INSERT INTO `habanos_presence` (`country_id`, `present`, `status`, `status_color`, `founded`, `ownership`, `hq`, `ceo`, `revenue`, `employees`, `factories`, `marques_officielles`, `distributeurs`, `description`, `festival`, `certifications`, `status_en`, `status_es`, `status_de`, `status_zh`, `status_ar`, `ownership_en`, `ownership_es`, `ownership_de`, `ownership_zh`, `ownership_ar`, `description_en`, `description_es`, `description_de`, `description_zh`, `description_ar`, `festival_en`, `festival_es`, `festival_de`, `festival_zh`, `festival_ar`) VALUES
  ('brazil', '0', 'PRODUCTEUR NATIONAL HISTORIQUE', '#B8860B', '1873 (Dannemann)', 'Principalement Dannemann Cigarrenfabrik (groupe suisse)', 'São Gonçalo dos Campos, Bahia, Brésil', 'Groupe Dannemann (Suisse)', '~$120M USD (feuilles + cigares)', '5 000+ (secteur tabac Bahia)', '[{\"name\":\"Dannemann Cigarrenfabrik\",\"city\":\"São Félix da Cachoeira\",\"founded\":\"1873\",\"marques\":[\"Dannemann Moods\",\"Speciale\",\"Sumatra\"]},{\"name\":\"Suerdieck\",\"city\":\"Maragogipe\",\"founded\":\"1929\",\"marques\":[\"Suerdieck Cigarros\",\"Mata Fina raw export\"]}]', '[\"Dannemann\",\"Suerdieck\"]', '[{\"pays\":\"Europe\",\"distributeur\":\"Dannemann GmbH (Allemagne/Suisse)\"},{\"pays\":\"Monde entier\",\"distributeur\":\"Export feuilles Mata Fina vers manufactures premium\"}]', 'Le Brésil n\'a pas de représentation Habanos. Son influence mondiale repose sur le tabac Mata Fina de Bahia — le meilleur wrapper Maduro naturel du monde. Des marques comme Arturo Fuente Añejo, Padrón 1926 Maduro et CAO utilisent ce wrapper exclusivement. Domestiquement, Dannemann (marque nationale) est distribuée dans 80+ pays.', 'Salon du Tabac de Bahia — annuel', '[\"MAPA (Ministère de l\'Agriculture brésilien)\",\"AFUBRA (Association des planteurs)\"]', 'HISTORIC DOMESTIC PRODUCER', 'PRODUCTOR NACIONAL HISTÓRICO', 'HISTORISCHER INLANDSERZEUGER', '历史悠久的本国产地', 'منتج وطني عريق', 'Mainly Dannemann Cigarrenfabrik (Swiss group)', 'Principalmente Dannemann Cigarrenfabrik (grupo suizo)', 'Überwiegend Dannemann Cigarrenfabrik (Schweizer Gruppe)', '主要为 Dannemann Cigarrenfabrik（瑞士集团）', 'أساسًا دانيمان سيغارنفابريك (مجموعة سويسرية)', 'Brazil has no Habanos office. Its global influence rests on Bahia\'s Mata Fina tobacco — the finest natural Maduro wrapper in the world. Brands such as Arturo Fuente Añejo, Padrón 1926 Maduro and CAO use it exclusively. At home, the national brand Dannemann is distributed in more than 80 countries.', 'Brasil no tiene representación de Habanos. Su influencia mundial descansa en el tabaco Mata Fina de Bahía, la mejor capa Maduro natural del mundo. Marcas como Arturo Fuente Añejo, Padrón 1926 Maduro y CAO la usan en exclusiva. En el plano nacional, Dannemann se distribuye en más de 80 países.', 'Brasilien hat keine Habanos-Vertretung. Sein weltweiter Einfluss beruht auf dem Mata-Fina-Tabak aus Bahia — dem besten natürlichen Maduro-Deckblatt der Welt. Marken wie Arturo Fuente Añejo, Padrón 1926 Maduro und CAO verwenden es exklusiv. Im Inland wird die nationale Marke Dannemann in über 80 Länder geliefert.', '巴西没有哈瓦那雪茄代表处。其全球影响力源自巴伊亚的 Mata Fina 烟草——世界最佳天然 Maduro 茄衣。Arturo Fuente Añejo、Padrón 1926 Maduro 与 CAO 等品牌专用此茄衣。在本土，民族品牌 Dannemann 销往 80 多个国家。', 'لا يوجد في البرازيل تمثيل لهابانوس. يقوم نفوذها العالمي على تبغ ماتا فينا من باهيا — أفضل غلاف مادورو طبيعي في العالم. وتستخدمه حصريًا علامات مثل أرتورو فوينتي أنييخو وبادرون 1926 مادورو وCAO. محليًا، تُوزَّع العلامة الوطنية دانيمان في أكثر من 80 بلدًا.', 'Bahia Tobacco Show — annual', 'Salón del Tabaco de Bahía: anual', 'Tabakmesse Bahia — jährlich', '巴伊亚烟草展——每年举办', 'معرض التبغ في باهيا — سنويًا'),
  ('cameroon', '0', 'PRODUCTEUR DE WRAPPER EXCLUSIF', '#B8860B', 'Culture commerciale depuis 1910 (ère coloniale)', 'SCTC (Société Camerounaise du Tabac) + BAT Cameroun', 'Mungo, Cameroun', 'SCTC (actionnaire majoritaire : État camerounais)', '~$45M USD exportations wrapper', '3 000+ (saison de récolte)', '[{\"name\":\"SCTC — Domaine du Mont Cameroun\",\"city\":\"Mungo / Wouri\",\"founded\":\"1952\",\"marques\":[\"Wrapper Cameroon Shade exporté mondialement\"]}]', '[]', '[{\"pays\":\"USA\",\"distributeur\":\"General Cigar (contrat exclusif wrapper)\"},{\"pays\":\"Europe\",\"distributeur\":\"Scandinavian Tobacco Group\"}]', 'Le Cameroun ne possède pas de représentation Habanos et ne produit aucun cigare fini pour le marché international. Son unique contribution — mais elle est fondamentale — est le wrapper Cameroon, cultivé sur les flancs volcaniques du Mont Cameroun. Ce wrapper est parmi les plus recherchés au monde, utilisé notamment dans les Arturo Fuente Hemingway et les Oliva Serie G. La production est très limitée et fluctue selon les saisons des pluies.', 'Aucun festival cigar national', '[\"Certificat origine SCTC\",\"Contrôle phytosanitaire MINADER\"]', 'EXCLUSIVE WRAPPER PRODUCER', 'PRODUCTOR DE CAPA EXCLUSIVA', 'ERZEUGER EXKLUSIVER DECKBLÄTTER', '独家茄衣产地', 'منتج غلاف حصري', 'SCTC (Cameroon Tobacco Company) + BAT Cameroon', 'SCTC (Sociedad Camerunesa del Tabaco) + BAT Camerún', 'SCTC (Kamerunische Tabakgesellschaft) + BAT Kamerun', 'SCTC（喀麦隆烟草公司）+ BAT 喀麦隆', 'SCTC (الشركة الكاميرونية للتبغ) + BAT الكاميرون', 'Cameroon has no Habanos office and makes no finished cigars for the international market. Its single contribution — a fundamental one — is the Cameroon wrapper, grown on the volcanic slopes of Mount Cameroon. It is among the most sought-after wrappers in the world, notably in the Arturo Fuente Hemingway and the Oliva Serie G. Output is very limited and swings with the rainy seasons.', 'Camerún no tiene representación de Habanos ni fabrica puros acabados para el mercado internacional. Su única aportación, aunque fundamental, es la capa Cameroon, cultivada en las laderas volcánicas del monte Camerún. Es una de las capas más buscadas del mundo, presente en los Arturo Fuente Hemingway y los Oliva Serie G. La producción es muy limitada y varía con las estaciones de lluvias.', 'Kamerun hat keine Habanos-Vertretung und fertigt keine Zigarren für den Weltmarkt. Sein einziger — dafür grundlegender — Beitrag ist das Cameroon-Deckblatt von den vulkanischen Hängen des Kamerunbergs. Es zählt zu den begehrtesten Deckblättern der Welt, etwa in der Arturo Fuente Hemingway und der Oliva Serie G. Die Erzeugung ist sehr begrenzt und schwankt mit den Regenzeiten.', '喀麦隆没有哈瓦那雪茄代表处，也不为国际市场生产成品雪茄。其唯一却举足轻重的贡献是喀麦隆茄衣，产自喀麦隆火山的山坡。它是世界上最抢手的茄衣之一，见于 Arturo Fuente Hemingway 与 Oliva Serie G。产量极为有限，且随雨季波动。', 'لا يوجد في الكاميرون تمثيل لهابانوس ولا تُنتج سيجارًا جاهزًا للسوق الدولية. إسهامها الوحيد — وهو جوهري — غلاف الكاميرون المزروع على السفوح البركانية لجبل الكاميرون. وهو من أكثر الأغلفة طلبًا عالميًا، ويظهر في أرتورو فوينتي همنغواي وأوليفا سيري G. الإنتاج محدود جدًا ويتقلّب مع مواسم الأمطار.', 'No national cigar festival', 'Ningún festival nacional del puro', 'Kein nationales Zigarrenfestival', '无全国性雪茄节', 'لا يوجد مهرجان سيجار وطني'),
  ('cuba', '1', 'SIÈGE SOCIAL', '#C0401A', '1994 (successeur de Cubatabaco, fondé 1962)', 'État cubain (50%) + Imperial Brands PLC (50%)', 'La Havane, Cuba', 'Luis Sánchez-Harguindey Pardo de Vera', '~$500M USD annuels', '30 000+ (planteurs inclus)', '[{\"name\":\"El Laguito\",\"city\":\"La Havane\",\"founded\":\"1966\",\"marques\":[\"Cohiba\",\"Trinidad\"]},{\"name\":\"H. Upmann (Partagás)\",\"city\":\"La Havane\",\"founded\":\"1845\",\"marques\":[\"Partagás\",\"H. Upmann\",\"Bolivar\",\"Punch\",\"Ramón Allones\"]},{\"name\":\"Romeo y Julieta\",\"city\":\"La Havane\",\"founded\":\"1875\",\"marques\":[\"Romeo y Julieta\",\"Cuaba\",\"Quintero\",\"Belinda\"]},{\"name\":\"Francisco Donatién\",\"city\":\"Pinar del Río\",\"founded\":\"1961\",\"marques\":[\"Vegas Robaina\",\"Vegueros\"]},{\"name\":\"La Corona\",\"city\":\"La Havane\",\"founded\":\"1934\",\"marques\":[\"Montecristo\",\"Por Larrañaga\",\"Saint Luis Rey\"]}]', '[\"Cohiba\",\"Montecristo\",\"Partagás\",\"Romeo y Julieta\",\"H. Upmann\",\"Bolivar\",\"Trinidad\",\"Punch\",\"Diplomaticos\",\"San Cristóbal\",\"Cuaba\",\"Vegas Robaina\",\"Por Larrañaga\",\"Quintero\",\"Vegueros\",\"Ramón Allones\",\"Saint Luis Rey\"]', '[{\"pays\":\"Espagne\",\"distributeur\":\"Tabacalera S.A.U.\"},{\"pays\":\"France\",\"distributeur\":\"Altadis (Seita)\"},{\"pays\":\"Allemagne\",\"distributeur\":\"Arnold André / Habanos Deutschland\"},{\"pays\":\"Suisse\",\"distributeur\":\"Intertabak AG\"},{\"pays\":\"Royaume-Uni\",\"distributeur\":\"Hunters & Frankau\"},{\"pays\":\"Italie\",\"distributeur\":\"MST Srl\"},{\"pays\":\"Mexique\",\"distributeur\":\"Mardini Hermanos\"},{\"pays\":\"Japon\",\"distributeur\":\"Habanos Japan\"}]', 'Habanos S.A. est la plus grande société de distribution de cigares premium au monde. Elle commercialise l\'ensemble des marques cubaines à l\'international et contrôle l\'appellation d\'origine protégée \"Habanos\". L\'entreprise organise chaque année le Festival del Habano à La Havane — l\'événement mondial de référence pour les amateurs de cigares.', 'Festival del Habano — chaque février à La Havane (depuis 1999)', '[\"Denominación de Origen Protegida \\\"Habanos\\\"\",\"ISO 9001\",\"Cahier des charges plantation Vuelta Abajo\"]', 'HEADQUARTERS', 'SEDE SOCIAL', 'HAUPTSITZ', '总部', 'المقر الرئيسي', 'Cuban state (50%) + Imperial Brands PLC (50%)', 'Estado cubano (50 %) + Imperial Brands PLC (50 %)', 'Kubanischer Staat (50 %) + Imperial Brands PLC (50 %)', '古巴政府（50%）+ Imperial Brands PLC（50%）', 'الدولة الكوبية (50٪) + إمبريال براندز (50٪)', 'Habanos S.A. is the largest premium cigar distributor in the world. It markets every Cuban brand internationally and controls the protected designation of origin “Habanos”. Each year it stages the Festival del Habano in Havana — the world\'s reference event for cigar lovers.', 'Habanos S.A. es la mayor distribuidora de puros premium del mundo. Comercializa todas las marcas cubanas a escala internacional y controla la denominación de origen protegida «Habanos». Cada año organiza el Festival del Habano en La Habana, el evento mundial de referencia para los aficionados.', 'Habanos S.A. ist der größte Vertrieb für Premium-Zigarren weltweit. Das Unternehmen vermarktet sämtliche kubanischen Marken international und kontrolliert die geschützte Ursprungsbezeichnung „Habanos“. Jährlich richtet es das Festival del Habano in Havanna aus — das weltweite Referenzereignis für Zigarrenliebhaber.', 'Habanos S.A. 是全球最大的优质雪茄分销商，负责所有古巴品牌的国际销售，并掌管受保护原产地名称“Habanos”。公司每年在哈瓦那举办哈瓦那雪茄节，是雪茄爱好者的世界性标杆盛事。', 'هابانوس ش.م. هي أكبر شركة لتوزيع السيجار الفاخر في العالم. تسوّق جميع العلامات الكوبية دوليًا وتتحكم في تسمية المنشأ المحمية «هابانوس». وتنظّم سنويًا مهرجان الهابانو في هافانا، الحدث المرجعي عالميًا لعشّاق السيجار.', 'Festival del Habano — every February in Havana (since 1999)', 'Festival del Habano: cada febrero en La Habana (desde 1999)', 'Festival del Habano — jeden Februar in Havanna (seit 1999)', '哈瓦那雪茄节——每年二月于哈瓦那举行（始于 1999 年）', 'مهرجان الهابانو — كل فبراير في هافانا (منذ 1999)'),
  ('dominican', '1', 'PREMIER EXPORTATEUR MONDIAL', '#C0401A', 'Industrie installée 1960s–1970s', 'Manufactures familiales et groupes internationaux', 'Santiago de los Caballeros, Rép. Dominicaine', 'Carlos Fuente Jr. (A. Fuente), Ernst Schneider (Davidoff), Litto Gomez (LFD)…', '~$1.2B USD exportations annuelles (record mondial)', '35 000+ (secteur tabac)', '[{\"name\":\"Tabacalera A. Fuente & Cia\",\"city\":\"Santiago\",\"founded\":\"1980\",\"marques\":[\"Opus X\",\"Hemingway\",\"Añejo\",\"Don Carlos\",\"Cuesta Rey\"]},{\"name\":\"Manufactura de Tabacos S.A. (MATASA)\",\"city\":\"Santiago\",\"founded\":\"1967\",\"marques\":[\"Avo\",\"Davidoff\",\"Juan Clemente\",\"Zino Platinum\"]},{\"name\":\"La Flor Dominicana S.A.\",\"city\":\"Santiago\",\"founded\":\"1996\",\"marques\":[\"LFD Double Ligero\",\"Air Bender\",\"Cameroon Especiale\"]},{\"name\":\"General Cigar Dominicana\",\"city\":\"La Romana\",\"founded\":\"1968\",\"marques\":[\"Macanudo\",\"Punch DOM\",\"Partagás DOM\"]},{\"name\":\"Consolidated Cigar Corp.\",\"city\":\"Santiago\",\"founded\":\"1970\",\"marques\":[\"H. Upmann DOM\",\"Romeo y Julieta DOM\",\"Montecristo White\"]}]', '[\"Arturo Fuente\",\"Davidoff\",\"La Flor Dominicana\",\"Macanudo\",\"Ashton\",\"Avo\",\"Romeo y Julieta (DOM)\",\"H. Upmann (DOM)\",\"Cubao\",\"La Gloria Cubana (DOM)\"]', '[{\"pays\":\"USA\",\"distributeur\":\"General Cigar Co. / Altadis USA / STG\"},{\"pays\":\"Europe\",\"distributeur\":\"Oettinger Davidoff AG / Scandinavian Tobacco\"},{\"pays\":\"Monde entier\",\"distributeur\":\"90+ importateurs agréés\"}]', 'La République Dominicaine est le premier exportateur mondial de cigares en valeur. La région de Santiago abrite une concentration unique de manufactures de premier plan. L\'appellation \"Cibao\" pour le tabac dominicain est reconnue internationalement. Le pays produit des cigares pour presque toutes les grandes marques mondiales.', 'ProCigar Festival — chaque février à Santiago (depuis 2006)', '[\"Denominación de Origen \\\"Cibao\\\"\",\"ProCigar (Association des fabricants dominicains)\",\"DICOEX export certification\"]', 'WORLD\'S LARGEST EXPORTER', 'PRIMER EXPORTADOR MUNDIAL', 'WELTGRÖSSTER EXPORTEUR', '全球第一大出口国', 'أكبر مصدّر عالمي', 'Family workshops and international groups', 'Manufacturas familiares y grupos internacionales', 'Familienmanufakturen und internationale Konzerne', '家族工坊与国际集团', 'مصانع عائلية ومجموعات دولية', 'The Dominican Republic is the world\'s largest cigar exporter by value. The Santiago region holds a unique concentration of leading manufacturers. The “Cibao” appellation for Dominican tobacco is recognised internationally. The country rolls cigars for almost every major brand in the world.', 'La República Dominicana es el primer exportador mundial de puros en valor. La región de Santiago concentra un número único de manufacturas de primer nivel. La denominación «Cibao» para el tabaco dominicano goza de reconocimiento internacional. El país produce puros para casi todas las grandes marcas del mundo.', 'Die Dominikanische Republik ist wertmäßig der größte Zigarrenexporteur der Welt. Die Region Santiago vereint eine einzigartige Dichte führender Manufakturen. Die Bezeichnung „Cibao“ für dominikanischen Tabak ist international anerkannt. Das Land fertigt Zigarren für nahezu alle großen Marken.', '多米尼加共和国是按金额计的全球第一大雪茄出口国。圣地亚哥地区汇聚了众多顶尖厂商。多米尼加烟草的“Cibao”名号享有国际声誉。该国为全球几乎所有大品牌代工雪茄。', 'جمهورية الدومينيكان أكبر مصدّر للسيجار في العالم من حيث القيمة. تضم منطقة سانتياغو تجمّعًا فريدًا لكبرى المصانع. وتحظى تسمية «سيباو» للتبغ الدومينيكي باعتراف دولي. تنتج البلاد سيجارًا لمعظم العلامات الكبرى في العالم.', 'ProCigar Festival — every February in Santiago (since 2006)', 'ProCigar Festival: cada febrero en Santiago (desde 2006)', 'ProCigar Festival — jeden Februar in Santiago (seit 2006)', 'ProCigar 雪茄节——每年二月于圣地亚哥举行（始于 2006 年）', 'مهرجان بروسيغار — كل فبراير في سانتياغو (منذ 2006)'),
  ('ecuador', '0', 'FOURNISSEUR MONDIAL DE WRAPPER', '#B8860B', 'Culture développée 1970s–1980s', 'Plantations de manufactures étrangères (Plasencia, General Cigar, STG)', 'Los Ríos / Guayas, Équateur', 'N/A — principalement culture de feuilles brutes', '~$180M USD exportations feuilles', '8 000+ (secteur agricole)', '[{\"name\":\"Plasencia Ecuador\",\"city\":\"Los Ríos\",\"founded\":\"1990s\",\"marques\":[\"Fournisseur universel de wrapper\"]},{\"name\":\"CETABACO\",\"city\":\"Guayas\",\"founded\":\"1980s\",\"marques\":[\"Connecticut Shade Ecuador\",\"Ecuador Habano\"]},{\"name\":\"General Cigar Ecuador\",\"city\":\"Los Ríos\",\"founded\":\"1990s\",\"marques\":[\"Wrapper pour Macanudo, CAO, Partagás…\"]}]', '[]', '[{\"pays\":\"Monde entier\",\"distributeur\":\"Export de feuilles brutes vers manufactures USA/RD/Nicaragua\"}]', 'L\'Équateur n\'a pas de représentation Habanos et ne produit pas de cigares finis sous sa propre marque — il est exclusivement un fournisseur mondial de feuilles de wrapper. La couverture nuageuse naturelle de la région remplace l\'ombrage artificiel utilisé au Connecticut, produisant un wrapper Connecticut Shade de qualité identique à moindre coût. Presque toutes les grandes manufactures mondiales utilisent du wrapper équatorien.', 'Aucun festival cigar national', '[\"Certificat phytosanitaire AGROCALIDAD\",\"PROECUADOR export label\"]', 'GLOBAL WRAPPER SUPPLIER', 'PROVEEDOR MUNDIAL DE CAPA', 'WELTWEITER DECKBLATTLIEFERANT', '全球茄衣供应国', 'مورّد عالمي لأوراق الغلاف', 'Plantations of foreign manufacturers (Plasencia, General Cigar, STG)', 'Plantaciones de manufacturas extranjeras (Plasencia, General Cigar, STG)', 'Plantagen ausländischer Manufakturen (Plasencia, General Cigar, STG)', '外国厂商的种植园（Plasencia、General Cigar、STG）', 'مزارع لمصانع أجنبية (بلاسينسيا، جنرال سيغار، STG)', 'Ecuador has no Habanos office and makes no finished cigars under its own name — it is purely a global supplier of wrapper leaf. The region\'s natural cloud cover replaces the artificial shading used in Connecticut, yielding a Connecticut Shade wrapper of equal quality at lower cost. Almost every major manufacturer in the world uses Ecuadorian wrapper.', 'Ecuador no tiene representación de Habanos ni fabrica puros acabados con marca propia: es exclusivamente un proveedor mundial de hoja de capa. La cobertura nubosa natural de la región sustituye al sombreado artificial de Connecticut y produce una capa Connecticut Shade de igual calidad a menor coste. Casi todas las grandes manufacturas del mundo emplean capa ecuatoriana.', 'Ecuador hat keine Habanos-Vertretung und stellt keine fertigen Zigarren unter eigenem Namen her — es ist reiner Weltlieferant von Deckblatt. Die natürliche Wolkendecke der Region ersetzt die künstliche Beschattung Connecticuts und liefert ein gleichwertiges Connecticut-Shade-Deckblatt zu geringeren Kosten. Nahezu alle großen Manufakturen verwenden ecuadorianisches Deckblatt.', '厄瓜多尔没有哈瓦那雪茄代表处，也不以自有品牌生产成品雪茄，而是纯粹的全球茄衣供应国。当地天然云层取代了康涅狄格的人工遮阴，以更低成本产出品质相当的康涅狄格遮阴茄衣。全球几乎所有大型厂商都使用厄瓜多尔茄衣。', 'لا يوجد في الإكوادور تمثيل لهابانوس ولا تُنتج سيجارًا جاهزًا باسمها — فهي مورّد عالمي لأوراق الغلاف حصرًا. يحلّ الغطاء السحابي الطبيعي محلّ التظليل الاصطناعي المستخدم في كونيتيكت، فينتج غلاف كونيتيكت شيد بالجودة نفسها وبكلفة أقل. تكاد كل المصانع الكبرى في العالم تستخدم الغلاف الإكوادوري.', 'No national cigar festival', 'Ningún festival nacional del puro', 'Kein nationales Zigarrenfestival', '无全国性雪茄节', 'لا يوجد مهرجان سيجار وطني'),
  ('honduras', '1', 'REPRÉSENTATION RÉGIONALE', '#B8860B', 'Industrie établie 1960s', 'HATSA (Honduras American Tobacco S.A.) + indépendants', 'Danlí, Honduras', 'Multiple — Alan Rubin (Alec Bradley), Cano Ozgener legacy (CAO)…', '~$220M USD exportations annuelles', '12 000+ (secteur tabac)', '[{\"name\":\"HATSA\",\"city\":\"Danlí\",\"founded\":\"1968\",\"marques\":[\"Hoyo de Monterrey HN\",\"Punch HN\",\"Excalibur\"]},{\"name\":\"Raices Cubanas S.A.\",\"city\":\"Danlí\",\"founded\":\"1990s\",\"marques\":[\"Alec Bradley Prensado\",\"Black Market\",\"Tempus\"]},{\"name\":\"Tabacos Rancho Jamastran\",\"city\":\"Jamastran\",\"founded\":\"1962\",\"marques\":[\"Camacho Corojo\",\"Triple Maduro\",\"American Barrel-Aged\"]},{\"name\":\"STG Honduras (Altadis)\",\"city\":\"Danlí\",\"founded\":\"1980s\",\"marques\":[\"CAO\",\"Baccarat\",\"Henri Wintermans HN\"]}]', '[\"Alec Bradley\",\"CAO Honduras\",\"Camacho\",\"Punch (HN)\",\"Hoyo de Monterrey (HN)\",\"Baccarat\",\"Excalibur\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Altadis USA / General Cigar / STG\"},{\"pays\":\"Europe\",\"distributeur\":\"Scandinavian Tobacco Group\"}]', 'Le Honduras est le quatrième producteur mondial de cigares premium. La Vallée de Jamastran, à 900m d\'altitude, produit certains des tabacs Corojo les plus puissants hors de Cuba. L\'industrie hondurienne est largement contrôlée par des groupes américains et européens.', 'Salon de tabac — intégré aux foires régionales d\'Amérique Centrale', '[\"Denominación de Origen \\\"Jamastran\\\"\",\"Honduras Cigar Association (HCA)\"]', 'REGIONAL REPRESENTATION', 'REPRESENTACIÓN REGIONAL', 'REGIONALE VERTRETUNG', '区域代表处', 'تمثيل إقليمي', 'HATSA (Honduras American Tobacco S.A.) + independents', 'HATSA (Honduras American Tobacco S.A.) + independientes', 'HATSA (Honduras American Tobacco S.A.) + Unabhängige', 'HATSA（洪都拉斯美洲烟草公司）与独立厂商', 'هاتسا (هندوراس أمريكان توباكو) + مستقلون', 'Honduras is the world\'s fourth-largest producer of premium cigars. The Jamastran Valley, at 900 m, grows some of the most powerful Corojo tobaccos outside Cuba. The Honduran industry is largely controlled by American and European groups.', 'Honduras es el cuarto productor mundial de puros premium. El valle de Jamastrán, a 900 m de altitud, da algunos de los tabacos Corojo más potentes fuera de Cuba. La industria hondureña está controlada en gran medida por grupos estadounidenses y europeos.', 'Honduras ist der viertgrößte Erzeuger von Premium-Zigarren weltweit. Das Jamastran-Tal auf 900 m bringt einige der kräftigsten Corojo-Tabake außerhalb Kubas hervor. Die honduranische Industrie liegt weitgehend in den Händen amerikanischer und europäischer Konzerne.', '洪都拉斯是全球第四大优质雪茄产地。海拔 900 米的哈马斯特兰河谷出产古巴以外最浓烈的 Corojo 烟草。洪都拉斯产业大体由美欧集团掌控。', 'هندوراس رابع أكبر منتج للسيجار الفاخر في العالم. ينتج وادي خاماستران على ارتفاع 900 م بعضًا من أقوى أنواع تبغ كوروخو خارج كوبا. وتسيطر مجموعات أمريكية وأوروبية إلى حد بعيد على الصناعة الهندوراسية.', 'Tobacco show — part of Central America\'s regional fairs', 'Salón del tabaco: integrado en las ferias regionales de Centroamérica', 'Tabakmesse — Teil der regionalen Messen Mittelamerikas', '烟草展——并入中美洲区域展会', 'معرض التبغ — ضمن المعارض الإقليمية لأمريكا الوسطى'),
  ('indonesia', '0', 'FOURNISSEUR DE WRAPPER SUMATRA', '#B8860B', 'Culture commerciale Deli Sumatra depuis 1863', 'PT Djarum / PT Gudang Garam / PT Sadhana Arif Nusa', 'Medan, Sumatra Nord, Indonésie', 'Multiple — conglomérats locaux', '~$220M USD exportations feuilles', '20 000+ (secteur plantation)', '[{\"name\":\"PT Sadhana Arif Nusa\",\"city\":\"Deli, Sumatra Nord\",\"founded\":\"1977\",\"marques\":[\"Deli Sumatra Wrapper — export cigarillos Europe\"]},{\"name\":\"PT Djarum\",\"city\":\"Kudus, Java\",\"founded\":\"1951\",\"marques\":[\"Djarum Black\",\"La Finca Cigars\"]}]', '[\"Café Crème\",\"Henri Wintermans\",\"Agio\"]', '[{\"pays\":\"Europe\",\"distributeur\":\"Royal Agio Cigars (Pays-Bas)\"},{\"pays\":\"Monde entier\",\"distributeur\":\"Export wrapper brut vers 40+ manufactures\"}]', 'L\'Indonésie ne possède pas de représentation Habanos. Sa contribution principale est le wrapper Deli Sumatra, cultivé sur des sols volcaniques depuis les plantations hollandaises du XIXème siècle. Ce wrapper — terreux, légèrement épicé — est l\'un des plus utilisés pour les cigarillos et cigares milieu de gamme en Europe.', 'Aucun festival cigar international', '[\"Badan Karantina (quarantaine agricole)\",\"Export license Kementerian Pertanian\"]', 'SUMATRA WRAPPER SUPPLIER', 'PROVEEDOR DE CAPA SUMATRA', 'LIEFERANT VON SUMATRA-DECKBLATT', '苏门答腊茄衣供应国', 'مورّد غلاف سومطرة', 'PT Djarum / PT Gudang Garam / PT Sadhana Arif Nusa', 'PT Djarum / PT Gudang Garam / PT Sadhana Arif Nusa', 'PT Djarum / PT Gudang Garam / PT Sadhana Arif Nusa', 'PT Djarum／PT Gudang Garam／PT Sadhana Arif Nusa', 'بي تي دجاروم / بي تي غودانغ غارام / بي تي سادانا عارف نوسا', 'Indonesia has no Habanos office. Its main contribution is the Deli Sumatra wrapper, grown on volcanic soils since the Dutch plantations of the nineteenth century. Earthy and lightly spiced, it is among the most widely used wrappers for cigarillos and mid-range cigars in Europe.', 'Indonesia no tiene representación de Habanos. Su aportación principal es la capa Deli Sumatra, cultivada en suelos volcánicos desde las plantaciones holandesas del siglo XIX. Terrosa y ligeramente especiada, es una de las más usadas para cigarritos y puros de gama media en Europa.', 'Indonesien hat keine Habanos-Vertretung. Sein wichtigster Beitrag ist das Deli-Sumatra-Deckblatt, seit den niederländischen Plantagen des 19. Jahrhunderts auf Vulkanböden angebaut. Erdig und leicht würzig, zählt es zu den meistgenutzten Deckblättern für Cigarillos und Zigarren der Mittelklasse in Europa.', '印度尼西亚没有哈瓦那雪茄代表处。其主要贡献是德利苏门答腊茄衣，自 19 世纪荷兰种植园以来种植于火山土壤。这种带土质、微辛香的茄衣，是欧洲小雪茄与中端雪茄最常用的茄衣之一。', 'لا يوجد في إندونيسيا تمثيل لهابانوس. إسهامها الأساسي هو غلاف دلي سومطرة، المزروع في تربة بركانية منذ المزارع الهولندية في القرن التاسع عشر. وهو غلاف ترابي خفيف التوابل، من أكثر الأغلفة استخدامًا للسيجار الصغير والسيجار المتوسط في أوروبا.', 'No international cigar festival', 'Ningún festival internacional del puro', 'Kein internationales Zigarrenfestival', '无国际雪茄节', 'لا يوجد مهرجان سيجار دولي'),
  ('mexico', '0', 'NICHE PREMIUM — WRAPPER SAN ANDRÉS', '#3D6B4A', '1963 (Te Amo / famille Turrent)', 'Famille Turrent (Tabacos San Andrés)', 'San Andrés Tuxtla, Veracruz, Mexique', 'Famille Turrent (4ème génération)', '~$85M USD exportations', '2 000+', '[{\"name\":\"Tabacos San Andrés S.A.\",\"city\":\"San Andrés Tuxtla\",\"founded\":\"1963\",\"marques\":[\"Te Amo\",\"Santa Clara 1830\",\"export wrapper San Andrés\"]},{\"name\":\"Hoja de México\",\"city\":\"Los Tuxtlas\",\"founded\":\"2000s\",\"marques\":[\"CAO Black wrapper\",\"Onyx wrapper\"]}]', '[\"Te Amo\",\"Santa Clara 1830\",\"Onyx\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Te Amo USA / General Cigar\"},{\"pays\":\"Monde entier\",\"distributeur\":\"Export wrapper San Andrés Maduro Negro\"}]', 'Le Mexique n\'a pas de représentation Habanos mais détient un terroir unique avec les \"terres noires\" volcaniques de San Andrés Tuxtla. Le wrapper San Andrés Maduro Negro est le plus naturellement foncé du monde — il fermente naturellement sans additifs, développant une douceur et une onctuosité incomparables. La famille Turrent contrôle l\'essentiel de la production depuis 4 générations.', 'Aucun festival cigar international', '[\"Denominación de Origen \\\"San Andrés Tuxtla\\\"\",\"SAGARPA Mexico\"]', 'PREMIUM NICHE — SAN ANDRÉS WRAPPER', 'NICHO PREMIUM: CAPA SAN ANDRÉS', 'PREMIUM-NISCHE — SAN-ANDRÉS-DECKBLATT', '高端小众——圣安德烈斯茄衣', 'فئة فاخرة متخصصة — غلاف سان أندريس', 'Turrent family (Tabacos San Andrés)', 'Familia Turrent (Tabacos San Andrés)', 'Familie Turrent (Tabacos San Andrés)', '图伦特家族（Tabacos San Andrés）', 'عائلة توران (تاباكوس سان أندريس)', 'Mexico has no Habanos office but holds a unique terroir in the volcanic “black earth” of San Andrés Tuxtla. The San Andrés Maduro Negro wrapper is the darkest in the world by nature — it ferments without additives, developing an incomparable sweetness and silkiness. The Turrent family has controlled most of the output for four generations.', 'México no tiene representación de Habanos, pero posee un terruño único con las «tierras negras» volcánicas de San Andrés Tuxtla. La capa San Andrés Maduro Negro es la más oscura del mundo de forma natural: fermenta sin aditivos y desarrolla una dulzura y una untuosidad incomparables. La familia Turrent controla la mayor parte de la producción desde hace cuatro generaciones.', 'Mexiko hat keine Habanos-Vertretung, besitzt aber mit der vulkanischen „Schwarzerde“ von San Andrés Tuxtla ein einzigartiges Terroir. Das Deckblatt San Andrés Maduro Negro ist das von Natur aus dunkelste der Welt — es fermentiert ohne Zusätze und entwickelt eine unvergleichliche Süße und Geschmeidigkeit. Die Familie Turrent kontrolliert den Großteil der Erzeugung seit vier Generationen.', '墨西哥没有哈瓦那雪茄代表处，却拥有圣安德烈斯图斯特拉火山“黑土”这一独特风土。San Andrés Maduro Negro 茄衣是世界上天然色泽最深的茄衣，无添加自然发酵，形成无与伦比的甘甜与丝滑。图伦特家族四代掌控着大部分产量。', 'لا يوجد في المكسيك تمثيل لهابانوس، لكنها تملك تروا فريدًا في «الأتربة السوداء» البركانية بسان أندريس توكستلا. غلاف سان أندريس مادورو نيغرو هو الأغمق طبيعيًا في العالم — يتخمّر دون إضافات فيكتسب حلاوة ونعومة لا تُضاهى. وتسيطر عائلة توران على معظم الإنتاج منذ أربعة أجيال.', 'No international cigar festival', 'Ningún festival internacional del puro', 'Kein internationales Zigarrenfestival', '无国际雪茄节', 'لا يوجد مهرجان سيجار دولي'),
  ('nicaragua', '1', 'PÔLE MONDIAL INDÉPENDANT', '#C0401A', 'Industrie développée 1960s–1990s', 'Principalement manufactures familiales indépendantes', 'Estelí, Nicaragua', 'Multiple — Jorge Padrón (Padrón), Janny Garcia (My Father), Willy Herrera (Drew Estate)…', '~$850M USD exportations annuelles', '25 000+ (secteur tabac)', '[{\"name\":\"Tabacos Valle de Jalapa (TAVASA)\",\"city\":\"Jalapa\",\"founded\":\"1970s\",\"marques\":[\"Padrón 1926\",\"Padrón 1964\",\"Family Reserve\"]},{\"name\":\"My Father Cigars S.A.\",\"city\":\"Estelí\",\"founded\":\"2006\",\"marques\":[\"My Father\",\"Le Bijou 1922\",\"Flor de Las Antillas\"]},{\"name\":\"Plasencia Cigars S.A.\",\"city\":\"Estelí\",\"founded\":\"1970s\",\"marques\":[\"Plasencia Cosecha\",\"Alma del Fuego\",\"Reserva Original\"]},{\"name\":\"Drew Estate S.A.\",\"city\":\"Estelí\",\"founded\":\"1999\",\"marques\":[\"Liga Privada No.9\",\"T52\",\"Acid\",\"Herrera Estelí\"]},{\"name\":\"Oliva Cigar Co.\",\"city\":\"Estelí\",\"founded\":\"1995\",\"marques\":[\"Serie V\",\"Melanio\",\"Serie G\"]}]', '[\"Padrón\",\"My Father\",\"Oliva\",\"Drew Estate\",\"Plasencia\",\"Rocky Patel\",\"Perdomo\",\"Joya de Nicaragua\",\"AJ Fernandez\",\"Mombacho\",\"La Flor de Selva\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Distribution directe (marchés spécialisés)\"},{\"pays\":\"Europe\",\"distributeur\":\"Altadis / Scandinavian Tobacco Group\"},{\"pays\":\"Canada\",\"distributeur\":\"Imperial Tobacco Canada\"}]', 'Le Nicaragua est devenu le premier producteur mondial de cigares premium en volume, dépassant Cuba et la République Dominicaine. L\'industrie se concentre autour d\'Estelí — la \"Capitale du Cigare\" — où se trouvent les manufactures des plus grandes maisons. Contrairement à Cuba, l\'industrie nicaraguayenne est entièrement privée et très compétitive.', 'Nicaragua Cigars Event — festival annuel à Estelí', '[\"Denominación de Origen \\\"Jalapa\\\"\",\"Denominación de Origen \\\"Estelí\\\"\",\"CAAN (Cámara Nicaragüense de Tabaco)\"]', 'INDEPENDENT GLOBAL HUB', 'POLO MUNDIAL INDEPENDIENTE', 'UNABHÄNGIGES WELTZENTRUM', '独立的全球枢纽', 'قطب عالمي مستقل', 'Mainly independent family workshops', 'Principalmente manufacturas familiares independientes', 'Überwiegend unabhängige Familienmanufakturen', '主要为独立家族工坊', 'أساسًا مصانع عائلية مستقلة', 'Nicaragua has become the world\'s largest producer of premium cigars by volume, ahead of Cuba and the Dominican Republic. The industry clusters around Estelí — the “Cigar Capital” — home to the workshops of the greatest houses. Unlike Cuba\'s, the Nicaraguan industry is entirely private and fiercely competitive.', 'Nicaragua se ha convertido en el primer productor mundial de puros premium en volumen, por delante de Cuba y la República Dominicana. La industria se concentra en torno a Estelí, la «Capital del Puro», donde están las manufacturas de las grandes casas. A diferencia de Cuba, la industria nicaragüense es enteramente privada y muy competitiva.', 'Nicaragua ist mengenmäßig zum größten Erzeuger von Premium-Zigarren aufgestiegen, vor Kuba und der Dominikanischen Republik. Die Industrie ballt sich um Estelí — die „Zigarrenhauptstadt“ — mit den Manufakturen der größten Häuser. Anders als in Kuba ist die nicaraguanische Industrie vollständig privat und stark umkämpft.', '尼加拉瓜已成为按产量计的全球第一大优质雪茄产地，超过古巴与多米尼加。产业集中于“雪茄之都”埃斯特利，各大名厂在此设厂。与古巴不同，尼加拉瓜产业完全私营，竞争激烈。', 'أصبحت نيكاراغوا أكبر منتج للسيجار الفاخر في العالم من حيث الحجم، متجاوزةً كوبا وجمهورية الدومينيكان. تتركّز الصناعة حول إستيلي — «عاصمة السيجار» — حيث مصانع كبرى الدور. وخلافًا لكوبا، الصناعة النيكاراغوية خاصة بالكامل وشديدة التنافس.', 'Nicaragua Cigars Event — annual festival in Estelí', 'Nicaragua Cigars Event: festival anual en Estelí', 'Nicaragua Cigars Event — jährliches Festival in Estelí', '尼加拉瓜雪茄节——埃斯特利年度盛会', 'فعالية سيجار نيكاراغوا — مهرجان سنوي في إستيلي'),
  ('panama', '0', 'TERROIR ÉMERGENT', '#3D6B4A', 'Production premium lancée ~2000', 'Toraño Panama / El Hatillo (petites structures)', 'Chiriquí, Panama', 'Carlos Toraño (pionnier)', '~$12M USD', '500+', '[{\"name\":\"Toraño Panama\",\"city\":\"Volcán, Chiriquí\",\"founded\":\"2001\",\"marques\":[\"Carlos Toraño Exodus 1959\",\"Toraño Signature\"]}]', '[\"Carlos Toraño Panama\",\"La Palina Panama\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Distribution directe boutiques spécialisées\"}]', 'Le Panama n\'a pas de représentation Habanos. Son terroir volcanique de Chiriquí, à 1400m d\'altitude sur les flancs du Volcán Barú, est l\'un des plus prometteurs d\'Amérique Centrale. Les conditions climatiques — altitude, sol volcanique, hygrométrie — y créent un microclimate exceptionnel. L\'industrie est encore très artisanale et en développement.', 'Aucun festival cigar national', '[\"MIDA Panama (agriculture)\"]', 'EMERGING TERROIR', 'TERRUÑO EMERGENTE', 'AUFSTREBENDES TERROIR', '新兴风土产区', 'تروا صاعد', 'Toraño Panama / El Hatillo (small operations)', 'Toraño Panamá / El Hatillo (pequeñas estructuras)', 'Toraño Panama / El Hatillo (kleine Betriebe)', 'Toraño 巴拿马 / El Hatillo（小型企业）', 'تورانيو بنما / إل هاتيّو (منشآت صغيرة)', 'Panama has no Habanos office. Its volcanic Chiriquí terroir, at 1400 m on the slopes of Volcán Barú, is among the most promising in Central America. Altitude, volcanic soil and humidity combine into an exceptional microclimate. The industry remains largely artisanal and still developing.', 'Panamá no tiene representación de Habanos. Su terruño volcánico de Chiriquí, a 1400 m en las laderas del volcán Barú, es de los más prometedores de Centroamérica. Altitud, suelo volcánico e higrometría crean allí un microclima excepcional. La industria sigue siendo muy artesanal y está en desarrollo.', 'Panama hat keine Habanos-Vertretung. Sein vulkanisches Terroir in Chiriquí, auf 1400 m an den Hängen des Volcán Barú, zählt zu den vielversprechendsten Mittelamerikas. Höhe, Vulkanboden und Luftfeuchte ergeben ein außergewöhnliches Mikroklima. Die Industrie ist noch weitgehend handwerklich und im Aufbau.', '巴拿马没有哈瓦那雪茄代表处。其奇里基火山风土位于巴鲁火山山坡海拔 1400 米处，是中美洲最具潜力的产区之一。海拔、火山土与湿度共同造就了极佳的小气候。产业仍以手工为主，处于发展阶段。', 'لا يوجد في بنما تمثيل لهابانوس. تروا تشيريكي البركاني، على ارتفاع 1400 م على سفوح بركان بارو، من أوعد ما في أمريكا الوسطى. يجتمع الارتفاع والتربة البركانية والرطوبة في مناخ محلي استثنائي. ولا تزال الصناعة حرفية إلى حد بعيد وفي طور النمو.', 'No national cigar festival', 'Ningún festival nacional del puro', 'Kein nationales Zigarrenfestival', '无全国性雪茄节', 'لا يوجد مهرجان سيجار وطني'),
  ('philippines', '0', 'PRODUCTION HISTORIQUE', '#3D6B4A', '1782 (Tabacalera — monopole espagnol)', 'PMFTC (Philip Morris) + Tabacalera Philippines', 'Manille, Philippines', 'Multiple', '~$35M USD', '8 000+ (secteur tabac)', '[{\"name\":\"Tabacalera Philippines\",\"city\":\"Manille\",\"founded\":\"1782\",\"marques\":[\"Tabacalera Pilipinas\",\"Tabacalera Special Reserve\"]},{\"name\":\"La Flor de la Isabela\",\"city\":\"Isabela\",\"founded\":\"1960s\",\"marques\":[\"Purito Filipino\",\"La Flor artisanal\"]}]', '[\"Tabacalera\",\"La Flor de la Isabela\"]', '[{\"pays\":\"Philippines\",\"distributeur\":\"Marché domestique principalement\"},{\"pays\":\"Espagne\",\"distributeur\":\"Tabacalera España (liens historiques)\"}]', 'Les Philippines ne possèdent pas de représentation Habanos. L\'une des plus anciennes industries du tabac au monde (monopole espagnol depuis 1782), elle est aujourd\'hui sous-exploitée à l\'international. Le terroir de la Cagayan Valley a un réel potentiel premium qui reste largement inexploité. Le marché est principalement domestique.', 'Aucun festival cigar international', '[\"BPI Philippines (Bureau of Plant Industry)\",\"FDA Philippines\"]', 'HISTORIC PRODUCTION', 'PRODUCCIÓN HISTÓRICA', 'HISTORISCHE PRODUKTION', '历史悠久的生产', 'إنتاج عريق', 'PMFTC (Philip Morris) + Tabacalera Philippines', 'PMFTC (Philip Morris) + Tabacalera Philippines', 'PMFTC (Philip Morris) + Tabacalera Philippines', 'PMFTC（菲利普莫里斯）+ Tabacalera Philippines', 'PMFTC (فيليب موريس) + تاباكاليرا الفلبين', 'The Philippines has no Habanos office. One of the oldest tobacco industries in the world — a Spanish monopoly from 1782 — it is under-exploited internationally today. The Cagayan Valley terroir holds real premium potential that remains largely untapped. The market is mainly domestic.', 'Filipinas no tiene representación de Habanos. Una de las industrias tabaqueras más antiguas del mundo (monopolio español desde 1782), hoy está infraexplotada en el plano internacional. El terruño del valle de Cagayán tiene un potencial premium real, aún poco aprovechado. El mercado es principalmente nacional.', 'Die Philippinen haben keine Habanos-Vertretung. Eine der ältesten Tabakindustrien der Welt — seit 1782 spanisches Monopol — ist international heute unterausgeschöpft. Das Terroir des Cagayan-Tals birgt echtes Premium-Potenzial, das weitgehend ungenutzt bleibt. Der Markt ist überwiegend inländisch.', '菲律宾没有哈瓦那雪茄代表处。作为世界上最古老的烟草产业之一（1782 年起为西班牙专卖），如今在国际上开发不足。卡加延河谷风土具备真正的高端潜力，却基本未被发掘。市场以本土为主。', 'لا يوجد في الفلبين تمثيل لهابانوس. وهي من أقدم صناعات التبغ في العالم (احتكار إسباني منذ 1782)، غير أنها اليوم غير مستثمَرة دوليًا بما يكفي. ويحمل تروا وادي كاغايان إمكانات فاخرة حقيقية لا تزال غير مستغلّة إلى حد بعيد. والسوق محلية في معظمها.', 'No international cigar festival', 'Ningún festival internacional del puro', 'Kein internationales Zigarrenfestival', '无国际雪茄节', 'لا يوجد مهرجان سيجار دولي'),
  ('usa', '0', 'MARCHÉ ET PRODUCTEUR DE WRAPPER', '#B8860B', 'Culture sous voile depuis 1900 (Connecticut)', 'Swedish Match / Altadis USA / General Cigar', 'Richmond, Virginie (General Cigar HQ)', 'Peter Jung (Scandinavian Tobacco Group Americas)', '~$380M USD marché premium local', '15 000+ (industrie tabac Connecticut)', '[{\"name\":\"General Cigar Richmond\",\"city\":\"Richmond, VA\",\"founded\":\"1906\",\"marques\":[\"Macanudo\",\"Punch DOM\",\"CAO\"]},{\"name\":\"Altadis USA\",\"city\":\"Fort Lauderdale, FL\",\"founded\":\"1999 (fusion)\",\"marques\":[\"H. Upmann DOM\",\"Romeo y Julieta DOM\",\"Montecristo White\"]},{\"name\":\"Drew Estate (Swisher)\",\"city\":\"Jacksonville, FL\",\"founded\":\"1996\",\"marques\":[\"Liga Privada\",\"Acid\",\"Herrera Estelí\"]}]', '[\"General Cigar Portfolio\",\"Altadis USA Portfolio\"]', '[{\"pays\":\"USA\",\"distributeur\":\"Marché domestique — réseau de détaillants agréés nationwide\"}]', 'Les États-Unis sont le plus grand marché consommateur de cigares premium au monde. Le Connecticut Shade — cultivé sous voiles dans la Vallée du Connecticut depuis 1900 — est le wrapper le plus doux au monde, utilisé par Macanudo, Davidoff, Ashton et des dizaines d\'autres. L\'embargo sur Cuba (1962) a paradoxalement boosté les industries nicaraguayenne et dominicaine qui ont absorbé les maîtres torcedores cubains exilés.', 'IPCPR Trade Show (Big Smoke) — Las Vegas, annuel', '[\"FDA (Food and Drug Administration) — réglementation tabac\",\"USTC (United States Tobacco Council)\"]', 'MARKET AND WRAPPER PRODUCER', 'MERCADO Y PRODUCTOR DE CAPA', 'MARKT UND DECKBLATTERZEUGER', '市场与茄衣产地', 'سوق ومنتج لأوراق الغلاف', 'Swedish Match / Altadis USA / General Cigar', 'Swedish Match / Altadis USA / General Cigar', 'Swedish Match / Altadis USA / General Cigar', 'Swedish Match／Altadis USA／General Cigar', 'سويديش ماتش / ألتاديس الولايات المتحدة / جنرال سيغار', 'The United States is the largest consumer market for premium cigars in the world. Connecticut Shade — grown under cloth in the Connecticut Valley since 1900 — is the mildest wrapper in the world, used by Macanudo, Davidoff, Ashton and dozens of others. The Cuban embargo of 1962 paradoxically boosted the Nicaraguan and Dominican industries, which absorbed the exiled Cuban master torcedores.', 'Estados Unidos es el mayor mercado consumidor de puros premium del mundo. El Connecticut Shade, cultivado bajo telas en el valle del Connecticut desde 1900, es la capa más suave del mundo, usada por Macanudo, Davidoff, Ashton y decenas más. El embargo a Cuba (1962) impulsó paradójicamente a las industrias nicaragüense y dominicana, que acogieron a los maestros torcedores cubanos exiliados.', 'Die Vereinigten Staaten sind der größte Verbrauchermarkt für Premium-Zigarren weltweit. Connecticut Shade — seit 1900 unter Tüchern im Connecticut-Tal angebaut — ist das mildeste Deckblatt der Welt und wird von Macanudo, Davidoff, Ashton und Dutzenden weiteren verwendet. Das Kuba-Embargo von 1962 beflügelte paradoxerweise die nicaraguanische und die dominikanische Industrie, die die exilierten kubanischen Meistertorcedores aufnahmen.', '美国是全球最大的优质雪茄消费市场。自 1900 年起在康涅狄格河谷帐布下种植的康涅狄格遮阴烟，是世界上最柔和的茄衣，为 Macanudo、Davidoff、Ashton 等数十个品牌所用。1962 年的古巴禁运反而促成了尼加拉瓜与多米尼加产业的兴起，两国接纳了流亡的古巴卷制大师。', 'الولايات المتحدة أكبر سوق استهلاكية للسيجار الفاخر في العالم. وكونيتيكت شيد — المزروع تحت الأقمشة في وادي كونيتيكت منذ 1900 — هو أنعم غلاف في العالم، وتستخدمه ماكانودو ودافيدوف وآشتون وعشرات غيرها. وقد عزّز الحظر على كوبا (1962) بشكل مفارق صناعتَي نيكاراغوا والدومينيكان اللتين استوعبتا كبار الملفّين الكوبيين المنفيين.', 'IPCPR Trade Show (Big Smoke) — Las Vegas, annual', 'IPCPR Trade Show (Big Smoke): Las Vegas, anual', 'IPCPR Trade Show (Big Smoke) — Las Vegas, jährlich', 'IPCPR 贸易展（Big Smoke）——拉斯维加斯，每年举办', 'معرض IPCPR (بيغ سموك) — لاس فيغاس، سنويًا');
INSERT INTO `feuilles` (`id`, `name`, `country_id`, `emploi`, `genese`, `culture`, `caracteres`, `notes`, `pairings`, `created_at`, `updated_at`, `genese_en`, `genese_es`, `genese_de`, `genese_zh`, `genese_ar`, `culture_en`, `culture_es`, `culture_de`, `culture_zh`, `culture_ar`, `caracteres_en`, `caracteres_es`, `caracteres_de`, `caracteres_zh`, `caracteres_ar`, `notes_en`, `notes_es`, `notes_de`, `notes_zh`, `notes_ar`, `pairings_en`, `pairings_es`, `pairings_de`, `pairings_zh`, `pairings_ar`, `emploi_en`, `emploi_es`, `emploi_de`, `emploi_zh`, `emploi_ar`) VALUES
  ('bresil-arapiraca', 'Arapiraca', 'brazil', 'Cape maduro', 'Celle-ci n\'est pas de Bahia mais de l\'État d\'Alagoas, dont la ville d\'Arapiraca est le centre du tabac brésilien depuis le début du XXe siècle.', 'Culture de plein soleil, comme les deux Mata. Le terroir d\'Alagoas donne une feuille sensiblement plus épaisse et plus grasse.', 'Sombre et huileuse, elle brûle régulièrement et laisse une cendre très blanche. Là où la Mata Fina va vers la fleur, elle va vers le chocolat et l\'épice — d\'où son emploi en cape maduro.', '[\"Chocolat\",\"Épices\",\"Terre sucrée\"]', '[\"Porto\",\"Café noir\",\"Chocolat au lait\"]', '2026-08-21 18:29:46', '2026-08-22 22:08:55', 'This one is not from Bahia but from the state of Alagoas, whose city of Arapiraca has been the hub of Brazilian tobacco since the early twentieth century.', 'Esta no es de Bahía sino del estado de Alagoas, cuya ciudad de Arapiraca es el centro del tabaco brasileño desde principios del siglo XX.', 'Dieses stammt nicht aus Bahia, sondern aus dem Bundesstaat Alagoas, dessen Stadt Arapiraca seit dem frühen 20. Jahrhundert das Zentrum des brasilianischen Tabaks ist.', '这一种并非来自巴伊亚，而是阿拉戈斯州；该州的阿拉皮拉卡市自二十世纪初便是巴西烟草的中心。', 'هذه ليست من باهيا بل من ولاية ألاغواس، التي تُعدّ مدينتها أراپيراكا مركز التبغ البرازيلي منذ مطلع القرن العشرين.', 'Sun-grown, like both Matas. The Alagoas ground yields a noticeably thicker, oilier leaf.', 'Cultivo a pleno sol, como las dos Mata. El terruño de Alagoas da una hoja sensiblemente más gruesa y más grasa.', 'Sonnenanbau wie bei beiden Matas. Der Boden von Alagoas bringt ein merklich dickeres, öligeres Blatt hervor.', '与两种 Mata 一样为全日照种植。阿拉戈斯的风土使叶片明显更厚、更油润。', 'تُزرع في الشمس الكاملة، مثل الماتا بنوعيها. وتربة ألاغواس تعطي ورقة أسمك وأكثر دهنية بوضوح.', 'Dark and oily, it burns evenly and leaves a strikingly white ash. Where Mata Fina goes towards flowers, it goes towards chocolate and spice — hence its use as a maduro wrapper.', 'Oscura y grasa, arde de forma regular y deja una ceniza muy blanca. Allí donde la Mata Fina tira a la flor, ella tira al chocolate y a la especia: de ahí su uso como capa maduro.', 'Dunkel und ölig, brennt es gleichmäßig und hinterlässt eine auffällig weiße Asche. Wo Mata Fina zur Blume geht, geht es zu Schokolade und Würze — daher sein Einsatz als Maduro-Deckblatt.', '色深油润，燃烧均匀，落灰极白。Mata Fina 走向花香，它则走向巧克力与辛香——故用作 maduro 茄衣。', 'داكنة ودهنية، تحترق بانتظام وتترك رمادًا شديد البياض. وحيث تميل ماتا فينا إلى الزهر، تميل هي إلى الشوكولاتة والتوابل — ومن هنا استخدامها غلافَ مادورو.', '[\"Chocolate\",\"Spice\",\"Sweet earth\"]', '[\"Chocolate\",\"Especias\",\"Tierra dulce\"]', '[\"Schokolade\",\"Gewürze\",\"Süße Erde\"]', '[\"巧克力\",\"香料\",\"甜润土壤\"]', '[\"شوكولاتة\",\"توابل\",\"تراب حلو\"]', '[\"Port\",\"Black coffee\",\"Milk chocolate\"]', '[\"Oporto\",\"Café solo\",\"Chocolate con leche\"]', '[\"Portwein\",\"Schwarzer Kaffee\",\"Milchschokolade\"]', '[\"波特酒\",\"黑咖啡\",\"牛奶巧克力\"]', '[\"بورتو\",\"قهوة سوداء\",\"شوكولاتة بالحليب\"]', 'Maduro wrapper', 'Capa maduro', 'Maduro-Deckblatt', '马杜罗茄衣', 'غلاف مادورو'),
  ('bresil-mata-fina', 'Mata Fina', 'brazil', 'Cape et tripe', 'Elle vient du Recôncavo Baiano, la baie qui entoure Salvador. C\'est la souche d\'origine : tout le tabac sombre planté en Bahia en descend, et ce sont les microclimats et les façons de faire qui creusent ensuite les différences.', 'Culture de plein soleil, sous quelque 1 200 millimètres de pluie par an. C\'est cette eau abondante qui la distingue de sa voisine du nord, plus sèche.', 'Feuille fine au parfum agréable et au goût retenu, plutôt floral. Assez belle pour servir de cape, assez souple pour entrer dans la tripe — elle fait les deux.', '[\"Douceur\",\"Fleurs\",\"Bois clair\"]', '[\"Cachaça vieillie\",\"Café doux\",\"Fruits blancs\"]', '2026-08-21 18:29:46', '2026-08-22 22:08:55', 'It comes from the Recôncavo Baiano, the bay around Salvador. This is the original strain: all the dark tobacco planted in Bahia descends from it, and it is microclimate and practice that open up the differences afterwards.', 'Viene del Recôncavo Baiano, la bahía que rodea Salvador. Es la cepa de origen: todo el tabaco oscuro plantado en Bahía desciende de ella, y son los microclimas y las prácticas los que después abren las diferencias.', 'Sie stammt aus dem Recôncavo Baiano, der Bucht um Salvador. Sie ist die Ursprungssorte: Aller dunkle Tabak, der in Bahia gepflanzt wird, geht auf sie zurück — die Unterschiede entstehen erst durch Mikroklima und Anbauweise.', '它来自环绕萨尔瓦多的雷孔卡沃-巴伊亚诺。这是原始品系：巴伊亚所种的深色烟草皆源出于此，其后的差异则由小气候与农艺手法拉开。', 'تأتي من ريكونكافو باهيا، الخليج المحيط بسلفادور. وهي السلالة الأصل: كل التبغ الداكن المزروع في باهيا ينحدر منها، والفوارق تصنعها بعد ذلك المناخات المحلية وأساليب الزراعة.', 'Sun-grown, under some 1,200 millimetres of rain a year. It is this abundant water that sets it apart from its drier neighbour to the north.', 'Cultivo a pleno sol, bajo unos 1.200 milímetros de lluvia al año. Es esa agua abundante la que la distingue de su vecina del norte, más seca.', 'Sonnenanbau unter rund 1.200 Millimetern Regen im Jahr. Dieses reichliche Wasser unterscheidet sie von ihrer trockeneren Nachbarin im Norden.', '全日照种植，年降雨约 1200 毫米。正是这份充沛的水量，使它有别于更干燥的北方邻居。', 'تُزرع في الشمس الكاملة تحت نحو 1200 ملم من المطر سنويًا. وهذه المياه الوفيرة هي ما يميّزها عن جارتها الشمالية الأكثر جفافًا.', 'A fine leaf of pleasant scent and restrained, rather floral taste. Handsome enough to serve as a wrapper, supple enough to go into the filler — it does both.', 'Hoja fina de aroma agradable y sabor contenido, más bien floral. Lo bastante bella para servir de capa, lo bastante flexible para entrar en la tripa: hace ambas cosas.', 'Ein feines Blatt von angenehmem Duft und zurückhaltendem, eher blumigem Geschmack. Schön genug als Deckblatt, geschmeidig genug für die Einlage — es leistet beides.', '叶片纤薄，香气宜人，味道内敛而偏花香。既美观得足以作茄衣，又柔韧得可入茄芯——两者兼任。', 'ورقة رفيعة عطرة الرائحة، مذاقها متحفّظ يميل إلى الزهر. جميلة بما يكفي لتكون غلافًا، ليّنة بما يكفي لتدخل الحشوة — وهي تؤدي الدورين.', '[\"Sweetness\",\"Flowers\",\"Pale wood\"]', '[\"Dulzura\",\"Flores\",\"Madera clara\"]', '[\"Milde\",\"Blüten\",\"Helles Holz\"]', '[\"甘润\",\"花香\",\"浅色木质\"]', '[\"حلاوة\",\"زهور\",\"خشب فاتح\"]', '[\"Aged cachaça\",\"Mild coffee\",\"White fruit\"]', '[\"Cachaça añejada\",\"Café suave\",\"Frutas blancas\"]', '[\"Gereifter Cachaça\",\"Milder Kaffee\",\"Helle Früchte\"]', '[\"陈年卡莎萨\",\"淡咖啡\",\"白色水果\"]', '[\"كاشاسا معتّقة\",\"قهوة خفيفة\",\"فواكه بيضاء\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('bresil-mata-norte', 'Mata Norte', 'brazil', 'Tripe et sous-cape', 'Même berceau que la Mata Fina, le Recôncavo Baiano, et même souche à l\'origine. C\'est le climat du nord de la zone qui en a fait autre chose.', 'Plein soleil également, mais sous une pluie plus rare. Les feuilles sèchent ensuite à l\'air libre, et non sous abri — ce qui appuie leur caractère.', 'Plus corsée que la Mata Fina, elle sert à donner de la profondeur aux assemblages plutôt qu\'à les habiller. C\'est la feuille de la charpente, pas celle de la façade.', '[\"Corps\",\"Terre\",\"Épices\"]', '[\"Rhum agricole\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 18:29:46', '2026-08-22 22:08:55', 'The same cradle as Mata Fina, the Recôncavo Baiano, and the same strain to begin with. It is the climate of the northern edge that made it something else.', 'Misma cuna que la Mata Fina, el Recôncavo Baiano, y misma cepa en el origen. Es el clima del norte de la zona el que la convirtió en otra cosa.', 'Dieselbe Wiege wie Mata Fina, das Recôncavo Baiano, und ursprünglich dieselbe Sorte. Erst das Klima im Norden der Zone hat etwas anderes daraus gemacht.', '与 Mata Fina 同一摇篮——雷孔卡沃-巴伊亚诺，起初也是同一品系。是产区北部的气候使它成了另一回事。', 'المهد نفسه الذي نشأت فيه ماتا فينا، ريكونكافو باهيا، والسلالة نفسها في الأصل. لكنّ مناخ شمال المنطقة جعل منها شيئًا آخر.', 'Sun-grown as well, but under scarcer rain. The leaves then dry in the open air rather than under cover — which deepens their character.', 'También a pleno sol, pero con lluvia más escasa. Las hojas se secan luego al aire libre, y no bajo cubierto, lo que acentúa su carácter.', 'Ebenfalls Sonnenanbau, aber bei spärlicherem Regen. Die Blätter trocknen anschließend im Freien statt unter Dach — was ihren Charakter verstärkt.', '同样全日照，但雨水更少。叶片随后在露天而非棚下干燥——这加深了它的性格。', 'تُزرع في الشمس الكاملة أيضًا، لكن تحت مطر أشحّ. ثم تجفّ الأوراق في الهواء الطلق لا تحت مظلة — ما يعمّق طابعها.', 'Fuller-bodied than Mata Fina, it serves to give blends depth rather than to dress them. It is the leaf of the frame, not of the façade.', 'Más corpulenta que la Mata Fina, sirve para dar profundidad a las ligas más que para vestirlas. Es la hoja de la estructura, no la de la fachada.', 'Kräftiger als Mata Fina, dient es dazu, Mischungen Tiefe zu geben, statt sie zu kleiden. Es ist das Blatt des Gerüsts, nicht der Fassade.', '较 Mata Fina 更为浓厚，它的作用是为配方增添深度，而非为其披衣。这是骨架之叶，不是门面之叶。', 'أقوى قوامًا من ماتا فينا، تُستخدم لمنح الخلطات عمقًا لا لكسائها. إنها ورقة الهيكل، لا ورقة الواجهة.', '[\"Body\",\"Earth\",\"Spice\"]', '[\"Cuerpo\",\"Tierra\",\"Especias\"]', '[\"Körper\",\"Erde\",\"Gewürze\"]', '[\"厚度\",\"泥土\",\"香料\"]', '[\"قوام\",\"تراب\",\"توابل\"]', '[\"Rhum agricole\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron agrícola\",\"Café cargado\",\"Chocolate negro\"]', '[\"Rhum agricole\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"农业朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم زراعي\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Filler and binder', 'Tripa y capote', 'Einlage und Umblatt', '茄芯与茄套', 'حشوة ورابط'),
  ('cameroun-cape', 'Cape du Cameroun', 'cameroon', 'Cape', 'Des colons néerlandais apportent la semence de Sumatra en Afrique centrale au début du XXe siècle. Sous administration française, le monopole SEITA achète et exporte seul la récolte pendant des décennies, jusqu\'à son retrait de la région en 1993. La maison M. Meerapfel & Söhne négocie cette feuille depuis plus de cent vingt ans, et on lui attribue de l\'avoir sauvée de la disparition dans les années 1990.', 'Cultivée en PLEIN SOLEIL — ce qui est rare pour une cape : la couverture nuageuse régulière de la saison rend les toiles d\'ombrage inutiles. Les terres de la zone sont si riches qu\'elles ne demandent pas d\'engrais. La région à cape est à cheval sur l\'est du Cameroun, autour de Batouri, et la Centrafrique voisine où se trouvent les usines de traitement.', 'Feuille fine au grain marqué, recherchée autant pour sa rareté que pour son aspect. Elle habille des cigares roulés ailleurs — Honduras, République dominicaine, Nicaragua — auxquels elle donne sa signature plutôt que sa force.', '[\"Café\",\"Cacao\",\"Épices douces\"]', '[\"Café noir serré\",\"Rhum vieux\",\"Chocolat noir\"]', '2026-08-21 16:49:18', '2026-08-22 22:08:55', 'Dutch colonists brought Sumatra seed to Central Africa in the early twentieth century. Under French administration, the SEITA monopoly alone bought and exported the crop for decades, until it withdrew from the region in 1993. The house of M. Meerapfel & Söhne has traded this leaf for more than a hundred and twenty years, and is credited with saving it from disappearing in the 1990s.', 'Colonos neerlandeses llevaron la semilla de Sumatra a África central a principios del siglo XX. Bajo administración francesa, el monopolio SEITA compró y exportó en solitario la cosecha durante décadas, hasta su retirada de la región en 1993. La casa M. Meerapfel & Söhne negocia esta hoja desde hace más de ciento veinte años, y se le atribuye haberla salvado de la desaparición en los años noventa.', 'Niederländische Kolonisten brachten den Sumatra-Samen zu Beginn des 20. Jahrhunderts nach Zentralafrika. Unter französischer Verwaltung kaufte und exportierte allein das SEITA-Monopol jahrzehntelang die Ernte, bis es sich 1993 aus der Region zurückzog. Das Haus M. Meerapfel & Söhne handelt seit über hundertzwanzig Jahren mit diesem Blatt und gilt als dessen Retter vor dem Verschwinden in den 1990er Jahren.', '二十世纪初，荷兰殖民者将苏门答腊烟种带到中非。在法国管理时期，SEITA 专营公司数十年间独家收购并出口这里的烟叶，直到 1993 年撤出该地区。M. Meerapfel & Söhne 家族经营这种烟叶已逾一百二十年，业界普遍认为是他们让它在九十年代免于消失。', 'جلب المستعمرون الهولنديون بذور سومطرة إلى وسط أفريقيا مطلع القرن العشرين. وفي ظل الإدارة الفرنسية، احتكرت شركة SEITA وحدها شراء المحصول وتصديره عقودًا، حتى انسحابها من المنطقة عام 1993. وتتاجر دار M. Meerapfel & Söhne بهذه الورقة منذ أكثر من مئة وعشرين عامًا، ويُنسب إليها إنقاذها من الاندثار في التسعينيات.', 'Grown in FULL SUN — rare for a wrapper: the season\'s steady cloud cover makes shade cloth unnecessary. The soils here are so rich they need no fertiliser. The wrapper region straddles eastern Cameroon, around Batouri, and neighbouring Central African Republic, where the processing plants stand.', 'Cultivada a PLENO SOL — algo raro en una capa: la cobertura nubosa constante de la temporada hace innecesarias las telas de sombra. Las tierras de la zona son tan ricas que no requieren abono. La región de capa se reparte entre el este de Camerún, en torno a Batouri, y la vecina República Centroafricana, donde están las plantas de tratamiento.', 'In VOLLER SONNE angebaut — für ein Deckblatt ungewöhnlich: die beständige Wolkendecke der Saison macht Schattentücher überflüssig. Die Böden der Zone sind so reich, dass sie keinen Dünger brauchen. Das Deckblattgebiet erstreckt sich über den Osten Kameruns um Batouri und die benachbarte Zentralafrikanische Republik, wo die Aufbereitungsanlagen stehen.', '在全日照下种植——这对茄衣而言颇为罕见：产季稳定的云层使遮阳布成为多余。当地土壤极为肥沃，无需施肥。茄衣产区横跨喀麦隆东部的巴图里一带，以及设有加工厂的邻国中非共和国。', 'تُزرع في الشمس الكاملة — وهو أمر نادر بالنسبة إلى غلاف: فالغطاء السحابي المنتظم في الموسم يُغني عن أقمشة التظليل. وتربة المنطقة من الغنى بحيث لا تحتاج إلى أسمدة. وتمتد منطقة الغلاف بين شرق الكاميرون حول باتوري، وجمهورية أفريقيا الوسطى المجاورة حيث توجد مصانع المعالجة.', 'A fine leaf with pronounced tooth, sought after as much for its rarity as for its look. It dresses cigars rolled elsewhere — Honduras, the Dominican Republic, Nicaragua — lending them its signature rather than its strength.', 'Hoja fina de grano marcado, apreciada tanto por su rareza como por su aspecto. Viste puros liados en otros lugares — Honduras, República Dominicana, Nicaragua — a los que aporta su firma más que su fuerza.', 'Ein feines Blatt mit ausgeprägter Körnung, ebenso wegen seiner Seltenheit wie wegen seines Aussehens geschätzt. Es umhüllt Zigarren, die anderswo gerollt werden — Honduras, Dominikanische Republik, Nicaragua — und verleiht ihnen seine Handschrift statt seiner Stärke.', '叶片细薄而颗粒感分明，既因稀有也因外观而备受追捧。它包覆的是在别处卷制的雪茄——洪都拉斯、多米尼加、尼加拉瓜——赋予它们的是标志性风格，而非力度。', 'ورقة رفيعة ذات حبيبات بارزة، مرغوبة لندرتها بقدر ما هي مرغوبة لمظهرها. تكسو سيجارًا يُلف في أماكن أخرى — هندوراس وجمهورية الدومينيكان ونيكاراغوا — فتمنحه بصمتها لا قوتها.', '[\"Coffee\",\"Cocoa\",\"Sweet spice\"]', '[\"Café\",\"Cacao\",\"Especias dulces\"]', '[\"Kaffee\",\"Kakao\",\"Milde Gewürze\"]', '[\"咖啡\",\"可可\",\"甜香料\"]', '[\"قهوة\",\"كاكاو\",\"توابل حلوة\"]', '[\"Strong black coffee\",\"Aged rum\",\"Dark chocolate\"]', '[\"Café solo cargado\",\"Ron añejo\",\"Chocolate negro\"]', '[\"Starker schwarzer Kaffee\",\"Alter Rum\",\"Zartbitterschokolade\"]', '[\"浓黑咖啡\",\"陈年朗姆\",\"黑巧克力\"]', '[\"قهوة سوداء مركزة\",\"روم معتّق\",\"شوكولاتة داكنة\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('canaries-la-palma', 'Tabac de La Palma', 'canaries', 'Cape, sous-cape et tripe', 'La Palma cultive du tabac depuis le XVIIIe siècle, pour le commerce avec l\'Amérique. Mais c\'est au XIXe que la feuille prend son caractère : l\'effondrement de la cochenille ruine l\'île, et des palmeros partis chercher fortune à Cuba en rapportent les premières semences cubaines, avec les gestes appris là-bas.', 'Le climat subtropical océanique de l\'île convient à ces semences venues des Caraïbes. Il reste six artisans, d\'une vingtaine de fabriques que La Palma a comptées ; chaque puro y est roulé du début à la fin par une seule personne, comme à Cuba.', 'Une feuille cubaine par la graine et canarienne par la terre. C\'est le premier tour d\'une boucle que l\'atlas raconte déjà dans l\'autre sens : cent ans plus tard, après 1960, ce sont les familles cubaines qui viendront s\'installer ici.', '[\"Douceur\",\"Bois\",\"Note florale\"]', '[\"Vin de Malvoisie\",\"Café doux\",\"Fruits secs\"]', '2026-08-21 23:23:48', '2026-08-22 22:08:55', 'La Palma has grown tobacco since the eighteenth century, for trade with the Americas. But it was in the nineteenth that the leaf took its character: the collapse of cochineal ruined the island, and palmeros who had gone to seek their fortune in Cuba brought back the first Cuban seed, along with the craft learned there.', 'La Palma cultiva tabaco desde el siglo XVIII, para el comercio con América. Pero es en el XIX cuando la hoja adquiere su carácter: el hundimiento de la cochinilla arruina la isla, y palmeros que habían ido a buscar fortuna a Cuba traen las primeras semillas cubanas, junto con los saberes aprendidos allí.', 'La Palma baut seit dem 18. Jahrhundert Tabak an, für den Handel mit Amerika. Doch erst im 19. gewann das Blatt seinen Charakter: Der Zusammenbruch der Cochenille ruinierte die Insel, und Palmeros, die ihr Glück auf Kuba gesucht hatten, brachten die ersten kubanischen Samen mit — samt der dort erlernten Handgriffe.', '拉帕尔马自十八世纪起种植烟草，用于与美洲通商。但真正塑造这片烟叶性格的是十九世纪：胭脂虫业崩溃令全岛陷入困顿，而曾赴古巴谋生的帕尔马人带回了最早的古巴烟种，连同在那里习得的手艺。', 'تزرع لا بالما التبغ منذ القرن الثامن عشر، للتجارة مع الأمريكتين. لكن الورقة اكتسبت طابعها في القرن التاسع عشر: إذ أفقر انهيار القرمز الجزيرة، فعاد بعض أبنائها الذين قصدوا كوبا طلبًا للرزق بأول بذور كوبية، ومعها الحرفة التي تعلّموها هناك.', 'The island\'s subtropical oceanic climate suits these Caribbean seeds. Six artisans remain, of some twenty workshops La Palma once counted; each cigar is rolled from start to finish by a single person, as in Cuba.', 'El clima subtropical oceánico de la isla conviene a estas semillas llegadas del Caribe. Quedan seis artesanos, de la veintena de fábricas que La Palma llegó a tener; cada puro se lía de principio a fin por una sola persona, como en Cuba.', 'Das subtropisch-ozeanische Klima der Insel bekommt diesen karibischen Samen. Sechs Handwerker sind geblieben, von rund zwanzig Manufakturen, die La Palma einst zählte; jede Zigarre wird dort von einer einzigen Person von Anfang bis Ende gerollt, wie auf Kuba.', '岛上的亚热带海洋性气候适合这些来自加勒比的烟种。拉帕尔马昔日曾有约二十家作坊，如今只剩六位手艺人；每支雪茄自始至终由一人卷成，一如古巴。', 'يلائم مناخ الجزيرة شبه المداري المحيطي هذه البذور القادمة من الكاريبي. وقد بقي ستة حرفيين من نحو عشرين مصنعًا عرفتها لا بالما؛ ويُلفّ كل سيجار هناك من أوله إلى آخره على يد شخص واحد، كما في كوبا.', 'A leaf Cuban by seed and Canarian by soil. This is the first turn of a loop the atlas already tells the other way round: a century later, after 1960, it would be Cuban families who came to settle here.', 'Una hoja cubana por la semilla y canaria por la tierra. Es la primera vuelta de un círculo que el atlas ya cuenta en sentido inverso: cien años después, tras 1960, serán las familias cubanas las que vengan a instalarse aquí.', 'Ein Blatt, kubanisch durch den Samen, kanarisch durch den Boden. Das ist die erste Runde eines Kreises, den der Atlas bereits andersherum erzählt: Hundert Jahre später, nach 1960, werden kubanische Familien hierherkommen, um sich niederzulassen.', '就烟种而言它是古巴的，就土地而言它是加那利的。这是一个循环的第一圈——本图册已讲过它的反向：一百年后，1960 年之后，轮到古巴家族前来此地落脚。', 'ورقة كوبية بالبذرة، كناريّة بالتربة. هذه هي الدورة الأولى لحلقة يرويها الأطلس في الاتجاه المعاكس: فبعد مئة عام، عقب 1960، ستأتي العائلات الكوبية لتستقرّ هنا.', '[\"Mildness\",\"Wood\",\"Floral note\"]', '[\"Suavidad\",\"Madera\",\"Nota floral\"]', '[\"Milde\",\"Holz\",\"Blumige Note\"]', '[\"柔顺\",\"木质\",\"花香\"]', '[\"نعومة\",\"خشب\",\"لمسة زهرية\"]', '[\"Malvasia wine\",\"Mild coffee\",\"Dried fruit\"]', '[\"Vino de Malvasía\",\"Café suave\",\"Frutos secos\"]', '[\"Malvasier\",\"Milder Kaffee\",\"Trockenfrüchte\"]', '[\"玛尔维萨葡萄酒\",\"淡咖啡\",\"果干\"]', '[\"نبيذ المالفازيا\",\"قهوة خفيفة\",\"فواكه مجففة\"]', 'Wrapper, binder and filler', 'Capa, capote y tripa', 'Deckblatt, Umblatt und Einlage', '茄衣、茄套与茄芯', 'غلاف ورابط وحشوة'),
  ('cuba-corojo', 'Corojo', 'cuba', 'Cape', 'Une création datée : 1947, par Diego Rodríguez, et expressément destinée à faire des capes. Elle a régné sur les habanos pendant un demi-siècle avant qu\'une maladie ne la chasse des champs cubains.', 'Culture sous toile d\'ombrage, comme toute feuille destinée à la cape. Son défaut n\'était pas au champ mais dans sa constitution : elle attrapait tout, et les récoltes se perdaient.', 'Cape fine et régulière, dont le nom a survécu à la plante : on le retrouve au Honduras et dans le Corojo 99 cubain, sa descendance résistante.', '[\"Épices\",\"Cèdre\",\"Poivre\"]', '[\"Rhum vieux\",\"Café noir\",\"Cacao\"]', '2026-08-21 19:39:07', '2026-08-22 22:08:55', 'A dated creation: 1947, by Diego Rodríguez, and expressly meant to make wrappers. It reigned over habanos for half a century before disease drove it from Cuban fields.', 'Una creación fechada: 1947, por Diego Rodríguez, y destinada expresamente a hacer capas. Reinó sobre los habanos durante medio siglo antes de que una enfermedad la expulsara de los campos cubanos.', 'Eine datierte Schöpfung: 1947, von Diego Rodríguez, und ausdrücklich für Deckblätter bestimmt. Ein halbes Jahrhundert lang beherrschte sie die Habanos, bis eine Krankheit sie von Kubas Feldern vertrieb.', '一项有确切年份的育成：1947 年，由 Diego Rodríguez 培育，专为制作茄衣而生。它统治哈瓦那雪茄半个世纪，直到一场病害将它逐出古巴的田野。', 'ابتكار مؤرَّخ: عام 1947، على يد دييغو رودريغيز، ومخصّص صراحةً لصناعة الأغلفة. ساد على الهابانوس نصف قرن قبل أن يطرده مرضٌ من حقول كوبا.', 'Grown under shade cloth, like any leaf meant for a wrapper. Its flaw was not in the field but in its make-up: it caught everything, and harvests were lost.', 'Cultivo bajo tela de sombra, como toda hoja destinada a la capa. Su defecto no estaba en el campo sino en su constitución: lo cogía todo, y las cosechas se perdían.', 'Anbau unter Schattentuch, wie bei jedem Blatt, das zum Deckblatt bestimmt ist. Ihr Mangel lag nicht im Feld, sondern in ihrer Konstitution: Sie fing sich alles ein, und die Ernten gingen verloren.', '在遮阳布下种植，一如所有备作茄衣的烟叶。它的缺陷不在田间而在体质：什么病都招，收成因此损失。', 'تُزرع تحت قماش التظليل، كأي ورقة مخصّصة للغلاف. ولم يكن عيبها في الحقل بل في بنيتها: كانت تلتقط كل شيء، فتضيع المحاصيل.', 'A fine, even wrapper whose name outlived the plant: it turns up in Honduras and in Cuba\'s Corojo 99, its disease-resistant offspring.', 'Capa fina y regular cuyo nombre sobrevivió a la planta: reaparece en Honduras y en el Corojo 99 cubano, su descendencia resistente.', 'Ein feines, gleichmäßiges Deckblatt, dessen Name die Pflanze überlebt hat: Man findet ihn in Honduras und im kubanischen Corojo 99, seiner widerstandsfähigen Nachkommenschaft.', '茄衣细腻均匀，其名比植株更长命：它出现在洪都拉斯，也出现在古巴抗病的后代 Corojo 99 之中。', 'غلاف رفيع متجانس، بقي اسمه بعد فناء النبتة: نجده في هندوراس وفي الكوروخو 99 الكوبي، ذريّته المقاومة.', '[\"Spice\",\"Cedar\",\"Pepper\"]', '[\"Especias\",\"Cedro\",\"Pimienta\"]', '[\"Gewürze\",\"Zeder\",\"Pfeffer\"]', '[\"香料\",\"雪松\",\"胡椒\"]', '[\"توابل\",\"أرز\",\"فلفل\"]', '[\"Aged rum\",\"Black coffee\",\"Cocoa\"]', '[\"Ron añejo\",\"Café solo\",\"Cacao\"]', '[\"Alter Rum\",\"Schwarzer Kaffee\",\"Kakao\"]', '[\"陈年朗姆\",\"黑咖啡\",\"可可\"]', '[\"روم معتّق\",\"قهوة سوداء\",\"كاكاو\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('cuba-criollo', 'Criollo', 'cuba', 'Tripe et sous-cape', 'Le mot signifie « semence native », et c\'est tout son propos : cette plante est réputée présente sur l\'île au moment où Colomb y débarque. Toutes les variétés cubaines qui ont suivi en descendent de près ou de loin.', 'Cultivée en plein soleil pour la tripe, et la même souche passe sous la toile quand on lui demande une cape. C\'est l\'usage, plus que la plante, qui décide.', 'Feuille de fond plutôt que de façade : elle porte le goût de l\'assemblage sans chercher à l\'habiller. Sa réputation tient à son ancienneté autant qu\'à son caractère.', '[\"Terre\",\"Cuir\",\"Note boisée\"]', '[\"Rhum cubain\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 19:39:07', '2026-08-22 22:08:55', 'The word means \"native seed\", and that is the whole point: the plant is held to have been on the island when Columbus landed. Every Cuban variety since descends from it, closely or distantly.', 'La palabra significa «semilla nativa», y en eso está todo: se tiene por cierto que la planta ya estaba en la isla cuando desembarcó Colón. Todas las variedades cubanas posteriores descienden de ella, de cerca o de lejos.', 'Das Wort bedeutet „einheimischer Samen\", und darum geht es: Die Pflanze soll bereits auf der Insel gewesen sein, als Kolumbus landete. Alle späteren kubanischen Sorten stammen von ihr ab, näher oder ferner.', '这个词意为「本地烟种」，其要义尽在于此：据信哥伦布登岛之时，此株已在。此后所有古巴品种皆或近或远地由它而来。', 'الكلمة تعني «البذرة المحلية»، وفي ذلك كل المعنى: يُعتقد أن النبتة كانت في الجزيرة حين رسا كولومبوس. وكل الأصناف الكوبية اللاحقة تنحدر منها، من قريب أو بعيد.', 'Sun-grown for filler, and the same strain goes under cloth when a wrapper is wanted. It is the use, more than the plant, that decides.', 'Cultivada a pleno sol para la tripa, y la misma cepa pasa bajo la tela cuando se le pide capa. Es el uso, más que la planta, quien decide.', 'Für die Einlage sonnengewachsen, und dieselbe Sorte geht unter das Tuch, wenn man ein Deckblatt will. Es entscheidet die Verwendung, nicht die Pflanze.', '作茄芯时全日照种植，同一品系若要用作茄衣便移入棚下。决定的是用途，而非植株本身。', 'تُزرع في الشمس الكاملة للحشوة، والسلالة نفسها تنتقل تحت القماش حين يُراد منها غلاف. الاستعمال هو الذي يقرّر، لا النبتة.', 'A leaf of substance rather than of surface: it carries the blend\'s taste without seeking to dress it. Its standing owes as much to its age as to its character.', 'Hoja de fondo más que de fachada: lleva el sabor de la liga sin pretender vestirla. Su reputación se debe tanto a su antigüedad como a su carácter.', 'Ein Blatt des Fundaments, nicht der Fassade: Es trägt den Geschmack der Mischung, ohne sie kleiden zu wollen. Sein Ansehen verdankt es seinem Alter ebenso wie seinem Charakter.', '这是底子之叶，而非门面之叶：它承载配方的味道，却不图为其披衣。其声誉既来自性格，也来自资历。', 'ورقة أساس لا ورقة واجهة: تحمل مذاق الخلطة دون أن تسعى إلى كسائها. وسمعتها تعود إلى قِدَمها بقدر ما تعود إلى طابعها.', '[\"Earth\",\"Leather\",\"Woody note\"]', '[\"Tierra\",\"Cuero\",\"Nota amaderada\"]', '[\"Erde\",\"Leder\",\"Holzige Note\"]', '[\"泥土\",\"皮革\",\"木质气息\"]', '[\"تراب\",\"جلد\",\"لمسة خشبية\"]', '[\"Cuban rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron cubano\",\"Café cargado\",\"Chocolate negro\"]', '[\"Kubanischer Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"古巴朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم كوبي\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Filler and binder', 'Tripa y capote', 'Einlage und Umblatt', '茄芯与茄套', 'حشوة ورابط'),
  ('cuba-habano-2000', 'Habano 2000', 'cuba', 'Cape', 'Elle naît d\'une catastrophe. À la fin des années 1970, le moho azul — un champignon — arrive à Cuba et détruit la production. Les agronomes croisent le Corojo avec Bell 61-10, un tabac de cigarette, et retiennent la troisième hybridation. On l\'écrit aussi « Habana 2000 » : les deux graphies circulent.', 'Cultivée sous toile, comme le Corojo dont elle prend la place. Toute sa raison d\'être est là : tenir debout face à la maladie qui avait emporté sa devancière.', 'On lui a demandé l\'aspect et le goût du Corojo avec sa résistance en plus, et c\'est ce qu\'elle donne. Une cape de remplacement qui a fini par s\'imposer pour elle-même.', '[\"Épices douces\",\"Bois\",\"Cuir\"]', '[\"Rhum ambré\",\"Café au lait\",\"Fruits secs\"]', '2026-08-21 19:39:07', '2026-08-22 22:08:55', 'It was born of a disaster. In the late 1970s blue mould — a fungus — reached Cuba and destroyed the crop. Agronomists crossed Corojo with Bell 61-10, a cigarette tobacco, and kept the third hybridisation. It is also written \"Habana 2000\": both spellings circulate.', 'Nace de una catástrofe. A finales de los años setenta el moho azul —un hongo— llega a Cuba y destruye la producción. Los agrónomos cruzan el Corojo con Bell 61-10, un tabaco de cigarrillo, y retienen la tercera hibridación. También se escribe «Habana 2000»: ambas grafías circulan.', 'Sie entstand aus einer Katastrophe. Ende der 1970er Jahre erreichte der Blauschimmel — ein Pilz — Kuba und vernichtete die Ernte. Agronomen kreuzten Corojo mit Bell 61-10, einem Zigarettentabak, und behielten die dritte Hybridisierung. Man schreibt sie auch „Habana 2000\": beide Schreibweisen sind im Umlauf.', '它诞生于一场灾难。1970 年代末，霉霜病——一种真菌——传入古巴，摧毁了产量。农学家将 Corojo 与卷烟烟草 Bell 61-10 杂交，保留了第三代杂交种。它也写作「Habana 2000」：两种拼法皆在流通。', 'وُلدت من كارثة. في أواخر السبعينيات وصل العفن الأزرق — وهو فطر — إلى كوبا فدمّر الإنتاج. فهجّن المهندسون الزراعيون الكوروخو مع Bell 61-10، وهو تبغ سجائر، واحتفظوا بالتهجين الثالث. وتُكتب أيضًا «هابانا 2000»: فالكتابتان متداولتان.', 'Grown under cloth, like the Corojo it replaces. Its whole reason for being lies there: to stand up to the disease that carried off its predecessor.', 'Cultivada bajo tela, como el Corojo al que sustituye. Toda su razón de ser está ahí: aguantar frente a la enfermedad que se llevó a su antecesora.', 'Unter Tuch angebaut wie der Corojo, den sie ersetzt. Ihr ganzer Daseinsgrund liegt darin: der Krankheit standzuhalten, die ihre Vorgängerin dahinraffte.', '如它所取代的 Corojo 一样在棚下种植。它存在的全部理由就在于此：顶住那场夺走前辈的病害。', 'تُزرع تحت القماش، مثل الكوروخو الذي حلّت محلّه. وكل سبب وجودها هناك: أن تصمد أمام المرض الذي أودى بسابقتها.', 'It was asked for the look and taste of Corojo with resistance added, and that is what it gives. A stand-in wrapper that ended up standing on its own.', 'Se le pidió el aspecto y el sabor del Corojo con la resistencia añadida, y es lo que da. Una capa de sustitución que acabó imponiéndose por sí misma.', 'Von ihr verlangte man Aussehen und Geschmack des Corojo, dazu die Widerstandskraft — und genau das liefert sie. Ein Ersatzdeckblatt, das sich am Ende aus eigenem Recht durchsetzte.', '人们要求它兼具 Corojo 的外观与风味，外加抗病力，它做到了。一片本为替补的茄衣，最终凭自身立住了脚。', 'طُلب منها مظهر الكوروخو ومذاقه مع المقاومة زيادةً، وهذا ما تقدّمه. غلافٌ بديل انتهى به الأمر أن يفرض نفسه بذاته.', '[\"Sweet spice\",\"Wood\",\"Leather\"]', '[\"Especias dulces\",\"Madera\",\"Cuero\"]', '[\"Milde Gewürze\",\"Holz\",\"Leder\"]', '[\"甜香料\",\"木质\",\"皮革\"]', '[\"توابل حلوة\",\"خشب\",\"جلد\"]', '[\"Amber rum\",\"Café au lait\",\"Dried fruit\"]', '[\"Ron ámbar\",\"Café con leche\",\"Frutos secos\"]', '[\"Bernsteinfarbener Rum\",\"Milchkaffee\",\"Trockenfrüchte\"]', '[\"琥珀朗姆\",\"欧蕾咖啡\",\"果干\"]', '[\"روم كهرماني\",\"قهوة بالحليب\",\"فواكه مجففة\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('dominicaine-olor', 'Olor Dominicano', 'dominican', 'Sous-cape', 'La seule des trois qui soit née ici : c\'est l\'unique semence proprement dominicaine, et son nom dit ce qu\'on lui demande — « olor », l\'odeur.', 'Cultivée dans les terres du Cibao comme le Piloto, mais pour un autre usage : on la veut souple et régulière plutôt que puissante.', 'Feuille de tenue : elle enveloppe la tripe et la maintient, sans imposer son goût. C\'est la sous-cape de la plupart des cigares dominicains.', '[\"Douceur\",\"Foin\",\"Note florale\"]', '[\"Thé noir\",\"Café doux\",\"Vin blanc sec\"]', '2026-08-21 19:56:32', '2026-08-22 22:08:55', 'The only one of the three born here: it is the single genuinely Dominican seed, and its name says what is asked of it — \"olor\", scent.', 'La única de las tres nacida aquí: es la única semilla propiamente dominicana, y su nombre dice lo que se le pide: «olor».', 'Als einzige der drei hier entstanden: Sie ist der einzige genuin dominikanische Samen, und ihr Name sagt, was man von ihr verlangt — „olor\", der Duft.', '三者之中唯一诞生于此者：它是真正意义上唯一的多米尼加本地烟种，其名即道出人们对它的期待——「olor」，香气。', 'الوحيدة بين الثلاث التي وُلدت هنا: إنها البذرة الدومينيكية الأصيلة الوحيدة، واسمها يقول ما يُطلب منها — «olor»، أي الرائحة.', 'Grown in Cibao soil like Piloto, but for another purpose: it is wanted supple and even rather than powerful.', 'Cultivada en las tierras del Cibao como el Piloto, pero para otro uso: se la quiere flexible y regular más que potente.', 'Auf Cibao-Boden angebaut wie Piloto, aber für einen anderen Zweck: Man will sie geschmeidig und gleichmäßig, nicht kräftig.', '与 Piloto 同样种植于西宝的土地，用途却不同：人们要的是柔韧均匀，而非强劲。', 'تُزرع في أراضي سيباو مثل البيلوتو، لكن لغرض آخر: يُراد لها الليونة والانتظام لا القوة.', 'A leaf of structure: it wraps the filler and holds it, without imposing its taste. It is the binder of most Dominican cigars.', 'Hoja de sostén: envuelve la tripa y la mantiene, sin imponer su sabor. Es el capote de la mayoría de los puros dominicanos.', 'Ein Blatt des Halts: Es umschließt die Einlage und hält sie, ohne seinen Geschmack aufzudrängen. Es ist das Umblatt der meisten dominikanischen Zigarren.', '这是承托之叶：它包裹并固定茄芯，却不强加自己的味道。它是多数多米尼加雪茄的茄套。', 'ورقة تماسك: تلفّ الحشوة وتمسكها دون أن تفرض مذاقها. وهي الرابط في معظم السيجار الدومينيكي.', '[\"Mildness\",\"Hay\",\"Floral note\"]', '[\"Suavidad\",\"Heno\",\"Nota floral\"]', '[\"Milde\",\"Heu\",\"Blumige Note\"]', '[\"柔顺\",\"干草\",\"花香\"]', '[\"نعومة\",\"قش\",\"لمسة زهرية\"]', '[\"Black tea\",\"Mild coffee\",\"Dry white wine\"]', '[\"Té negro\",\"Café suave\",\"Vino blanco seco\"]', '[\"Schwarzer Tee\",\"Milder Kaffee\",\"Trockener Weißwein\"]', '[\"红茶\",\"淡咖啡\",\"干白葡萄酒\"]', '[\"شاي أسود\",\"قهوة خفيفة\",\"نبيذ أبيض جاف\"]', 'Binder', 'Capote', 'Umblatt', '茄套', 'رابط'),
  ('dominicaine-piloto-cubano', 'Piloto Cubano', 'dominican', 'Tripe', 'Une semence de la Vuelta Abajo, sortie de Cuba en 1962 dans des enveloppes bourrées de coton. On attribue généralement à Carlos Toraño père de l\'avoir amenée sur l\'île voisine. La même rupture qui a dispersé les familles cubaines a donc aussi déplacé leurs graines.', 'Elle a trouvé son terrain dans la vallée du Cibao, au nord du pays : beaucoup de soleil, et des brises d\'après-midi qui empêchent les plantations de surchauffer.', 'C\'est la feuille de force des assemblages dominicains, celle qu\'on mêle aux autres pour donner du goût plutôt que de la tenue. Sa filiation cubaine s\'entend.', '[\"Corps\",\"Terre\",\"Épices\"]', '[\"Rhum dominicain\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 19:56:32', '2026-08-22 22:08:55', 'A Vuelta Abajo seed, taken out of Cuba in 1962 in envelopes stuffed with cotton. Carlos Toraño Sr. is generally credited with bringing it to the neighbouring island. The same rupture that scattered Cuban families moved their seed as well.', 'Una semilla de Vuelta Abajo, sacada de Cuba en 1962 en sobres rellenos de algodón. Suele atribuirse a Carlos Toraño padre haberla llevado a la isla vecina. La misma ruptura que dispersó a las familias cubanas desplazó también sus semillas.', 'Ein Samen aus der Vuelta Abajo, 1962 in mit Watte gefüllten Umschlägen aus Kuba gebracht. Carlos Toraño senior wird gemeinhin zugeschrieben, ihn auf die Nachbarinsel gebracht zu haben. Derselbe Bruch, der kubanische Familien zerstreute, versetzte auch ihr Saatgut.', '来自下维尔塔的烟种，1962 年装在塞满棉花的信封里带出古巴。一般认为是老 Carlos Toraño 将它带到了邻岛。那场使古巴家族流散的断裂，也让他们的种子迁徙。', 'بذرة من فويلتا أباخو، أُخرجت من كوبا عام 1962 في مظاريف محشوّة بالقطن. ويُنسب عادةً إلى كارلوس تورانيو الأب أنه جلبها إلى الجزيرة المجاورة. فالقطيعة نفسها التي شتّتت العائلات الكوبية نقلت بذورها أيضًا.', 'It found its ground in the Cibao valley, in the north of the country: plenty of sun, and afternoon breezes that keep the plantations from overheating.', 'Encontró su terreno en el valle del Cibao, al norte del país: mucho sol y brisas de la tarde que impiden que las plantaciones se recalienten.', 'Ihren Boden fand sie im Cibao-Tal im Norden des Landes: viel Sonne und Nachmittagsbrisen, die die Pflanzungen vor Überhitzung bewahren.', '它在该国北部的西宝谷找到了归宿：阳光充足，午后的微风又使种植园不致过热。', 'وجدت أرضها في وادي سيباو شمال البلاد: شمس وفيرة، ونسائم بعد الظهر تمنع المزارع من فرط الحرارة.', 'It is the strength leaf of Dominican blends, the one mixed in for taste rather than structure. Its Cuban lineage can be heard.', 'Es la hoja de fuerza de las ligas dominicanas, la que se mezcla con las demás para dar sabor más que sostén. Su filiación cubana se nota.', 'Sie ist das Kraftblatt der dominikanischen Mischungen, jenes, das man beimengt für Geschmack, nicht für Halt. Ihre kubanische Abstammung ist herauszuschmecken.', '它是多米尼加配方中的力量之叶，掺入是为了味道而非结构。其古巴血统听得出来。', 'إنها ورقة القوة في الخلطات الدومينيكية، تُمزج بغيرها لأجل المذاق لا لأجل التماسك. ونسبها الكوبي مسموع.', '[\"Body\",\"Earth\",\"Spice\"]', '[\"Cuerpo\",\"Tierra\",\"Especias\"]', '[\"Körper\",\"Erde\",\"Gewürze\"]', '[\"厚度\",\"泥土\",\"香料\"]', '[\"قوام\",\"تراب\",\"توابل\"]', '[\"Dominican rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron dominicano\",\"Café cargado\",\"Chocolate negro\"]', '[\"Dominikanischer Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"多米尼加朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم دومينيكي\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Filler', 'Tripa', 'Einlage', '茄芯', 'حشوة'),
  ('dominicaine-san-vicente', 'San Vicente', 'dominican', 'Sous-cape et tripe', 'Une variation du Piloto Cubano, et donc une petite-fille de la Vuelta Abajo. Elle s\'est fixée dans le sud du pays, loin du Cibao où sa devancière s\'était installée.', 'Culture du sud dominicain. Le déplacement a suffi à l\'adoucir : c\'est le même sang que le Piloto, dans un autre climat.', 'Plus douce que son aînée, d\'une texture souple et d\'un goût crémeux. Elle sert de sous-cape autant que de tripe, là où le Piloto reste dans la tripe.', '[\"Douceur\",\"Crème\",\"Bois clair\"]', '[\"Café au lait\",\"Rhum blanc\",\"Fruits secs\"]', '2026-08-21 19:56:32', '2026-08-22 22:08:55', 'A variation on Piloto Cubano, and thus a granddaughter of the Vuelta Abajo. It settled in the south of the country, far from the Cibao where its forebear had taken root.', 'Una variación del Piloto Cubano, y por tanto nieta de Vuelta Abajo. Se fijó en el sur del país, lejos del Cibao donde se había instalado su antecesora.', 'Eine Abwandlung des Piloto Cubano und damit eine Enkelin der Vuelta Abajo. Sie hat sich im Süden des Landes festgesetzt, fern vom Cibao, wo ihre Vorgängerin heimisch wurde.', 'Piloto Cubano 的一个变种，因而是下维尔塔的孙辈。它扎根于该国南部，远离其先辈落脚的西宝谷。', 'تنويعة على البيلوتو كوبانو، ومن ثمّ حفيدة لفويلتا أباخو. استقرّت في جنوب البلاد، بعيدًا عن سيباو حيث ترسّخت سالفتها.', 'Grown in the Dominican south. The move alone was enough to soften it: the same blood as Piloto, in another climate.', 'Cultivo del sur dominicano. El traslado bastó para suavizarla: es la misma sangre que el Piloto, en otro clima.', 'Anbau im dominikanischen Süden. Der Ortswechsel allein genügte, sie zu mildern: dasselbe Blut wie Piloto, in einem anderen Klima.', '种植于多米尼加南部。仅是这一迁移便足以使其柔和：与 Piloto 同源，只是换了气候。', 'زراعة في الجنوب الدومينيكي. كفى الانتقال وحده لتليينها: الدم نفسه الذي في البيلوتو، لكن في مناخ آخر.', 'Milder than its forebear, supple in texture and creamy in taste. It serves as binder as much as filler, where Piloto stays in the filler.', 'Más suave que su antecesora, de textura flexible y sabor cremoso. Sirve de capote tanto como de tripa, allí donde el Piloto se queda en la tripa.', 'Milder als ihre Vorgängerin, geschmeidig in der Textur und cremig im Geschmack. Sie dient ebenso als Umblatt wie als Einlage, wo Piloto in der Einlage bleibt.', '较其先辈更柔和，质地柔韧、口感绵密。它既可作茄套亦可入茄芯，而 Piloto 只留在茄芯。', 'أنعم من سالفتها، ليّنة الملمس كريمية المذاق. تصلح رابطًا بقدر ما تصلح حشوة، بينما يبقى البيلوتو في الحشوة.', '[\"Mildness\",\"Cream\",\"Pale wood\"]', '[\"Suavidad\",\"Crema\",\"Madera clara\"]', '[\"Milde\",\"Sahne\",\"Helles Holz\"]', '[\"柔顺\",\"奶油\",\"浅色木质\"]', '[\"نعومة\",\"قشدة\",\"خشب فاتح\"]', '[\"Café au lait\",\"White rum\",\"Dried fruit\"]', '[\"Café con leche\",\"Ron blanco\",\"Frutos secos\"]', '[\"Milchkaffee\",\"Weißer Rum\",\"Trockenfrüchte\"]', '[\"欧蕾咖啡\",\"白朗姆\",\"果干\"]', '[\"قهوة بالحليب\",\"روم أبيض\",\"فواكه مجففة\"]', 'Binder and filler', 'Capote y tripa', 'Umblatt und Einlage', '茄套与茄芯', 'رابط وحشوة'),
  ('equateur-connecticut', 'Ecuador Connecticut', 'ecuador', 'Cape', 'Semence du Connecticut transplantée en Équateur. Le pays offre à cette feuille d\'ombre les conditions qu\'elle demandait, sans les toiles qu\'il faut tendre en Nouvelle-Angleterre.', 'Même principe que l\'Habano équatorien : c\'est le ciel qui fait l\'ombre. La couverture nuageuse permanente donne une feuille plus claire et plus fine que celle poussée en plein soleil.', 'Cape claire, veinée discrète, réputée pour sa douceur. C\'est le choix des assemblages doux du matin, là où l\'Habano équatorien vise le corps.', '[\"Douceur\",\"Amande\",\"Crème\"]', '[\"Café au lait\",\"Champagne\",\"Pâtisserie\"]', '2026-08-21 17:58:41', '2026-08-22 22:08:55', 'Connecticut seed transplanted to Ecuador. The country gives this shade leaf the conditions it needed, without the cloth that must be stretched in New England.', 'Semilla de Connecticut trasplantada a Ecuador. El país ofrece a esta hoja de sombra las condiciones que exigía, sin las telas que hay que tender en Nueva Inglaterra.', 'Connecticut-Samen, nach Ecuador verpflanzt. Das Land bietet diesem Schattenblatt die Bedingungen, die es brauchte — ohne die Tücher, die man in Neuengland spannen muss.', '康涅狄格烟种移植至厄瓜多尔。这里为这种阴植烟叶提供了它所需的条件，而无需新英格兰必须张设的遮阳布。', 'بذور كونيتيكت منقولة إلى الإكوادور. توفّر البلاد لهذه الورقة المزروعة في الظل ما كانت تحتاجه، دون الأقمشة التي يجب نصبها في نيو إنغلاند.', 'The same principle as the Ecuadorian Habano: the sky provides the shade. Permanent cloud cover yields a paler, finer leaf than one grown in full sun.', 'El mismo principio que el Habano ecuatoriano: es el cielo el que da la sombra. La cobertura nubosa permanente produce una hoja más clara y más fina que la crecida a pleno sol.', 'Dasselbe Prinzip wie beim ecuadorianischen Habano: Den Schatten spendet der Himmel. Die ständige Wolkendecke ergibt ein helleres, feineres Blatt als der Anbau in voller Sonne.', '与厄瓜多尔哈瓦那种同理：遮阴来自天空。终年云层使叶片较全日照者更浅、更薄。', 'المبدأ نفسه كما في الهابانو الإكوادوري: السماء هي التي تصنع الظل. فالغطاء السحابي الدائم يعطي ورقة أفتح وأرقّ من تلك التي تنمو في الشمس الكاملة.', 'A pale wrapper with discreet veining, prized for its mildness. It is the choice for gentle morning blends, where the Ecuadorian Habano aims at body.', 'Capa clara, de venas discretas, reputada por su suavidad. Es la elección de las ligas suaves de la mañana, allí donde el Habano ecuatoriano busca el cuerpo.', 'Ein helles Deckblatt mit dezenter Äderung, für seine Milde geschätzt. Es ist die Wahl für sanfte Morgenmischungen, wo der ecuadorianische Habano auf Körper zielt.', '茄衣色浅，叶脉不显，以柔顺著称。它是清晨温和配方的选择，而厄瓜多尔哈瓦那种追求的是厚度。', 'غلاف فاتح بعروق خفيفة، ذائع الصيت بنعومته. وهو خيار الخلطات اللطيفة الصباحية، حيث يسعى الهابانو الإكوادوري إلى القوام.', '[\"Sweetness\",\"Almond\",\"Cream\"]', '[\"Dulzura\",\"Almendra\",\"Crema\"]', '[\"Milde\",\"Mandel\",\"Sahne\"]', '[\"甘润\",\"杏仁\",\"奶油\"]', '[\"حلاوة\",\"لوز\",\"قشدة\"]', '[\"Café au lait\",\"Champagne\",\"Pastry\"]', '[\"Café con leche\",\"Champán\",\"Repostería\"]', '[\"Milchkaffee\",\"Champagner\",\"Gebäck\"]', '[\"欧蕾咖啡\",\"香槟\",\"糕点\"]', '[\"قهوة بالحليب\",\"شمبانيا\",\"معجّنات\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('equateur-habano', 'Ecuador Habano', 'ecuador', 'Cape', 'Semence cubaine plantée sur les contreforts andins. L\'Équateur n\'a pas de tradition du cigare roulé : il fournit la feuille aux fabricants du Nicaragua, du Honduras et de République dominicaine.', 'Cultivée SANS TOILE D\'OMBRAGE, ce qui est l\'exception dans le métier : la couverture nuageuse de la saison filtre le soleil en permanence et rend les tentures inutiles. C\'est cette lumière égale qui fait la réputation du pays.', 'Cape souple et régulière, l\'une des plus répandues aujourd\'hui sur les cigares premium. Elle apporte du corps et de l\'épice là où sa voisine Connecticut apporte de la douceur.', '[\"Épices\",\"Cuir\",\"Poivre\"]', '[\"Rhum ambré\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 17:58:41', '2026-08-22 22:08:55', 'Cuban seed planted on the Andean foothills. Ecuador has no tradition of rolling cigars: it supplies leaf to makers in Nicaragua, Honduras and the Dominican Republic.', 'Semilla cubana plantada en las estribaciones andinas. Ecuador no tiene tradición de puro liado: abastece de hoja a los fabricantes de Nicaragua, Honduras y República Dominicana.', 'Kubanischer Samen, angebaut am Fuß der Anden. Ecuador hat keine Tradition des Zigarrenrollens: Es liefert Blatt an die Hersteller in Nicaragua, Honduras und der Dominikanischen Republik.', '古巴烟种，种植于安第斯山麓。厄瓜多尔没有卷制雪茄的传统：它向尼加拉瓜、洪都拉斯和多米尼加的制造商供应烟叶。', 'بذور كوبية تُزرع على سفوح الأنديز. لا تقليد لدى الإكوادور في لفّ السيجار: فهي تزوّد المصنّعين في نيكاراغوا وهندوراس وجمهورية الدومينيكان بالأوراق.', 'Grown WITHOUT SHADE CLOTH, the exception in the trade: the season\'s cloud cover filters the sun continuously and makes tenting unnecessary. It is this even light that made the country\'s name.', 'Cultivada SIN TELA DE SOMBRA, lo que es la excepción en el oficio: la cobertura nubosa de la temporada filtra el sol de forma permanente y hace innecesarios los toldos. Es esa luz uniforme la que dio fama al país.', 'Ohne SCHATTENTUCH angebaut — die Ausnahme im Metier: Die Wolkendecke der Saison filtert die Sonne beständig und macht Planen überflüssig. Dieses gleichmäßige Licht begründete den Ruf des Landes.', '无需遮阳布种植，这在业内是例外：产季的云层持续过滤阳光，使张设遮棚成为多余。正是这份均匀的光线成就了该国的声誉。', 'تُزرع دون قماش تظليل، وهو استثناء في هذه الحرفة: إذ يرشّح الغطاء السحابي الموسمي الشمس باستمرار فيجعل المظلات بلا لزوم. وهذا الضوء المتساوي هو ما صنع سمعة البلاد.', 'A supple, even wrapper, among the most widespread on premium cigars today. It brings body and spice where its Connecticut neighbour brings sweetness.', 'Capa flexible y regular, de las más extendidas hoy en los puros premium. Aporta cuerpo y especia allí donde su vecina Connecticut aporta dulzura.', 'Ein geschmeidiges, gleichmäßiges Deckblatt, heute eines der verbreitetsten auf Premium-Zigarren. Es bringt Körper und Würze, wo sein Connecticut-Nachbar Milde bringt.', '茄衣柔韧均匀，是当今优质雪茄上最常见的品类之一。相较于邻近的康涅狄格种带来柔顺，它带来的是厚度与辛香。', 'غلاف ليّن ومتجانس، من أكثر الأغلفة انتشارًا اليوم على السيجار الفاخر. يمنح القوام والتوابل حيث يمنح جاره الكونيتيكت الحلاوة.', '[\"Spice\",\"Leather\",\"Pepper\"]', '[\"Especias\",\"Cuero\",\"Pimienta\"]', '[\"Gewürze\",\"Leder\",\"Pfeffer\"]', '[\"香料\",\"皮革\",\"胡椒\"]', '[\"توابل\",\"جلد\",\"فلفل\"]', '[\"Amber rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron ámbar\",\"Café cargado\",\"Chocolate negro\"]', '[\"Bernsteinfarbener Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"琥珀朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم كهرماني\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('equateur-sumatra', 'Ecuador Sumatra', 'ecuador', 'Cape', 'Semence née aux Indes néerlandaises, arrivée en Équateur par le chemin qu\'ont pris toutes les graines d\'importation du pays : on y cherchait un climat, pas un terroir d\'origine. C\'est la troisième des grandes capes équatoriennes, et la moins nommée des trois.', 'Même principe que ses voisines : pas de toile d\'ombrage, la couverture nuageuse s\'en charge. Récoltée plus tard que la Connecticut, elle prend une teinte colorado que la lumière constante garde égale d\'un pied à l\'autre — c\'est ce qui permet d\'en tirer des capes assorties en quantité.', 'Cape fine, veinure presque invisible, plus sombre que la Connecticut sans atteindre le corps de l\'Habano. On la choisit pour ce qu\'elle ajoute au goût plutôt que pour la force : c\'est la plus sucrée des trois équatoriennes.', '[\"Épices douces\",\"Cèdre\",\"Sucre brun\"]', '[\"Bourbon\",\"Café au lait\",\"Fruits secs\"]', '2026-08-22 21:18:53', '2026-08-22 22:08:55', 'A seed born in the Dutch East Indies, brought to Ecuador by the route every imported seed in the country has taken: what was sought here was a climate, not a native terroir. It is the third of the great Ecuadorian wrappers, and the least often named of the three.', 'Semilla nacida en las Indias Orientales Neerlandesas, llegada a Ecuador por el camino que han seguido todas las semillas importadas del país: allí se buscaba un clima, no un terruño de origen. Es la tercera de las grandes capas ecuatorianas, y la menos nombrada de las tres.', 'Ein in Niederländisch-Ostindien entstandener Samen, nach Ecuador gelangt auf demselben Weg wie alle eingeführten Saaten des Landes: Gesucht war ein Klima, kein Herkunftsterroir. Sie ist das dritte der großen ecuadorianischen Deckblätter und das am seltensten genannte der drei.', '这一品种出自荷属东印度，循着厄瓜多尔所有引进种子的同一条路径来到此地：人们要的是一种气候，而非原产地风土。它是厄瓜多尔三大茄衣中的第三种，也是最少被提起的一种。', 'بذرة وُلدت في جزر الهند الشرقية الهولندية، ووصلت إلى الإكوادور عبر الطريق نفسه الذي سلكته كل البذور المستوردة إلى البلاد: كان المطلوب مناخًا لا أرضًا أصليّة. إنها ثالثة الأغلفة الإكوادورية الكبرى، وأقلّها ذِكرًا بين الثلاث.', 'The same principle as its neighbours: no shade cloth, the cloud cover does the work. Harvested later than the Connecticut, it takes on a colorado shade that the steady light keeps even from one plant to the next — which is what makes matched wrappers available in quantity.', 'El mismo principio que sus vecinas: sin tela de sombreo, de eso se encarga la cobertura nubosa. Cosechada más tarde que la Connecticut, adquiere un tono colorado que la luz constante mantiene parejo de una planta a otra: eso permite obtener capas a juego en cantidad.', 'Dasselbe Prinzip wie bei ihren Nachbarinnen: kein Schattentuch, die Wolkendecke übernimmt das. Später geerntet als die Connecticut, nimmt sie einen Colorado-Ton an, den das gleichmäßige Licht von Pflanze zu Pflanze konstant hält — genau das erlaubt es, farblich passende Deckblätter in Menge zu gewinnen.', '与它的邻居们同理：不搭遮阳布，云层自会代劳。采收晚于康涅狄格种，它因而呈现一层「科罗拉多」色调，而恒定的光照使这层色调在每一株之间都保持一致——正因如此才能批量取得色泽相配的茄衣。', 'المبدأ نفسه الذي تتبعه جاراتها: لا قماش تظليل، فالغطاء السحابي يتكفّل بذلك. تُجنى بعد الكونيتيكت، فتكتسب لونًا «كولورادو» يُبقيه الضوء الثابت متساويًا من نبتة إلى أخرى — وهذا ما يتيح استخراج أغلفة متجانسة بكميات.', 'A fine wrapper with all but invisible veining, darker than the Connecticut without reaching the body of the Habano. It is chosen for what it adds to the taste rather than for strength: it is the sweetest of the three Ecuadorians.', 'Capa fina, de venas casi invisibles, más oscura que la Connecticut sin alcanzar el cuerpo del Habano. Se elige por lo que aporta al sabor más que por la fuerza: es la más dulce de las tres ecuatorianas.', 'Ein feines Deckblatt mit nahezu unsichtbarer Äderung, dunkler als die Connecticut, ohne den Körper der Habano zu erreichen. Man wählt sie für das, was sie dem Geschmack hinzufügt, nicht für die Stärke: Sie ist die süßeste der drei Ecuadorianerinnen.', '茄衣细薄，叶脉近乎不可见，色泽深于康涅狄格种，却不及哈瓦那种厚实。人们选它是为了它给味道添上的东西，而非力度：它是三种厄瓜多尔茄衣中最甜的一种。', 'غلاف رفيع، عروقه تكاد لا تُرى، أدكن من الكونيتيكت دون أن يبلغ جسد الهابانو. يُختار لما يضيفه إلى المذاق لا لقوّته: إنه أحلى الأغلفة الإكوادورية الثلاثة.', '[\"Sweet spice\",\"Cedar\",\"Brown sugar\"]', '[\"Especias dulces\",\"Cedro\",\"Azúcar moreno\"]', '[\"Milde Gewürze\",\"Zeder\",\"Brauner Zucker\"]', '[\"甜香料\",\"雪松\",\"红糖\"]', '[\"توابل حلوة\",\"أرز\",\"سكر بنّي\"]', '[\"Bourbon\",\"Café au lait\",\"Dried fruit\"]', '[\"Bourbon\",\"Café con leche\",\"Frutos secos\"]', '[\"Bourbon\",\"Milchkaffee\",\"Trockenfrüchte\"]', '[\"波本威士忌\",\"欧蕾咖啡\",\"果干\"]', '[\"بوربون\",\"قهوة بالحليب\",\"فواكه مجففة\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('honduras-connecticut-shade', 'Connecticut Shade', 'honduras', 'Cape', 'La semence de Nouvelle-Angleterre, transplantée au Honduras. Le pays est l\'un des rares à cultiver côte à côte deux capes d\'ombrage aux caractères opposés : celle-ci et le Corojo.', 'Sous toile, comme dans sa vallée d\'origine — mais sous un soleil tropical, ce qui n\'appelle pas les mêmes gestes ni les mêmes durées.', 'Cape claire et douce, à l\'opposé du Corojo voisin. Les deux poussent dans le même pays et servent des assemblages contraires : c\'est la palette du Honduras.', '[\"Douceur\",\"Cèdre\",\"Pain grillé\"]', '[\"Café au lait\",\"Thé blanc\",\"Vin blanc sec\"]', '2026-08-21 22:22:19', '2026-08-22 22:08:55', 'The New England seed, transplanted to Honduras. The country is among the few to grow side by side two shade wrappers of opposite character: this one and Corojo.', 'La semilla de Nueva Inglaterra, trasplantada a Honduras. El país es de los pocos que cultivan lado a lado dos capas de sombra de carácter opuesto: esta y el Corojo.', 'Der Samen aus Neuengland, nach Honduras verpflanzt. Das Land gehört zu den wenigen, die zwei Schattendeckblätter gegensätzlichen Charakters nebeneinander anbauen: dieses und den Corojo.', '来自新英格兰的烟种，移植至洪都拉斯。该国是少数并肩种植两种性格相反的阴植茄衣的地方：这一种，与 Corojo。', 'بذرة نيو إنغلاند، منقولة إلى هندوراس. والبلاد من القلائل التي تزرع جنبًا إلى جنب غلافين مزروعين في الظل متعاكسي الطابع: هذا والكوروخو.', 'Under cloth, as in its home valley — but beneath a tropical sun, which calls for different handling and different timings.', 'Bajo tela, como en su valle de origen, pero bajo un sol tropical, lo que no exige los mismos gestos ni los mismos tiempos.', 'Unter Tuch wie in ihrem Ursprungstal — doch unter tropischer Sonne, was andere Handgriffe und andere Zeiten verlangt.', '如在故乡谷地一样置于棚下——但顶着热带的太阳，所需的手法与时序皆不相同。', 'تحت القماش، كما في واديها الأصلي — لكن تحت شمس مدارية، ما يستدعي حركات مختلفة ومدداً مختلفة.', 'A pale, mild wrapper, the opposite of the Corojo next door. Both grow in the same country and serve opposing blends: that is Honduras\'s palette.', 'Capa clara y suave, en las antípodas del Corojo vecino. Ambas crecen en el mismo país y sirven a ligas contrarias: esa es la paleta de Honduras.', 'Ein helles, mildes Deckblatt, das Gegenteil des benachbarten Corojo. Beide wachsen im selben Land und dienen gegensätzlichen Mischungen: das ist die Palette von Honduras.', '茄衣色浅而柔和，与相邻的 Corojo 恰成对照。二者生长于同一国度，却服务于相反的配方：这就是洪都拉斯的调色盘。', 'غلاف فاتح ناعم، على نقيض الكوروخو المجاور. ينمو الاثنان في البلد نفسه ويخدمان خلطات متعاكسة: تلك هي لوحة هندوراس.', '[\"Mildness\",\"Cedar\",\"Toast\"]', '[\"Suavidad\",\"Cedro\",\"Pan tostado\"]', '[\"Milde\",\"Zeder\",\"Toast\"]', '[\"柔顺\",\"雪松\",\"烤面包\"]', '[\"نعومة\",\"أرز\",\"خبز محمّص\"]', '[\"Café au lait\",\"White tea\",\"Dry white wine\"]', '[\"Café con leche\",\"Té blanco\",\"Vino blanco seco\"]', '[\"Milchkaffee\",\"Weißer Tee\",\"Trockener Weißwein\"]', '[\"欧蕾咖啡\",\"白茶\",\"干白葡萄酒\"]', '[\"قهوة بالحليب\",\"شاي أبيض\",\"نبيذ أبيض جاف\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('honduras-corojo', 'Corojo', 'honduras', 'Cape', 'La semence cubaine de 1947 arrive dans la vallée de Jamastrán au cours des années 1960, plantée par la maison Camacho — qui revendique d\'y avoir fait pousser la première feuille de Corojo hors de Cuba. Le moho azul chassera l\'originale des champs cubains une quinzaine d\'années plus tard : ce qui n\'était qu\'un essai est devenu un refuge.', 'Culture sous toile d\'ombrage, dans une vallée dont le climat rappelle celui de la Vuelta Abajo. C\'est de là que vient aujourd\'hui l\'essentiel du Corojo du monde.', 'Elle a gardé la puissance et l\'épice de la souche d\'origine — c\'est ce qu\'on vient y chercher, et ce que Cuba avait perdu en la remplaçant par des hybrides résistants.', '[\"Épices\",\"Poivre\",\"Cuir\"]', '[\"Rhum vieux\",\"Café noir\",\"Cacao\"]', '2026-08-21 22:22:19', '2026-08-22 22:08:55', 'The Cuban seed of 1947 reached the Jamastrán valley during the 1960s, planted by the house of Camacho — which claims to have grown there the first Corojo leaf outside Cuba. Blue mould would drive the original from Cuban fields some fifteen years later: what had been an experiment became a refuge.', 'La semilla cubana de 1947 llega al valle de Jamastrán en los años sesenta, plantada por la casa Camacho, que reivindica haber cultivado allí la primera hoja de Corojo fuera de Cuba. El moho azul expulsaría a la original de los campos cubanos unos quince años después: lo que era un ensayo se volvió un refugio.', 'Der kubanische Samen von 1947 erreichte in den 1960er Jahren das Tal von Jamastrán, gepflanzt vom Haus Camacho — das für sich beansprucht, dort das erste Corojo-Blatt außerhalb Kubas gezogen zu haben. Der Blauschimmel sollte das Original rund fünfzehn Jahre später von Kubas Feldern vertreiben: Was ein Versuch war, wurde zur Zuflucht.', '1947 年的古巴烟种于六十年代进入哈马斯特兰谷地，由 Camacho 家族种下——该家族宣称在此培育出古巴以外的第一片 Corojo 叶。约十五年后，霉霜病将原株逐出古巴的田野：本是一场试验，竟成了避难所。', 'وصلت البذرة الكوبية لعام 1947 إلى وادي خاماستران في ستينيات القرن الماضي، زرعتها دار كاماتشو — التي تدّعي أنها أنبتت هناك أول ورقة كوروخو خارج كوبا. وبعد نحو خمسة عشر عامًا طرد العفن الأزرق الأصل من حقول كوبا: فما كان تجربةً صار ملجأً.', 'Grown under shade cloth, in a valley whose climate recalls that of the Vuelta Abajo. Most of the world\'s Corojo comes from here today.', 'Cultivo bajo tela de sombra, en un valle cuyo clima recuerda al de Vuelta Abajo. De ahí procede hoy la mayor parte del Corojo del mundo.', 'Anbau unter Schattentuch, in einem Tal, dessen Klima an die Vuelta Abajo erinnert. Von hier stammt heute der Großteil des Corojo der Welt.', '在遮阳布下种植，谷地气候令人想起下维尔塔。如今世界上大部分 Corojo 都出自这里。', 'تُزرع تحت قماش التظليل، في وادٍ يذكّر مناخه بفويلتا أباخو. ومن هنا يأتي اليوم معظم الكوروخو في العالم.', 'It kept the power and spice of the original strain — that is what people come for, and what Cuba lost when it replaced it with resistant hybrids.', 'Ha conservado la potencia y la especia de la cepa original: es lo que se viene a buscar, y lo que Cuba perdió al sustituirla por híbridos resistentes.', 'Sie hat Kraft und Würze der Ursprungssorte bewahrt — genau das sucht man hier, und genau das verlor Kuba, als es sie durch widerstandsfähige Hybriden ersetzte.', '它保留了原始品系的力度与辛香——这正是人们为之而来的，也正是古巴以抗病杂交种取而代之时失去的。', 'حافظت على قوة السلالة الأصلية وتوابلها — وهذا ما يُقصد لأجله، وهو ما فقدته كوبا حين استبدلتها بهجائن مقاومة.', '[\"Spice\",\"Pepper\",\"Leather\"]', '[\"Especias\",\"Pimienta\",\"Cuero\"]', '[\"Gewürze\",\"Pfeffer\",\"Leder\"]', '[\"香料\",\"胡椒\",\"皮革\"]', '[\"توابل\",\"فلفل\",\"جلد\"]', '[\"Aged rum\",\"Black coffee\",\"Cocoa\"]', '[\"Ron añejo\",\"Café solo\",\"Cacao\"]', '[\"Alter Rum\",\"Schwarzer Kaffee\",\"Kakao\"]', '[\"陈年朗姆\",\"黑咖啡\",\"可可\"]', '[\"روم معتّق\",\"قهوة سوداء\",\"كاكاو\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('indonesie-besuki', 'Besuki', 'indonesia', 'Cape et tripe', 'La région de Jember, à Java Est, est la plus réputée d\'Indonésie pour le tabac. La feuille y porte le nom de la résidence de Besuki, héritée de l\'administration coloniale.', 'Deux récoltes se succèdent et ont gardé leurs noms néerlandais : la Vroege Oogst, précoce, et la Na Oogst, tardive. Culture de plein soleil, comme à Deli.', 'Feuille douce et aromatique, assez souple pour servir de cape et assez neutre pour entrer dans la tripe. C\'est cette double vocation qui la distingue.', '[\"Douceur\",\"Aromatique\",\"Foin sec\"]', '[\"Thé vert\",\"Vin blanc sec\",\"Fruits secs\"]', '2026-08-21 17:58:41', '2026-08-22 22:08:55', 'The Jember region of East Java is Indonesia\'s most celebrated tobacco ground. The leaf carries the name of the Besuki residency, inherited from the colonial administration.', 'La región de Jember, en Java Oriental, es la más reputada de Indonesia para el tabaco. La hoja lleva el nombre de la residencia de Besuki, heredado de la administración colonial.', 'Die Region Jember in Ostjava ist Indonesiens renommiertester Tabakboden. Das Blatt trägt den Namen der Residentschaft Besuki, ein Erbe der Kolonialverwaltung.', '东爪哇的任抹（Jember）地区是印尼最负盛名的烟草产地。这种烟叶沿用了殖民时期行政区「Besuki」之名。', 'منطقة جيمبر في جاوة الشرقية هي الأشهر في إندونيسيا لزراعة التبغ. وتحمل الورقة اسم ولاية بيسوكي الموروث عن الإدارة الاستعمارية.', 'Two harvests follow one another and have kept their Dutch names: Vroege Oogst, the early one, and Na Oogst, the late one. Sun-grown, as at Deli.', 'Dos cosechas se suceden y han conservado sus nombres neerlandeses: la Vroege Oogst, temprana, y la Na Oogst, tardía. Cultivo a pleno sol, como en Deli.', 'Zwei Ernten folgen aufeinander und haben ihre niederländischen Namen behalten: Vroege Oogst, die frühe, und Na Oogst, die späte. Sonnenanbau wie in Deli.', '两季采收先后进行，并保留了荷兰语名称：早收的 Vroege Oogst 与晚收的 Na Oogst。与德利一样为日晒种植。', 'حصادان متعاقبان احتفظا باسميهما الهولنديين: Vroege Oogst المبكر، وNa Oogst المتأخر. وتُزرع في الشمس الكاملة، كما في دلي.', 'A sweet, aromatic leaf, supple enough to serve as a wrapper and neutral enough to go into the filler. It is this double calling that sets it apart.', 'Hoja dulce y aromática, lo bastante flexible para servir de capa y lo bastante neutra para entrar en la tripa. Es esa doble vocación la que la distingue.', 'Ein mildes, aromatisches Blatt, geschmeidig genug als Deckblatt und neutral genug für die Einlage. Diese doppelte Bestimmung zeichnet es aus.', '叶片甘润而芬芳，柔韧足以作茄衣，中性足以入茄芯。正是这种双重用途使其与众不同。', 'ورقة حلوة عطرة، من الليونة ما يكفي لتكون غلافًا، ومن الحياد ما يكفي لتدخل في الحشوة. وهذه الازدواجية هي ما يميّزها.', '[\"Sweetness\",\"Aromatic\",\"Dry hay\"]', '[\"Dulzura\",\"Aromática\",\"Heno seco\"]', '[\"Milde\",\"Aromatisch\",\"Trockenes Heu\"]', '[\"甘润\",\"芬芳\",\"干草\"]', '[\"حلاوة\",\"عطرية\",\"قش جاف\"]', '[\"Green tea\",\"Dry white wine\",\"Dried fruit\"]', '[\"Té verde\",\"Vino blanco seco\",\"Frutos secos\"]', '[\"Grüner Tee\",\"Trockener Weißwein\",\"Trockenfrüchte\"]', '[\"绿茶\",\"干白葡萄酒\",\"果干\"]', '[\"شاي أخضر\",\"نبيذ أبيض جاف\",\"فواكه مجففة\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('indonesie-deli', 'Deli Sumatra', 'indonesia', 'Cape', 'Les planteurs néerlandais installent la culture à Deli, sur la côte est de Sumatra, au XIXe siècle. Avec Besuki à Java Est et Klaten à Java Centre, Deli forme l\'un des trois centres historiques du tabac à cigare indonésien.', 'Cultivée en plein soleil, et destinée dès le départ à servir de cape. La semence est native — un tabac noir qui n\'a pas été importé d\'ailleurs.', 'Fumée sèche et épicée, d\'un caractère reconnaissable. C\'est en Europe qu\'elle est la plus répandue, où elle habille une grande part des cigares et cigarillos.', '[\"Épices\",\"Fumée sèche\",\"Bois\"]', '[\"Café allongé\",\"Bière brune\",\"Thé noir fumé\"]', '2026-08-21 17:58:41', '2026-08-22 22:08:55', 'Dutch planters established the crop at Deli, on Sumatra\'s east coast, in the nineteenth century. With Besuki in East Java and Klaten in Central Java, Deli is one of the three historic centres of Indonesian cigar tobacco.', 'Los plantadores neerlandeses implantaron el cultivo en Deli, en la costa oriental de Sumatra, en el siglo XIX. Junto con Besuki, en Java Oriental, y Klaten, en Java Central, Deli forma uno de los tres centros históricos del tabaco de puro indonesio.', 'Niederländische Pflanzer etablierten den Anbau im 19. Jahrhundert in Deli an der Ostküste Sumatras. Mit Besuki in Ostjava und Klaten in Zentraljava bildet Deli eines der drei historischen Zentren des indonesischen Zigarrentabaks.', '十九世纪，荷兰种植园主在苏门答腊东岸的德利建立了这一作物。德利与东爪哇的Besuki、中爪哇的Klaten并列为印尼雪茄烟草的三大历史中心之一。', 'أرسى المزارعون الهولنديون هذه الزراعة في دلي على الساحل الشرقي لسومطرة في القرن التاسع عشر. وتشكّل دلي، مع بيسوكي في جاوة الشرقية وكلاتن في جاوة الوسطى، أحد المراكز التاريخية الثلاثة لتبغ السيجار الإندونيسي.', 'Sun-grown, and intended from the start to serve as a wrapper. The seed is native — a black tobacco that was not imported from anywhere else.', 'Cultivada a pleno sol y destinada desde el principio a servir de capa. La semilla es autóctona: un tabaco negro que no se importó de ninguna parte.', 'Sonnengewachsen und von Anfang an als Deckblatt bestimmt. Der Samen ist einheimisch — ein schwarzer Tabak, der nicht von anderswo eingeführt wurde.', '日晒种植，自始即为茄衣而生。烟种为本地原生——一种并非自他处引进的黑烟草。', 'تُزرع في الشمس الكاملة، وقُصد بها منذ البداية أن تكون غلافًا. والبذرة محلية — تبغ أسود لم يُستورد من مكان آخر.', 'A dry, spicy smoke of recognisable character. It is most widespread in Europe, where it dresses a large share of cigars and cigarillos.', 'Humo seco y especiado, de carácter reconocible. Es en Europa donde más se extiende, donde viste buena parte de los puros y cigarritos.', 'Ein trockener, würziger Rauch von wiedererkennbarem Charakter. Am weitesten verbreitet ist es in Europa, wo es einen großen Teil der Zigarren und Zigarillos umhüllt.', '烟气干爽而带香料气息，性格易辨。它在欧洲最为普及，包覆着当地相当大一部分雪茄与小雪茄。', 'دخان جاف وحارّ الطابع، سهل التمييز. وهي الأوسع انتشارًا في أوروبا، حيث تكسو نسبة كبيرة من السيجار والسيجارلو.', '[\"Spice\",\"Dry smoke\",\"Wood\"]', '[\"Especias\",\"Humo seco\",\"Madera\"]', '[\"Gewürze\",\"Trockener Rauch\",\"Holz\"]', '[\"香料\",\"干爽烟气\",\"木质\"]', '[\"توابل\",\"دخان جاف\",\"خشب\"]', '[\"Long black coffee\",\"Dark beer\",\"Smoked black tea\"]', '[\"Café largo\",\"Cerveza negra\",\"Té negro ahumado\"]', '[\"Verlängerter Kaffee\",\"Dunkles Bier\",\"Geräucherter Schwarztee\"]', '[\"美式咖啡\",\"黑啤\",\"烟熏红茶\"]', '[\"قهوة مطوّلة\",\"جعة داكنة\",\"شاي أسود مدخّن\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('italie-kentucky', 'Kentucky', 'italy', 'Cape et tripe', 'La graine vient d\'Amérique du Nord et porte le nom de l\'État qui l\'a fait connaître. Elle arrive en Italie au XIXe siècle, dans un pays qui cultivait déjà du tabac pour son monopole d\'État. Elle y est restée, et c\'est aujourd\'hui la seule feuille à cigare d\'Europe continentale.', 'Récoltée en fin d\'été, puis séchée AU FEU : la feuille passe une quinzaine de jours suspendue au-dessus d\'un feu de bois lent, dans une grange close. Ce n\'est pas de la fumaison au sens culinaire — le feu sèche autant qu\'il parfume — et c\'est ce que presque aucune autre origine ne pratique pour le cigare. Vient ensuite la fermentation, plus longue que la moyenne.', 'Feuille épaisse, nervurée, sombre. Elle sert à la fois de cape et de tripe, ce qui est rare : le Toscano est fait d\'un seul type de feuille, là où un cigare caribéen en assemble trois ou quatre. Le Kentucky italien fournit surtout la tripe, la cape venant selon les cas d\'Italie ou des États-Unis.', '[\"Fumée\",\"Cuir\",\"Poivre\"]', '[\"Grappa\",\"Café serré\",\"Chocolat noir\"]', '2026-08-22 22:19:24', '2026-08-23 02:24:48', 'The seed comes from North America and bears the name of the state that made it known. It reached Italy in the 19th century, in a country already growing tobacco for its state monopoly. It stayed, and it is today the only cigar leaf of continental Europe.', 'La semilla viene de América del Norte y lleva el nombre del estado que la dio a conocer. Llega a Italia en el siglo XIX, a un país que ya cultivaba tabaco para su monopolio estatal. Allí se quedó, y es hoy la única hoja de puro de la Europa continental.', 'Der Samen stammt aus Nordamerika und trägt den Namen des Bundesstaats, der ihn bekannt machte. Im 19. Jahrhundert gelangte er nach Italien, in ein Land, das bereits Tabak für sein Staatsmonopol anbaute. Er blieb — und ist heute das einzige Zigarrenblatt Kontinentaleuropas.', '这一品种来自北美，名字取自使它闻名的那个州。它在十九世纪进入意大利——一个当时已为国家专卖种植烟草的国度——并从此留了下来，成为今日欧洲大陆唯一的雪茄烟叶。', 'البذرة من أمريكا الشمالية، وتحمل اسم الولاية التي عرَّفت بها. وصلت إلى إيطاليا في القرن التاسع عشر، إلى بلد كان يزرع التبغ أصلًا لاحتكاره الحكومي. وبقيت هناك، وهي اليوم ورقة السيجار الوحيدة في أوروبا القارية.', 'Harvested at the end of summer, then FIRE-CURED: the leaf hangs for about a fortnight above a slow wood fire in a closed barn. This is not smoking in the culinary sense — the fire dries as much as it perfumes — and almost no other origin does it for cigars. Fermentation follows, longer than average.', 'Se cosecha a finales de verano y luego se cura AL FUEGO: la hoja pasa unos quince días colgada sobre un fuego de leña lento, en un granero cerrado. No es ahumado en sentido culinario —el fuego seca tanto como perfuma— y casi ningún otro origen lo practica para el puro. Después viene la fermentación, más larga que la media.', 'Am Ende des Sommers geerntet und dann ÜBER FEUER GETROCKNET: Das Blatt hängt etwa vierzehn Tage über einem langsamen Holzfeuer in einer geschlossenen Scheune. Das ist kein Räuchern im kulinarischen Sinn — das Feuer trocknet ebenso sehr, wie es aromatisiert — und kaum eine andere Herkunft praktiziert es für Zigarren. Danach folgt die Fermentation, länger als üblich.', '夏末采收，随后以火烘干：烟叶在密闭的烤房里，悬于缓慢燃烧的木火之上约两周。这并非烹饪意义上的烟熏——火既是干燥也是赋香——而且几乎没有别的产地会为雪茄这样做。之后是发酵，比一般更为漫长。', 'تُجنى في أواخر الصيف، ثم تُجفَّف بالنار: تُعلَّق الورقة نحو خمسة عشر يومًا فوق نار حطب هادئة في حظيرة مغلقة. ليس هذا تدخينًا بالمعنى الطهوي — فالنار تُجفِّف بقدر ما تُعطِّر — ولا يكاد أي منشأ آخر يفعله للسيجار. ثم تأتي التخمير، أطول من المعتاد.', 'A thick, veined, dark leaf. It serves as both wrapper and filler, which is rare: the Toscano is made of a single kind of leaf, where a Caribbean cigar blends three or four. Italian Kentucky supplies mainly the filler, the wrapper coming from Italy or the United States depending on the case.', 'Hoja gruesa, nervada, oscura. Sirve a la vez de capa y de tripa, cosa poco común: el Toscano está hecho de un solo tipo de hoja, mientras que un puro caribeño liga tres o cuatro. El Kentucky italiano aporta sobre todo la tripa; la capa viene, según los casos, de Italia o de Estados Unidos.', 'Ein dickes, geadertes, dunkles Blatt. Es dient zugleich als Deckblatt und als Einlage, was selten ist: Die Toscano besteht aus einer einzigen Blattart, während eine karibische Zigarre drei oder vier verschneidet. Der italienische Kentucky liefert vor allem die Einlage, das Deckblatt kommt je nach Fall aus Italien oder den Vereinigten Staaten.', '叶片厚实、脉络分明、色泽深沉。它同时充当茄衣与茄芯，这颇为罕见：托斯卡诺只用一种烟叶，而加勒比雪茄要调配三四种。意大利肯塔基主要供作茄芯，茄衣则视情形来自意大利或美国。', 'ورقة سميكة، بارزة العروق، داكنة. تصلح غلافًا وحشوة في آن، وهذا نادر: فالتوسكانو مصنوع من نوع واحد من الورق، بينما يمزج السيجار الكاريبي ثلاثة أو أربعة. يوفّر الكنتاكي الإيطالي الحشوة أساسًا، أما الغلاف فيأتي من إيطاليا أو الولايات المتحدة بحسب الحال.', '[\"Smoke\",\"Leather\",\"Pepper\"]', '[\"Humo\",\"Cuero\",\"Pimienta\"]', '[\"Rauch\",\"Leder\",\"Pfeffer\"]', '[\"烟熏\",\"皮革\",\"胡椒\"]', '[\"دخان\",\"جلد\",\"فلفل\"]', '[\"Grappa\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Grappa\",\"Café cargado\",\"Chocolate negro\"]', '[\"Grappa\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"格拉帕\",\"浓咖啡\",\"黑巧克力\"]', '[\"غرابا\",\"قهوة مركّزة\",\"شوكولاتة داكنة\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('jamaique-cow-tongue', 'Cow Tongue', 'jamaica', 'Cape et tripe', 'La feuille jamaïcaine porte un nom qu\'on ne lit nulle part ailleurs — Cow Tongue, langue de vache, dite aussi Silver Tongue. Les populations autochtones de l\'île la cultivaient bien avant que des Cubains n\'y bâtissent une industrie au XIXe siècle.', 'Elle poussait dans la plaine calcaire de May Pen et autour de Kingston. Ces terres ne sont plus cultivées : l\'ouragan Gilbert a détruit l\'usine de Kingston et mille acres de tabac en septembre 1988, et rien n\'a redémarré depuis.', 'Cette fiche décrit une feuille au passé, et c\'est assumé. La Jamaïque fut le premier pays du cigare des Caraïbes hors de Cuba dans les années 1960-1970 ; il n\'en reste que des marques, rachetées et transférées ailleurs.', '[\"Douceur\",\"Terre\",\"Bois clair\"]', '[\"Rhum jamaïcain\",\"Café Blue Mountain\",\"Fruits confits\"]', '2026-08-21 23:23:48', '2026-08-22 22:08:55', 'The Jamaican leaf bears a name read nowhere else — Cow Tongue, also called Silver Tongue. The island\'s indigenous people grew it long before Cubans built an industry there in the nineteenth century.', 'La hoja jamaicana lleva un nombre que no se lee en ninguna otra parte: Cow Tongue, lengua de vaca, llamada también Silver Tongue. Los pueblos originarios de la isla la cultivaban mucho antes de que unos cubanos levantaran allí una industria en el siglo XIX.', 'Das jamaikanische Blatt trägt einen Namen, den man nirgends sonst liest — Cow Tongue, Kuhzunge, auch Silver Tongue genannt. Die indigene Bevölkerung der Insel baute es an, lange bevor Kubaner dort im 19. Jahrhundert eine Industrie errichteten.', '牙买加的烟叶有一个别处读不到的名字——Cow Tongue（牛舌），亦称 Silver Tongue。早在十九世纪古巴人在此建立产业之前，岛上的原住民就已种植它。', 'تحمل الورقة الجامايكية اسمًا لا يُقرأ في مكان آخر — «كاو تَنغ»، أي لسان البقرة، ويُقال لها أيضًا «سيلفر تَنغ». وكان سكان الجزيرة الأصليون يزرعونها قبل وقت طويل من إقامة الكوبيين صناعةً هناك في القرن التاسع عشر.', 'It grew on the limestone plain of May Pen and around Kingston. That ground is no longer worked: Hurricane Gilbert destroyed the Kingston factory and a thousand acres of tobacco in September 1988, and nothing has restarted since.', 'Crecía en la llanura caliza de May Pen y en torno a Kingston. Esas tierras ya no se cultivan: el huracán Gilbert destruyó la fábrica de Kingston y mil acres de tabaco en septiembre de 1988, y nada ha vuelto a arrancar.', 'Es wuchs auf der Kalkebene von May Pen und rund um Kingston. Dieser Boden wird nicht mehr bestellt: Hurrikan Gilbert zerstörte im September 1988 die Fabrik von Kingston und tausend Acre Tabak, und nichts ist seither wieder angelaufen.', '它曾生长在梅彭的石灰岩平原以及金斯敦周边。这些土地已不再耕作：1988 年 9 月，飓风吉尔伯特摧毁了金斯敦的工厂和一千英亩烟田，此后再未重启。', 'كانت تنمو في سهل ماي بن الكلسي وحول كينغستون. ولم تعد تلك الأراضي تُزرع: فقد دمّر إعصار جيلبرت مصنع كينغستون وألف فدان من التبغ في سبتمبر 1988، ولم يُستأنف شيء منذ ذلك الحين.', 'This entry describes a leaf in the past tense, and does so deliberately. Jamaica was the first cigar country of the Caribbean outside Cuba in the 1960s and 1970s; all that remains are brands, bought up and moved elsewhere.', 'Esta ficha describe una hoja en pasado, y lo asume. Jamaica fue el primer país del puro en el Caribe fuera de Cuba en los años sesenta y setenta; solo quedan marcas, compradas y trasladadas a otra parte.', 'Dieser Eintrag beschreibt ein Blatt in der Vergangenheit, und das mit Absicht. Jamaika war in den 1960er und 1970er Jahren das erste Zigarrenland der Karibik außerhalb Kubas; geblieben sind nur Marken, aufgekauft und andernorts weitergeführt.', '这份条目以过去时描述一片烟叶，且是有意为之。二十世纪六七十年代，牙买加曾是古巴之外加勒比第一大雪茄国；如今只剩下若干品牌，被收购并迁往他处。', 'تصف هذه البطاقة ورقةً بصيغة الماضي، وذلك عن قصد. كانت جامايكا في الستينيات والسبعينيات أول بلد للسيجار في الكاريبي خارج كوبا؛ ولم يبقَ منها سوى علامات اشتُريت ونُقلت إلى أماكن أخرى.', '[\"Mildness\",\"Earth\",\"Pale wood\"]', '[\"Suavidad\",\"Tierra\",\"Madera clara\"]', '[\"Milde\",\"Erde\",\"Helles Holz\"]', '[\"柔顺\",\"泥土\",\"浅色木质\"]', '[\"نعومة\",\"تراب\",\"خشب فاتح\"]', '[\"Jamaican rum\",\"Blue Mountain coffee\",\"Candied fruit\"]', '[\"Ron jamaicano\",\"Café Blue Mountain\",\"Frutas confitadas\"]', '[\"Jamaika-Rum\",\"Blue-Mountain-Kaffee\",\"Kandierte Früchte\"]', '[\"牙买加朗姆\",\"蓝山咖啡\",\"蜜饯\"]', '[\"روم جامايكي\",\"قهوة بلو ماونتن\",\"فواكه مسكّرة\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('mexique-negro-san-andres', 'Negro San Andrés', 'mexico', 'Cape maduro et sous-cape', 'Des immigrants cubains et allemands plantent du tabac dans la vallée de San Andrés dès les années 1830. En 1880, le cultivateur cubain Alberto Turrent quitte son île pour s\'y installer avec ses semences — la filiation est directe.', 'La vallée monte à quelque 1 200 mètres au bord du golfe du Mexique : climat plus frais qu\'on ne l\'attendrait sous cette latitude, brises humides venues de la côte, sols enrichis par le volcan.', 'Feuille sombre qui se coupe à la tige, comme le broadleaf du Connecticut. Elle supporte des températures de fermentation élevées, ce qui en fait une cape maduro de premier plan.', '[\"Chocolat noir\",\"Poivre\",\"Terre\"]', '[\"Mezcal\",\"Café serré\",\"Chocolat chaud\"]', '2026-08-21 18:14:54', '2026-08-22 22:08:55', 'Cuban and German immigrants were planting tobacco in the San Andrés valley as early as the 1830s. In 1880 the Cuban grower Alberto Turrent left his island to settle there with his seed — the lineage is direct.', 'Inmigrantes cubanos y alemanes plantan tabaco en el valle de San Andrés ya en los años 1830. En 1880, el cultivador cubano Alberto Turrent deja su isla para instalarse allí con sus semillas: la filiación es directa.', 'Kubanische und deutsche Einwanderer pflanzten schon in den 1830er Jahren Tabak im Tal von San Andrés. 1880 verließ der kubanische Pflanzer Alberto Turrent seine Insel und ließ sich dort mit seinem Saatgut nieder — die Abstammung ist unmittelbar.', '早在 1830 年代，古巴与德国移民便在圣安德烈斯谷地种植烟草。1880 年，古巴种植者 Alberto Turrent 离开故岛，带着自己的烟种在此定居——血脉直接相承。', 'زرع مهاجرون كوبيون وألمان التبغ في وادي سان أندريس منذ ثلاثينيات القرن التاسع عشر. وفي 1880 غادر المزارع الكوبي ألبرتو توران جزيرته ليستقرّ هناك ببذوره — والنسب مباشر.', 'The valley rises to some 1,200 metres on the edge of the Gulf of Mexico: a climate cooler than the latitude would suggest, humid breezes off the coast, soils enriched by the volcano.', 'El valle se eleva a unos 1.200 metros junto al golfo de México: clima más fresco de lo que cabría esperar en esa latitud, brisas húmedas de la costa, suelos enriquecidos por el volcán.', 'Das Tal steigt am Rand des Golfs von Mexiko auf rund 1.200 Meter: ein Klima, kühler als die Breite erwarten ließe, feuchte Brisen von der Küste, vom Vulkan angereicherte Böden.', '谷地在墨西哥湾畔升至约 1200 米：气候比该纬度应有的更为凉爽，海岸吹来湿润的微风，土壤则得火山之利。', 'يرتفع الوادي نحو 1200 متر على حافة خليج المكسيك: مناخ أبرد ممّا يوحي به خط العرض، ونسائم رطبة من الساحل، وتربة أغناها البركان.', 'A dark leaf cut by the stalk, like Connecticut broadleaf. It withstands high fermentation temperatures, which makes it a leading maduro wrapper.', 'Hoja oscura que se corta por el tallo, como el broadleaf de Connecticut. Soporta temperaturas de fermentación elevadas, lo que la convierte en una capa maduro de primer orden.', 'Ein dunkles Blatt, das am Stängel geschnitten wird wie das Connecticut-Broadleaf. Es hält hohe Fermentationstemperaturen aus, was es zu einem führenden Maduro-Deckblatt macht.', '深色叶片，连茎采收，与康涅狄格 broadleaf 同法。它能承受较高的发酵温度，因而成为首屈一指的 maduro 茄衣。', 'ورقة داكنة تُقطع بالساق، مثل البرودليف الكونيتيكتي. تتحمّل درجات تخمير مرتفعة، ما يجعلها غلاف مادورو في الطليعة.', '[\"Dark chocolate\",\"Pepper\",\"Earth\"]', '[\"Chocolate negro\",\"Pimienta\",\"Tierra\"]', '[\"Zartbitterschokolade\",\"Pfeffer\",\"Erde\"]', '[\"黑巧克力\",\"胡椒\",\"泥土\"]', '[\"شوكولاتة داكنة\",\"فلفل\",\"تراب\"]', '[\"Mezcal\",\"Strong coffee\",\"Hot chocolate\"]', '[\"Mezcal\",\"Café cargado\",\"Chocolate caliente\"]', '[\"Mezcal\",\"Starker Kaffee\",\"Heiße Schokolade\"]', '[\"梅斯卡尔酒\",\"浓缩咖啡\",\"热巧克力\"]', '[\"مسكال\",\"قهوة مركزة\",\"شوكولاتة ساخنة\"]', 'Maduro wrapper and binder', 'Capa maduro y capote', 'Maduro-Deckblatt und Umblatt', '马杜罗茄衣与茄套', 'غلاف مادورو ورابط'),
  ('nicaragua-corojo-99', 'Corojo 99', 'nicaragua', 'Cape et tripe', 'Le croisement du Criollo 98 avec le Corojo de 1947 — celui de Diego Rodríguez, que la maladie avait chassé des champs cubains. Le but était de retrouver son goût sans sa fragilité, et c\'est ce que porte son nom.', 'Mêmes vallées que le Criollo 98, et les deux se partagent le gros des surfaces nicaraguayennes.', 'Feuille plus longue que sa parente : la largeur n\'y fait que 55 % de la longueur, une proportion qui convient à la cape. Elle garde du Corojo l\'épice et le cèdre.', '[\"Épices\",\"Cèdre\",\"Cuir\"]', '[\"Rhum vieux\",\"Café noir\",\"Cacao\"]', '2026-08-21 20:09:51', '2026-08-22 22:08:55', 'A cross of Criollo 98 with the Corojo of 1947 — Diego Rodríguez\'s, which disease had driven from Cuban fields. The aim was to recover its taste without its frailty, and its name says so.', 'El cruce del Criollo 98 con el Corojo de 1947, el de Diego Rodríguez, al que la enfermedad había expulsado de los campos cubanos. El objetivo era recuperar su sabor sin su fragilidad, y eso lleva en el nombre.', 'Die Kreuzung von Criollo 98 mit dem Corojo von 1947 — jenem von Diego Rodríguez, den die Krankheit von Kubas Feldern vertrieben hatte. Ziel war, seinen Geschmack ohne seine Anfälligkeit zurückzugewinnen; das trägt sie im Namen.', 'Criollo 98 与 1947 年 Corojo 的杂交——即被病害逐出古巴田野的那一支，Diego Rodríguez 所育。目的是找回其风味而不带其脆弱，这一点就写在它的名字里。', 'تهجين الكريولو 98 مع الكوروخو الذي أنتجه دييغو رودريغيز عام 1947، والذي طرده المرض من حقول كوبا. كان الهدف استعادة مذاقه دون هشاشته، وهذا ما يحمله اسمها.', 'The same valleys as Criollo 98, and the two share the bulk of Nicaragua\'s acreage.', 'Los mismos valles que el Criollo 98, y ambos se reparten el grueso de la superficie nicaragüense.', 'Dieselben Täler wie Criollo 98; beide teilen sich den Großteil der nicaraguanischen Anbaufläche.', '与 Criollo 98 同处三谷，二者分占尼加拉瓜的大部分种植面积。', 'الوديان نفسها التي يُزرع فيها الكريولو 98، والاثنان يتقاسمان معظم المساحات النيكاراغوية.', 'A longer leaf than its parent: width is only 55 per cent of length, a proportion that suits a wrapper. From Corojo it keeps the spice and the cedar.', 'Hoja más larga que su progenitora: la anchura es solo el 55 % de la longitud, proporción que conviene a la capa. Del Corojo conserva la especia y el cedro.', 'Ein längeres Blatt als sein Elternteil: die Breite beträgt nur 55 Prozent der Länge, eine Proportion, die zum Deckblatt passt. Vom Corojo behält es Würze und Zeder.', '叶片较其亲本更长：宽度仅为长度的 55%，这一比例适合作茄衣。它保留了 Corojo 的辛香与雪松气息。', 'ورقة أطول من سالفتها: عرضها 55 بالمئة فقط من طولها، وهي نسبة تلائم الغلاف. وتحتفظ من الكوروخو بالتوابل والأرز.', '[\"Spice\",\"Cedar\",\"Leather\"]', '[\"Especias\",\"Cedro\",\"Cuero\"]', '[\"Gewürze\",\"Zeder\",\"Leder\"]', '[\"香料\",\"雪松\",\"皮革\"]', '[\"توابل\",\"أرز\",\"جلد\"]', '[\"Aged rum\",\"Black coffee\",\"Cocoa\"]', '[\"Ron añejo\",\"Café solo\",\"Cacao\"]', '[\"Alter Rum\",\"Schwarzer Kaffee\",\"Kakao\"]', '[\"陈年朗姆\",\"黑咖啡\",\"可可\"]', '[\"روم معتّق\",\"قهوة سوداء\",\"كاكاو\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('nicaragua-criollo-98', 'Criollo 98', 'nicaragua', 'Tripe et sous-cape', 'Une réponse cubaine au moho azul : le croisement de Havana 92 et de Habana P.R., sélectionné pour résister au champignon qui avait détruit les récoltes de la fin des années 1970. Le Nicaragua l\'a adoptée et en a fait l\'une de ses deux semences principales.', 'Cultivée dans les trois vallées du nord — Estelí, Jalapa, Condega — qui se partagent l\'essentiel des surfaces avec le Corojo 99.', 'Feuille courte : sa largeur fait 65 % de sa longueur, ce qui la destine à la tripe et à la sous-cape plutôt qu\'à la cape. Elle apporte l\'arôme et la force.', '[\"Force\",\"Arôme\",\"Épices\"]', '[\"Rhum nicaraguayen\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 20:09:51', '2026-08-22 22:08:55', 'A Cuban answer to blue mould: a cross of Havana 92 and Habana P.R., selected to resist the fungus that had destroyed the harvests of the late 1970s. Nicaragua adopted it and made it one of its two main seeds.', 'Una respuesta cubana al moho azul: el cruce de Havana 92 y Habana P.R., seleccionado para resistir al hongo que había destruido las cosechas de finales de los setenta. Nicaragua la adoptó y la convirtió en una de sus dos semillas principales.', 'Eine kubanische Antwort auf den Blauschimmel: eine Kreuzung aus Havana 92 und Habana P.R., ausgelesen, um dem Pilz zu widerstehen, der die Ernten der späten 1970er vernichtet hatte. Nicaragua übernahm sie und machte sie zu einem seiner beiden Hauptsamen.', '古巴对霉霜病的回应：Havana 92 与 Habana P.R. 的杂交种，专为抵抗那场毁掉七十年代末收成的真菌而选育。尼加拉瓜采纳了它，使之成为本国两大主力烟种之一。', 'ردّ كوبي على العفن الأزرق: تهجين بين Havana 92 وHabana P.R.، انتُخب لمقاومة الفطر الذي دمّر محاصيل أواخر السبعينيات. تبنّته نيكاراغوا وجعلته أحد بذرتيها الرئيسيتين.', 'Grown in the three northern valleys — Estelí, Jalapa, Condega — which share most of the acreage with Corojo 99.', 'Cultivada en los tres valles del norte —Estelí, Jalapa, Condega— que se reparten la mayor parte de la superficie con el Corojo 99.', 'In den drei nördlichen Tälern angebaut — Estelí, Jalapa, Condega —, die sich den Großteil der Fläche mit Corojo 99 teilen.', '种植于北部三大谷地——埃斯特利、哈拉帕、孔德加——它与 Corojo 99 分占了大部分种植面积。', 'تُزرع في الوديان الشمالية الثلاثة — إستيلي وخالابا وكونديغا — التي تتقاسم معظم المساحات مع الكوروخو 99.', 'A short leaf: its width is 65 per cent of its length, which suits it to filler and binder rather than wrapper. It brings aroma and strength.', 'Hoja corta: su anchura es el 65 % de su longitud, lo que la destina a la tripa y al capote más que a la capa. Aporta aroma y fuerza.', 'Ein kurzes Blatt: seine Breite beträgt 65 Prozent der Länge, was es eher für Einlage und Umblatt als für das Deckblatt bestimmt. Es bringt Aroma und Kraft.', '叶片较短：宽度为长度的 65%，因而更适合作茄芯与茄套，而非茄衣。它带来香气与力度。', 'ورقة قصيرة: عرضها 65 بالمئة من طولها، ما يجعلها للحشوة والرابط أكثر منها للغلاف. تمنح العطر والقوة.', '[\"Strength\",\"Aroma\",\"Spice\"]', '[\"Fuerza\",\"Aroma\",\"Especias\"]', '[\"Kraft\",\"Aroma\",\"Gewürze\"]', '[\"力度\",\"香气\",\"香料\"]', '[\"قوة\",\"عطر\",\"توابل\"]', '[\"Nicaraguan rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron nicaragüense\",\"Café cargado\",\"Chocolate negro\"]', '[\"Nicaraguanischer Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"尼加拉瓜朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم نيكاراغوي\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Filler and binder', 'Tripa y capote', 'Einlage und Umblatt', '茄芯与茄套', 'حشوة ورابط'),
  ('nicaragua-habano', 'Habano', 'nicaragua', 'Cape et tripe', 'Ce n\'est pas une variété au sens strict mais un nom de famille : celui des semences de souche cubaine cultivées hors de Cuba. Criollo 98 et Corojo 99 en sont deux membres datés ; quelques hectares nicaraguayens portent encore la génération d\'avant, Havana 92.', 'Le mot suit la semence partout où elle s\'exporte — l\'atlas le retrouve en Équateur et au Panama, sur des terres qui n\'ont rien de cubain.', 'Ce que le mot promet, c\'est une filiation plutôt qu\'un profil : de l\'épice, du corps, et le caractère qu\'on associe au tabac cubain, tempéré par le sol qui l\'accueille.', '[\"Épices\",\"Corps\",\"Terre\"]', '[\"Rhum ambré\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 20:09:51', '2026-08-22 22:08:55', 'Not a variety in the strict sense but a family name: that of Cuban-stock seeds grown outside Cuba. Criollo 98 and Corojo 99 are two dated members; a few Nicaraguan hectares still carry the previous generation, Havana 92.', 'No es una variedad en sentido estricto, sino un apellido: el de las semillas de cepa cubana cultivadas fuera de Cuba. Criollo 98 y Corojo 99 son dos miembros fechados; unas pocas hectáreas nicaragüenses llevan aún la generación anterior, Havana 92.', 'Keine Sorte im strengen Sinn, sondern ein Familienname: der der Samen kubanischer Herkunft, die außerhalb Kubas angebaut werden. Criollo 98 und Corojo 99 sind zwei datierte Mitglieder; einige nicaraguanische Hektar tragen noch die Vorgängergeneration, Havana 92.', '严格说来它不是一个品种，而是一个姓氏：指在古巴以外种植的古巴血统烟种。Criollo 98 与 Corojo 99 是其中两位有确切年份的成员；尼加拉瓜仍有少量田块种着上一代的 Havana 92。', 'ليست صنفًا بالمعنى الدقيق بل اسم عائلة: عائلة البذور ذات الأصل الكوبي المزروعة خارج كوبا. الكريولو 98 والكوروخو 99 عضوان مؤرَّخان فيها؛ ولا تزال بضعة هكتارات نيكاراغوية تحمل الجيل السابق، Havana 92.', 'The word follows the seed wherever it travels — the atlas meets it again in Ecuador and Panama, on ground that has nothing Cuban about it.', 'La palabra sigue a la semilla allí donde se exporta: el atlas la reencuentra en Ecuador y Panamá, en tierras que nada tienen de cubanas.', 'Das Wort folgt dem Samen überallhin — der Atlas trifft es in Ecuador und Panama wieder, auf Böden, die nichts Kubanisches haben.', '这个词随烟种四处旅行——本图册在厄瓜多尔与巴拿马再度遇见它，而那里的土地与古巴毫无关系。', 'تتبع الكلمة البذرة أينما صُدِّرت — ويلتقيها الأطلس مجددًا في الإكوادور وبنما، على أراضٍ لا شيء فيها كوبي.', 'What the word promises is a lineage rather than a profile: spice, body, and the character associated with Cuban tobacco, tempered by the soil that receives it.', 'Lo que la palabra promete es una filiación más que un perfil: especia, cuerpo y el carácter que se asocia al tabaco cubano, templado por el suelo que lo acoge.', 'Was das Wort verspricht, ist eine Abstammung, kein Profil: Würze, Körper und der Charakter, den man kubanischem Tabak zuschreibt, gemildert vom Boden, der ihn aufnimmt.', '这个词许诺的是血统而非风味图谱：辛香、厚度，以及人们心目中古巴烟草的性格，再由承载它的土壤加以调和。', 'ما تَعِد به الكلمة نسبٌ لا ملمح: توابل وقوام، والطابع الذي يُنسب إلى التبغ الكوبي، تلطّفه التربة التي تحتضنه.', '[\"Spice\",\"Body\",\"Earth\"]', '[\"Especias\",\"Cuerpo\",\"Tierra\"]', '[\"Gewürze\",\"Körper\",\"Erde\"]', '[\"香料\",\"厚度\",\"泥土\"]', '[\"توابل\",\"قوام\",\"تراب\"]', '[\"Amber rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron ámbar\",\"Café cargado\",\"Chocolate negro\"]', '[\"Bernsteinfarbener Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"琥珀朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم كهرماني\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('nicaragua-havana-92', 'Havana 92', 'nicaragua', 'Tripe et sous-cape', 'La génération d\'avant. C\'est elle que les agronomes cubains ont croisée avec Habana P.R. pour obtenir le Criollo 98, lequel a ensuite été recroisé avec le Corojo de 1947 pour donner le Corojo 99. Les trois feuilles nicaraguayennes sont donc trois étapes de la même lignée, née de la lutte contre le moho azul.', 'Ses deux descendantes se partagent l\'essentiel des surfaces du pays ; elle n\'occupe plus que quelques hectares. Une semence qu\'on n\'a pas abandonnée, sans qu\'elle soit redevenue majoritaire.', 'Les sources la citent comme semence encore en terre sans en décrire le profil. Cette fiche dit donc sa place dans la lignée, qui est établie, et s\'abstient de lui prêter des arômes que personne ne lui attribue : ce qu\'on lui connaît est celui de la famille Habano.', '[\"Épices\",\"Corps\",\"Terre\"]', '[\"Rhum ambré\",\"Café serré\",\"Chocolat noir\"]', '2026-08-22 00:05:14', '2026-08-22 22:08:55', 'The previous generation. It was this that Cuban agronomists crossed with Habana P.R. to obtain Criollo 98, which was then crossed again with the Corojo of 1947 to give Corojo 99. Nicaragua\'s three leaves are thus three stages of a single line, born of the fight against blue mould.', 'La generación anterior. Es a ella a quien los agrónomos cubanos cruzaron con Habana P.R. para obtener el Criollo 98, que luego se recruzó con el Corojo de 1947 para dar el Corojo 99. Las tres hojas nicaragüenses son, pues, tres etapas de un mismo linaje, nacido de la lucha contra el moho azul.', 'Die Generation davor. Sie kreuzten kubanische Agronomen mit Habana P.R., um Criollo 98 zu erhalten, das später erneut mit dem Corojo von 1947 gekreuzt wurde und Corojo 99 ergab. Die drei nicaraguanischen Blätter sind somit drei Etappen derselben Linie, geboren aus dem Kampf gegen den Blauschimmel.', '上一代。正是它被古巴农学家与 Habana P.R. 杂交，得到 Criollo 98；后者又与 1947 年的 Corojo 回交，育成 Corojo 99。因此尼加拉瓜的三片烟叶，实为同一血脉的三个阶段，皆生于对抗霉霜病之役。', 'الجيل السابق. هي التي هجّنها المهندسون الزراعيون الكوبيون مع Habana P.R. للحصول على الكريولو 98، الذي هُجّن بدوره مع كوروخو 1947 فأعطى الكوروخو 99. فأوراق نيكاراغوا الثلاث إذن ثلاث مراحل من سلالة واحدة، وُلدت من معركة العفن الأزرق.', 'Its two descendants share most of the country\'s acreage; it now occupies only a few hectares. A seed that was not abandoned, without ever becoming dominant again.', 'Sus dos descendientes se reparten la mayor parte de la superficie del país; ella ya solo ocupa unas pocas hectáreas. Una semilla que no se abandonó, sin que haya vuelto a ser mayoritaria.', 'Ihre beiden Nachkommen teilen sich den Großteil der Anbaufläche des Landes; sie selbst nimmt nur noch einige Hektar ein. Ein Samen, den man nicht aufgegeben hat, ohne dass er wieder vorherrschend geworden wäre.', '它的两个后代分占了全国大部分种植面积；它自身如今只余寥寥数公顷。一枚未被放弃的烟种，却也未再成为主流。', 'تتقاسم سليلتاها معظم مساحات البلاد؛ أما هي فلم تعد تشغل سوى بضعة هكتارات. بذرة لم تُهجر، دون أن تعود إلى الصدارة.', 'Sources mention it as a seed still in the ground without describing its profile. This entry therefore states its place in the line, which is established, and refrains from lending it aromas no one attributes to it: what is known of it is that of the Habano family.', 'Las fuentes la citan como semilla aún en tierra sin describir su perfil. Esta ficha dice, pues, su lugar en el linaje, que está establecido, y se abstiene de prestarle aromas que nadie le atribuye: lo que se le conoce es el de la familia Habano.', 'Die Quellen nennen sie als Samen, der noch im Boden ist, ohne ihr Profil zu beschreiben. Dieser Eintrag nennt daher ihren Platz in der Linie, der gesichert ist, und verzichtet darauf, ihr Aromen anzudichten, die ihr niemand zuschreibt: Bekannt ist von ihr das der Habano-Familie.', '资料只提到它仍在土中，却未描述其风味特征。因此本条目只陈述它在血脉中的位置——这一点是确凿的——而不为它附会无人赋予的香气：人们所知的，是 Habano 一族的风味。', 'تذكرها المصادر بوصفها بذرة لا تزال في الأرض دون أن تصف ملمحها. لذا تقول هذه البطاقة موضعها في السلالة، وهو ثابت، وتمتنع عن أن تنسب إليها روائح لا ينسبها إليها أحد: فما يُعرف عنها هو ما يُعرف عن عائلة هابانو.', '[\"Spice\",\"Body\",\"Earth\"]', '[\"Especias\",\"Cuerpo\",\"Tierra\"]', '[\"Gewürze\",\"Körper\",\"Erde\"]', '[\"香料\",\"厚度\",\"泥土\"]', '[\"توابل\",\"قوام\",\"تراب\"]', '[\"Amber rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron ámbar\",\"Café cargado\",\"Chocolate negro\"]', '[\"Bernsteinfarbener Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"琥珀朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم كهرماني\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Filler and binder', 'Tripa y capote', 'Einlage und Umblatt', '茄芯与茄套', 'حشوة ورابط'),
  ('panama-corojo', 'Corojo Panamá', 'panama', 'Cape', 'La semence de 1947, celle de Diego Rodríguez, arrivée jusqu\'aux montagnes de Chiriquí. Elle a fait le même voyage qu\'au Honduras — mais sur une terre dont la vocation tabacière avait survécu à une interdiction royale plutôt qu\'à une maladie.', 'Culture d\'altitude dans le Chiriquí, sur les pentes du Volcán Barú. Le pays revendique plus de cent ans de fabrication de cigares, malgré les siècles perdus.', 'Elle porte le nom d\'une lignée dont l\'atlas suit déjà la trace à Cuba et au Honduras. Ce qu\'en fait le Panama tient à ses hauteurs et à son sol volcanique.', '[\"Épices\",\"Cèdre\",\"Poivre\"]', '[\"Rhum vieux\",\"Café noir\",\"Cacao\"]', '2026-08-21 22:52:19', '2026-08-22 22:08:55', 'The seed of 1947, Diego Rodríguez\'s, carried as far as the mountains of Chiriquí. It made the same journey as to Honduras — but onto ground whose tobacco calling had survived a royal ban rather than a disease.', 'La semilla de 1947, la de Diego Rodríguez, llegada hasta las montañas de Chiriquí. Hizo el mismo viaje que a Honduras, pero a una tierra cuya vocación tabacalera había sobrevivido a una prohibición real y no a una enfermedad.', 'Der Samen von 1947, jener von Diego Rodríguez, bis in die Berge von Chiriquí gelangt. Er machte dieselbe Reise wie nach Honduras — nur auf einen Boden, dessen Tabakberufung ein königliches Verbot überlebt hatte statt einer Krankheit.', '1947 年的烟种，Diego Rodríguez 所育，一路抵达奇里基的山间。它走的路与去洪都拉斯的相同——只是这片土地的烟草天职，是从一道王室禁令而非一场病害中幸存下来的。', 'بذرة عام 1947، بذرة دييغو رودريغيز، بلغت جبال تشيريكي. قطعت الرحلة نفسها التي قطعتها إلى هندوراس — لكن إلى أرض نجت رسالتها التبغية من حظر ملكي لا من مرض.', 'High-altitude growing in Chiriquí, on the slopes of Volcán Barú. The country claims more than a hundred years of cigar making, despite the lost centuries.', 'Cultivo de altura en Chiriquí, en las laderas del Volcán Barú. El país reivindica más de cien años de fabricación de puros, pese a los siglos perdidos.', 'Höhenanbau in Chiriquí, an den Hängen des Volcán Barú. Das Land beansprucht über hundert Jahre Zigarrenherstellung, trotz der verlorenen Jahrhunderte.', '在奇里基高海拔种植，位于巴鲁火山的山坡。尽管失去了几个世纪，该国仍宣称拥有逾百年的雪茄制造史。', 'زراعة على ارتفاع في تشيريكي، على منحدرات بركان بارو. وتدّعي البلاد أكثر من مئة عام من صناعة السيجار، رغم القرون الضائعة.', 'It bears the name of a line the atlas already tracks in Cuba and Honduras. What Panama makes of it owes to its heights and its volcanic soil.', 'Lleva el nombre de un linaje cuyo rastro el atlas ya sigue en Cuba y Honduras. Lo que Panamá hace de él se debe a sus alturas y a su suelo volcánico.', 'Es trägt den Namen einer Linie, deren Spur der Atlas bereits in Kuba und Honduras verfolgt. Was Panama daraus macht, verdankt sich seinen Höhen und seinem vulkanischen Boden.', '它承袭的是本图册已在古巴与洪都拉斯追踪过的血脉之名。巴拿马赋予它的，源自这里的高度与火山土壤。', 'تحمل اسم سلالة يتتبّع الأطلس أثرها في كوبا وهندوراس. وما يصنعه بنما منها يعود إلى مرتفعاته وتربته البركانية.', '[\"Spice\",\"Cedar\",\"Pepper\"]', '[\"Especias\",\"Cedro\",\"Pimienta\"]', '[\"Gewürze\",\"Zeder\",\"Pfeffer\"]', '[\"香料\",\"雪松\",\"胡椒\"]', '[\"توابل\",\"أرز\",\"فلفل\"]', '[\"Aged rum\",\"Black coffee\",\"Cocoa\"]', '[\"Ron añejo\",\"Café solo\",\"Cacao\"]', '[\"Alter Rum\",\"Schwarzer Kaffee\",\"Kakao\"]', '[\"陈年朗姆\",\"黑咖啡\",\"可可\"]', '[\"روم معتّق\",\"قهوة سوداء\",\"كاكاو\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف'),
  ('panama-habano', 'Habano Panamá', 'panama', 'Cape et tripe', 'Une semence de la famille cubaine, plantée dans un pays où le tabac fut longtemps interdit : au XVIe siècle, Philippe II d\'Espagne en défendit la culture au Panama sous peine de mort, pour ne pas concurrencer Cuba. La tradition s\'y est perdue — sauf à Chiriquí, où l\'on n\'a jamais cessé de récolter.', 'Tout le tabac panaméen vient de la province de Chiriquí, à l\'ouest. Le cœur de la production s\'appelle Sortova, haut dans les montagnes : c\'est la terre la plus réputée du pays.', 'Ce que le nom promet est une filiation plutôt qu\'un profil, comme partout où la semence cubaine s\'est exportée. Ce qui distingue celle-ci est le lieu, pas la graine.', '[\"Épices\",\"Corps\",\"Terre\"]', '[\"Rhum ambré\",\"Café serré\",\"Chocolat noir\"]', '2026-08-21 22:52:19', '2026-08-22 22:08:55', 'A seed of the Cuban family, planted in a country where tobacco was long forbidden: in the sixteenth century Philip II of Spain banned its cultivation in Panama on pain of death, so as not to compete with Cuba. The tradition was lost there — except in Chiriquí, where harvesting never stopped.', 'Una semilla de la familia cubana, plantada en un país donde el tabaco estuvo largo tiempo prohibido: en el siglo XVI Felipe II de España vedó su cultivo en Panamá bajo pena de muerte, para no competir con Cuba. La tradición se perdió allí, salvo en Chiriquí, donde nunca se dejó de cosechar.', 'Ein Samen der kubanischen Familie, gepflanzt in einem Land, in dem Tabak lange verboten war: Im 16. Jahrhundert untersagte Philipp II. von Spanien seinen Anbau in Panama bei Todesstrafe, um Kuba keine Konkurrenz zu machen. Die Tradition ging dort verloren — außer in Chiriquí, wo nie aufgehört wurde zu ernten.', '一枚古巴血统的烟种，种在一个曾长期禁烟的国度：十六世纪，西班牙国王腓力二世下令禁止在巴拿马种植烟草，违者处死，以免与古巴竞争。传统因此断绝——唯独奇里基除外，那里从未停止收获。', 'بذرة من العائلة الكوبية، زُرعت في بلد حُظر فيه التبغ طويلًا: ففي القرن السادس عشر منع فيليب الثاني ملك إسبانيا زراعته في بنما تحت طائلة الإعدام، لئلّا يُنافس كوبا. فضاع التقليد هناك — إلا في تشيريكي، حيث لم يتوقف الحصاد قط.', 'All Panamanian tobacco comes from the province of Chiriquí, in the west. The heart of production is called Sortova, high in the mountains: the country\'s most celebrated ground.', 'Todo el tabaco panameño viene de la provincia de Chiriquí, al oeste. El corazón de la producción se llama Sortova, alto en las montañas: la tierra más reputada del país.', 'Aller panamaische Tabak stammt aus der westlichen Provinz Chiriquí. Das Herz der Produktion heißt Sortova, hoch in den Bergen: der renommierteste Boden des Landes.', '巴拿马的烟草全部来自西部的奇里基省。产区的核心名为 Sortova，高踞山间：这是全国最负盛名的土地。', 'كل التبغ البنمي يأتي من مقاطعة تشيريكي غربًا. وقلب الإنتاج يُسمّى سورتوفا، عاليًا في الجبال: وهي أشهر أرض في البلاد.', 'What the name promises is a lineage rather than a profile, as everywhere the Cuban seed has travelled. What sets this one apart is the place, not the seed.', 'Lo que el nombre promete es una filiación más que un perfil, como en todas partes donde se ha exportado la semilla cubana. Lo que distingue a esta es el lugar, no el grano.', 'Was der Name verspricht, ist eine Abstammung, kein Profil — wie überall, wohin der kubanische Samen gelangt ist. Was diesen auszeichnet, ist der Ort, nicht das Korn.', '这个名字许诺的是血统而非风味图谱，一如古巴烟种所到之处皆然。让这一支与众不同的是地方，而非种子。', 'ما يَعِد به الاسم نسبٌ لا ملمح، كما في كل مكان صُدِّرت إليه البذرة الكوبية. وما يميّز هذه هو المكان لا الحبّة.', '[\"Spice\",\"Body\",\"Earth\"]', '[\"Especias\",\"Cuerpo\",\"Tierra\"]', '[\"Gewürze\",\"Körper\",\"Erde\"]', '[\"香料\",\"厚度\",\"泥土\"]', '[\"توابل\",\"قوام\",\"تراب\"]', '[\"Amber rum\",\"Strong coffee\",\"Dark chocolate\"]', '[\"Ron ámbar\",\"Café cargado\",\"Chocolate negro\"]', '[\"Bernsteinfarbener Rum\",\"Starker Kaffee\",\"Zartbitterschokolade\"]', '[\"琥珀朗姆\",\"浓缩咖啡\",\"黑巧克力\"]', '[\"روم كهرماني\",\"قهوة مركزة\",\"شوكولاتة داكنة\"]', 'Wrapper and filler', 'Capa y tripa', 'Deckblatt und Einlage', '茄衣与茄芯', 'غلاف وحشوة'),
  ('philippines-cagayan', 'Tabac natif de Cagayan', 'philippines', 'Cape, sous-cape et tripe', 'La semence a suivi la foi : ce sont les frères missionnaires qui l\'ont répandue dans l\'archipel, et qui ont trouvé qu\'elle prospérait dans la vallée de Cagayan, province d\'Isabela. L\'Espagne y tint un monopole du tabac jusqu\'à son abolition en 1881 — l\'année même où le marquis de Comillas fonde à Barcelone la compagnie qui lui succédera, et dont la manufacture de Manille sera la première fabrique de cigares d\'Asie.', 'La vallée de Cagayan s\'étend à quatre cents kilomètres au nord de Manille. Son climat est proche de celui de la Vuelta Abajo cubaine, et c\'est ce qui a décidé de sa vocation.', 'Ce n\'est pas un cultivar mais une famille de souches locales — Cimaba, Viscaya, Isabela — dont on ne lit les noms nulle part ailleurs. La dernière a donné le sien à la maison La Flor de la Isabela, fondée en 1885 : ici, la marque et la plante sont la même chose.', '[\"Bois\",\"Terre\",\"Épices douces\"]', '[\"Thé noir\",\"Café allongé\",\"Fruits secs\"]', '2026-08-21 23:11:41', '2026-08-22 22:08:55', 'The seed followed the faith: friars spread it through the archipelago and found it thrived in the Cagayan valley, province of Isabela. Spain held a tobacco monopoly there until its abolition in 1881 — the very year the Marquis of Comillas founded in Barcelona the company that would succeed it, whose Manila works would be the first cigar factory in Asia.', 'La semilla siguió a la fe: fueron los frailes quienes la difundieron por el archipiélago y hallaron que prosperaba en el valle de Cagayán, provincia de Isabela. España mantuvo allí un monopolio del tabaco hasta su abolición en 1881, el mismo año en que el marqués de Comillas funda en Barcelona la compañía que lo sucederá, cuya fábrica de Manila será la primera de puros de Asia.', 'Der Samen folgte dem Glauben: Mönche verbreiteten ihn im Archipel und fanden, dass er im Cagayan-Tal in der Provinz Isabela gedieh. Spanien hielt dort ein Tabakmonopol bis zu dessen Abschaffung 1881 — im selben Jahr gründete der Marquis von Comillas in Barcelona die Nachfolgegesellschaft, deren Manufaktur in Manila die erste Zigarrenfabrik Asiens sein sollte.', '烟种随信仰而行：是传教修士将它带遍群岛，并发现它在伊莎贝拉省的卡加延河谷生长最好。西班牙在此维持烟草专营，直至 1881 年废止——同年，科米利亚斯侯爵在巴塞罗那创立了承接其业的公司，其马尼拉工厂将成为亚洲第一家雪茄厂。', 'تبعت البذرة الإيمان: فالرهبان المبشّرون هم من نشروها في الأرخبيل، ووجدوا أنها تزدهر في وادي كاغايان بمقاطعة إيزابيلا. واحتكرت إسبانيا التبغ هناك حتى إلغاء الاحتكار عام 1881 — وهو العام نفسه الذي أسّس فيه ماركيز كوميّاس في برشلونة الشركة الخلف، والتي سيكون مصنعها في مانيلا أول مصنع سيجار في آسيا.', 'The Cagayan valley lies four hundred kilometres north of Manila. Its climate is close to that of Cuba\'s Vuelta Abajo, and that is what settled its calling.', 'El valle de Cagayán se extiende a cuatrocientos kilómetros al norte de Manila. Su clima se acerca al de la Vuelta Abajo cubana, y eso decidió su vocación.', 'Das Cagayan-Tal liegt vierhundert Kilometer nördlich von Manila. Sein Klima kommt dem der kubanischen Vuelta Abajo nahe, und das entschied über seine Bestimmung.', '卡加延河谷位于马尼拉以北四百公里处。其气候近似古巴的下维尔塔，这正决定了它的天职。', 'يمتد وادي كاغايان على بعد أربعمئة كيلومتر شمال مانيلا. ومناخه قريب من مناخ فويلتا أباخو الكوبية، وهذا ما حسم رسالته.', 'Not a cultivar but a family of local strains — Cimaba, Viscaya, Isabela — whose names are read nowhere else. The last gave its own to the house of La Flor de la Isabela, founded in 1885: here, the brand and the plant are one and the same.', 'No es un cultivar sino una familia de cepas locales —Cimaba, Viscaya, Isabela— cuyos nombres no se leen en ninguna otra parte. La última dio el suyo a la casa La Flor de la Isabela, fundada en 1885: aquí, la marca y la planta son la misma cosa.', 'Kein Cultivar, sondern eine Familie lokaler Sorten — Cimaba, Viscaya, Isabela —, deren Namen man nirgends sonst liest. Die letzte gab ihren dem Haus La Flor de la Isabela, gegründet 1885: Hier sind Marke und Pflanze dasselbe.', '这不是一个栽培种，而是一族本地品系——Cimaba、Viscaya、Isabela——它们的名字别处读不到。最后一个把自己的名字给了 1885 年创立的 La Flor de la Isabela：在这里，品牌与植株本是一回事。', 'ليست صنفًا مستنبتًا بل عائلة من السلالات المحلية — سيمابا، بيسكايا، إيزابيلا — لا تُقرأ أسماؤها في مكان آخر. وقد أعطت الأخيرة اسمها لدار «لا فلور دي لا إيزابيلا» المؤسَّسة عام 1885: هنا العلامة والنبتة شيء واحد.', '[\"Wood\",\"Earth\",\"Sweet spice\"]', '[\"Madera\",\"Tierra\",\"Especias dulces\"]', '[\"Holz\",\"Erde\",\"Milde Gewürze\"]', '[\"木质\",\"泥土\",\"甜香料\"]', '[\"خشب\",\"تراب\",\"توابل حلوة\"]', '[\"Black tea\",\"Long black coffee\",\"Dried fruit\"]', '[\"Té negro\",\"Café largo\",\"Frutos secos\"]', '[\"Schwarzer Tee\",\"Verlängerter Kaffee\",\"Trockenfrüchte\"]', '[\"红茶\",\"美式咖啡\",\"果干\"]', '[\"شاي أسود\",\"قهوة مطوّلة\",\"فواكه مجففة\"]', 'Wrapper, binder and filler', 'Capa, capote y tripa', 'Deckblatt, Umblatt und Einlage', '茄衣、茄套与茄芯', 'غلاف ورابط وحشوة'),
  ('usa-broadleaf', 'Connecticut Broadleaf', 'usa', 'Cape maduro et sous-cape', 'C\'est l\'aînée : avant 1900, la vallée du Connecticut ne cultivait qu\'elle. L\'arrivée de la cape d\'ombre ne l\'a pas remplacée — elle lui a donné un rôle opposé, celui des cigares sombres.', 'Plein soleil, et les plants espacés d\'une soixantaine de centimètres pour que la feuille prenne toute sa taille. Elle se coupe à la tige entière, et non feuille à feuille comme la cape d\'ombre.', 'Feuille épaisse, grasse et très veinée, d\'une couleur profonde après séchage. Elle brûle lentement et porte un goût appuyé — tout le contraire de sa voisine d\'ombre.', '[\"Cacao\",\"Terre\",\"Sucre brûlé\"]', '[\"Bourbon\",\"Café noir\",\"Stout\"]', '2026-08-21 18:14:54', '2026-08-22 22:08:55', 'It is the elder: before 1900 the Connecticut Valley grew nothing else. The arrival of the shade wrapper did not replace it — it gave it the opposite role, that of dark cigars.', 'Es la mayor: antes de 1900 el valle del Connecticut solo la cultivaba a ella. La llegada de la capa de sombra no la sustituyó, sino que le dio un papel opuesto, el de los puros oscuros.', 'Sie ist die Ältere: Vor 1900 baute das Connecticut-Tal nichts anderes an. Das Schattendeckblatt hat sie nicht verdrängt — es gab ihr die entgegengesetzte Rolle, die der dunklen Zigarren.', '它是长者：1900 年之前，康涅狄格河谷只种植它。阴植茄衣的到来并未取代它，而是赋予它相反的角色——深色雪茄的角色。', 'هي الأقدم: قبل عام 1900 لم يزرع وادي كونيتيكت سواها. ولم يحلّ الغلاف المزروع في الظل محلّها، بل منحها دورًا مضادًا: دور السيجار الداكن.', 'Full sun, with plants set some sixty centimetres apart so the leaf reaches its full size. It is cut by the whole stalk, not leaf by leaf as the shade wrapper is.', 'Pleno sol, con las plantas separadas unos sesenta centímetros para que la hoja alcance todo su tamaño. Se corta por el tallo entero, y no hoja a hoja como la capa de sombra.', 'Volle Sonne, die Pflanzen etwa sechzig Zentimeter auseinander, damit das Blatt seine volle Größe erreicht. Geerntet wird der ganze Stängel, nicht Blatt für Blatt wie beim Schattendeckblatt.', '全日照，株距约六十厘米，好让叶片长足尺寸。采收时整株连茎砍下，而非如阴植茄衣那样逐叶采摘。', 'شمس كاملة، والنباتات متباعدة نحو ستين سنتيمترًا كي تبلغ الورقة حجمها الكامل. وتُقطع بالساق كاملة، لا ورقة ورقة كما يُفعل بالغلاف المزروع في الظل.', 'A thick, oily, heavily veined leaf of deep colour once cured. It burns slowly and carries a pronounced taste — the very opposite of its shade-grown neighbour.', 'Hoja gruesa, grasa y muy venosa, de color profundo tras el secado. Arde despacio y lleva un sabor marcado: todo lo contrario de su vecina de sombra.', 'Ein dickes, öliges, stark geädertes Blatt von tiefer Farbe nach der Trocknung. Es brennt langsam und trägt einen ausgeprägten Geschmack — das genaue Gegenteil seiner Schattennachbarin.', '叶片厚实油润、叶脉粗显，干燥后色泽深沉。燃烧缓慢，味道浓重——与它阴植的邻居恰好相反。', 'ورقة سميكة دهنية بارزة العروق، لونها عميق بعد التجفيف. تحترق ببطء وتحمل مذاقًا قويًا — نقيض جارتها المزروعة في الظل تمامًا.', '[\"Cocoa\",\"Earth\",\"Burnt sugar\"]', '[\"Cacao\",\"Tierra\",\"Azúcar quemado\"]', '[\"Kakao\",\"Erde\",\"Gebrannter Zucker\"]', '[\"可可\",\"泥土\",\"焦糖\"]', '[\"كاكاو\",\"تراب\",\"سكر محروق\"]', '[\"Bourbon\",\"Black coffee\",\"Stout\"]', '[\"Bourbon\",\"Café solo\",\"Stout\"]', '[\"Bourbon\",\"Schwarzer Kaffee\",\"Stout\"]', '[\"波本威士忌\",\"黑咖啡\",\"世涛啤酒\"]', '[\"بوربون\",\"قهوة سوداء\",\"ستاوت\"]', 'Maduro wrapper and binder', 'Capa maduro y capote', 'Maduro-Deckblatt und Umblatt', '马杜罗茄衣与茄套', 'غلاف مادورو ورابط'),
  ('usa-connecticut-shade', 'Connecticut Shade', 'usa', 'Cape', 'Vers 1900, la cape de Sumatra ruine le commerce américain. Des planteurs de la vallée du Connecticut vont en chercher la semence et la rapportent — mais sous le soleil de Nouvelle-Angleterre, les feuilles brûlent. Ils tendent alors des toiles de gaze au-dessus des champs, et la cape d\'ombre est née.', 'Cultivée serrée, sous des toiles de gaze ou de nylon qui filtrent le soleil et abritent aussi du vent. La « Tobacco Valley » remonte la vallée du Connecticut de Springfield, dans le Massachusetts, jusqu\'à Hartford.', 'Feuille mince et souple, d\'un brun doré, à la nervure très fine et au toucher soyeux. Elle donne un corps doux : c\'est la cape des assemblages qu\'on veut légers.', '[\"Douceur\",\"Cèdre\",\"Pain grillé\"]', '[\"Café au lait\",\"Thé blanc\",\"Vin blanc sec\"]', '2026-08-21 18:14:54', '2026-08-22 22:08:55', 'Around 1900, Sumatra wrapper was ruining the American trade. Growers from the Connecticut Valley went to fetch the seed and brought it home — but under the New England sun the leaves burned. So they stretched cheesecloth tents over the fields, and the shade wrapper was born.', 'Hacia 1900, la capa de Sumatra arruinaba el comercio estadounidense. Unos plantadores del valle del Connecticut fueron a buscar la semilla y la trajeron, pero bajo el sol de Nueva Inglaterra las hojas se quemaban. Tendieron entonces telas de gasa sobre los campos, y nació la capa de sombra.', 'Um 1900 ruinierte das Sumatra-Deckblatt den amerikanischen Handel. Pflanzer aus dem Connecticut-Tal holten den Samen und brachten ihn heim — doch unter der Sonne Neuenglands verbrannten die Blätter. Also spannten sie Gazetücher über die Felder, und das Schattendeckblatt war geboren.', '约在 1900 年，苏门答腊茄衣重创美国烟草贸易。康涅狄格河谷的种植者前往取种带回，但在新英格兰的烈日下叶片被灼伤。于是他们在田间张起纱布遮棚，阴植茄衣由此诞生。', 'نحو عام 1900 كان غلاف سومطرة يدمّر التجارة الأمريكية. فذهب مزارعون من وادي كونيتيكت لجلب البذور وأعادوها — لكنّ الأوراق احترقت تحت شمس نيو إنغلاند. فنصبوا أقمشة الشاش فوق الحقول، ووُلد الغلاف المزروع في الظل.', 'Grown close together under cheesecloth or nylon that filters the sun and shelters from wind as well. The \"Tobacco Valley\" runs up the Connecticut Valley from Springfield, Massachusetts, to Hartford.', 'Cultivada apretada, bajo telas de gasa o de nailon que filtran el sol y también resguardan del viento. El «Tobacco Valley» remonta el valle del Connecticut desde Springfield, en Massachusetts, hasta Hartford.', 'Dicht gepflanzt unter Gaze- oder Nylontüchern, die die Sonne filtern und zugleich vor Wind schützen. Das „Tobacco Valley\" zieht sich das Connecticut-Tal hinauf von Springfield in Massachusetts bis Hartford.', '密植于纱布或尼龙棚下，既滤去阳光，也遮挡风力。所谓「烟草谷」沿康涅狄格河谷自马萨诸塞州的斯普林菲尔德延伸至哈特福德。', 'تُزرع متقاربة تحت أقمشة الشاش أو النايلون التي ترشّح الشمس وتقي الريح أيضًا. ويمتد «وادي التبغ» صعودًا في وادي كونيتيكت من سبرينغفيلد في ماساتشوستس حتى هارتفورد.', 'A thin, supple leaf of golden brown, with very fine veins and a silky feel. It gives a mild body: this is the wrapper for blends meant to stay light.', 'Hoja fina y flexible, de un pardo dorado, con la vena muy fina y tacto sedoso. Aporta un cuerpo suave: es la capa de las ligas que se quieren ligeras.', 'Ein dünnes, geschmeidiges Blatt in Goldbraun, mit sehr feiner Äderung und seidigem Griff. Es gibt einen milden Körper: das Deckblatt für Mischungen, die leicht bleiben sollen.', '叶片薄而柔韧，呈金褐色，叶脉极细，触感如丝。赋予柔和的body：这是追求轻盈配方所用的茄衣。', 'ورقة رفيعة ليّنة بلون بنّي ذهبي، عروقها دقيقة جدًا وملمسها حريري. تمنح قوامًا لطيفًا: إنها غلاف الخلطات التي يُراد لها أن تبقى خفيفة.', '[\"Mildness\",\"Cedar\",\"Toast\"]', '[\"Suavidad\",\"Cedro\",\"Pan tostado\"]', '[\"Milde\",\"Zeder\",\"Toast\"]', '[\"柔顺\",\"雪松\",\"烤面包\"]', '[\"نعومة\",\"أرز\",\"خبز محمّص\"]', '[\"Café au lait\",\"White tea\",\"Dry white wine\"]', '[\"Café con leche\",\"Té blanco\",\"Vino blanco seco\"]', '[\"Milchkaffee\",\"Weißer Tee\",\"Trockener Weißwein\"]', '[\"欧蕾咖啡\",\"白茶\",\"干白葡萄酒\"]', '[\"قهوة بالحليب\",\"شاي أبيض\",\"نبيذ أبيض جاف\"]', 'Wrapper', 'Capa', 'Deckblatt', '茄衣', 'غلاف');
INSERT INTO `brands` (`name`, `country_id`, `founded`, `history`, `gamme`, `created_at`, `updated_at`, `scores`, `celebrities`, `pairings`, `limited_eds`, `factory`, `history_en`, `history_es`, `history_de`, `history_zh`, `history_ar`, `gamme_en`, `gamme_es`, `gamme_de`, `gamme_zh`, `gamme_ar`, `celebrities_en`, `celebrities_es`, `celebrities_de`, `celebrities_zh`, `celebrities_ar`, `pairings_en`, `pairings_es`, `pairings_de`, `pairings_zh`, `pairings_ar`) VALUES
  ('Cohiba', 'cuba', '1966 — La Havane, Cuba', 'Cohiba naquit dans le plus grand secret pour servir Fidel Castro. Eduardo Rivera, torcedor remarqué par un garde du corps de Castro pour la qualité extraordinaire de ses cigares personnels, fut convoqué à La Havane. Pendant seize ans, Cohiba ne fut jamais commercialisée — uniquement offerte comme cadeau diplomatique aux chefs d\'État du monde entier : Brandt, Mitterrand, Gaddafi reçurent tous des boîtes de ce cigare sans nom.\r\n\r\nEn 1982, face à la demande diplomatique croissante, Cuba décida d\'ouvrir Cohiba au commerce international. Le nom vient du mot Taïno — la langue des premiers habitants de Cuba — désignant le tabac. Cohiba est aujourd\'hui la marque de cigares la plus reconnue, la plus copiée et la plus convoitée du monde. Ses feuilles proviennent exclusivement de la région Vuelta Abajo, la plus prestigieuse de Cuba, et subissent une troisième fermentation supplémentaire qui n\'existe nulle part ailleurs.\r\n\r\nLa manufacture El Laguito, nichée dans un ancien hôtel particulier havanais, est le sanctuaire de la marque. Ses torcedoras — majoritairement des femmes — sont les artisanes les mieux payées de Cuba. On dit que fumer un Cohiba, c\'est inhaler six décennies d\'histoire révolutionnaire.', '[\r\n  {\"name\":\"Behike BHK\",\"color\":\"#8B0000\",\"story\":\"Lancée en 2010 pour les 44 ans de la marque, la Behike est la vitola la plus rare et la plus chère de l\'histoire cubaine. Elle utilise la rarissime feuille medio tiempo — poussant au sommet du plant tabacalero, trop petite pour être récoltée à grande échelle. Trois formats seulement, quelques milliers de boîtes par an. Score parfait par plusieurs experts. Prix unitaire : 30 à 50€.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"BHK 52\",\"BHK 54\",\"BHK 56\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":98,\"year\":2011},{\"source\":\"Cigar Journal\",\"score\":97,\"year\":2012}]},\r\n  {\"name\":\"Línea 1492\",\"color\":\"#C04000\",\"story\":\"Créée pour le 500ème anniversaire de la découverte des Amériques en 1992. Les Sublimes EL et Pirámides comptent parmi les vitolas les plus rares de la maison. Disponibles en éditions régionales dans certains pays seulement. La Línea 1492 incarne la Cohiba de luxe quotidien — full body sans excès.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado Claro\",\"vitolas\":[\"Sublimes\",\"Pirámides\",\"Robusto Extra\",\"Coronas Especiales\"]},\r\n  {\"name\":\"Siglo I–VI\",\"color\":\"#8B6914\",\"story\":\"Les Clásicos — gamme originelle de Castro. Les Siglo progressent de I à VI en longueur et intensité. Le Lancero (Siglo VI allongé) reste le test ultime de tout torcedor cubain. Difficile à rouler parfaitement, difficile à fumer parfaitement. La bague dorée et sa bande noire sont devenues le symbole universel du cigare de prestige.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"Siglo I\",\"Siglo II\",\"Siglo III\",\"Siglo IV\",\"Siglo V\",\"Siglo VI\"]},\r\n  {\"name\":\"Maduro 5\",\"color\":\"#3D1C00\",\"story\":\"Lancée en 2007, première Maduro dans l\'univers cubain — une révolution. Wrapper maduro vieilli 5 ans en fûts supplémentaires, créant une douceur paradoxale malgré la puissance. Notes de pruneaux, chocolat noir, café torréfié. Les fumeurs habitués aux cubains traditionnels furent déstabilisés par cette douceur inattendue. Aujourd\'hui culte.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Maduro x5\",\"vitolas\":[\"Genios\",\"Mágicos\",\"Secretos\",\"Divinos\"]},\r\n  {\"name\":\"Serie D\",\"color\":\"#5C1A00\",\"story\":\"La Robaina — format Robusto (50 x 124mm), format roi. Fumée en 45 minutes, la Serie D No.4 est la référence mondiale du Robusto. Densément chargée, elle libère en milieu de fumée une complexité épicée unique. Indispensable dans toute cave sérieuse.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.4\",\"No.5\",\"No.6\"]}\r\n]', '2026-03-18 09:43:40', '2026-08-14 15:26:40', '[{\"source\":\"Cigar Aficionado\",\"score\":97,\"year\":2023,\"vitola\":\"Siglo VI\"},{\"source\":\"Cigar Aficionado\",\"score\":98,\"year\":2011,\"vitola\":\"Behike BHK 56\"}]', '[{\"name\":\"Fidel Castro\",\"anecdote\":\"Castro fumait 20 à 25 Cohiba par jour avant d\'arrêter en 1985 sur conseil médical. Il aurait déclaré : \'La meilleure chose que j\'ai faite pour ma santé, c\'est d\'arrêter de fumer. La meilleure chose que j\'ai faite pour mes ennemis, c\'est de continuer à leur en offrir.\'\"},{\"name\":\"Jack Nicholson\",\"anecdote\":\"Fumeur notoire de Cohiba Esplendidos lors de ses apparitions aux Oscars, contribuant à populariser la marque aux États-Unis malgré l\'embargo.\"},{\"name\":\"Che Guevara\",\"anecdote\":\"Figure iconique du cigare cubain, souvent photographié avec un Cohiba. L\'image est devenue un symbole culturel mondial.\"}]', '[{\"type\":\"Spiritueux\",\"name\":\"Cognac Hennessy XO\",\"notes\":\"La rondeur du cognac amplifie les notes boisées du Behike. Accord classique des grandes occasions.\"},{\"type\":\"Rhum\",\"name\":\"Ron Santiago de Cuba 12 ans\",\"notes\":\"L\'accord naturel — les deux produits partagent les mêmes terres cubaines. Notes de canne et de tabac en résonance.\"},{\"type\":\"Café\",\"name\":\"Café cubain cortadito\",\"notes\":\"L\'amertume douce du café cubain soutient parfaitement la complexité épicée d\'un Siglo III après repas.\"}]', '[\"Cohiba Behike BHK 52/54/56 (2010)\",\"Cohiba 55 Aniversario (2021)\",\"Cohiba Sublimes EL (annuel)\",\"Cohiba 1966 EL\",\"Cohiba Siglo VI Gran Reserva Cosecha 2006\"]', 'El Laguito, La Havane — manufacture exclusive Cohiba', 'Cohiba was born in absolute secrecy in 1966. Eduardo Rivera, a torcedor whose exceptional private cigars had caught the eye of a presidential bodyguard, was summoned to Havana and quietly installed at El Laguito — a former aristocratic mansion in the Miramar district. For sixteen years, Cohiba was never sold. It existed as a diplomatic instrument: boxes without price tags, offered by Fidel Castro to heads of state who understood immediately they held something extraordinary. Willy Brandt received them in Bonn. François Mitterrand in Paris. Muammar Gaddafi in Tripoli. Nelson Mandela in Johannesburg. All received boxes of this nameless cigar.\r\n\r\nIn 1982, facing mounting international curiosity and a growing black market, Cuba opened Cohiba to commercial distribution — but only outside the island, and only through Cubatabaco\'s most exclusive channels. The name comes from the Taíno language, spoken by Cuba\'s original inhabitants before Columbus: it simply means tobacco. The irony is perfect — the world\'s most prestigious cigar bears the most ancient and universal name for what it is.\r\n\r\nWhat makes Cohiba technically distinct is the third fermentation. After the standard two fermentations undergone by all Cuban tobacco, Cohiba\'s leaves undergo a third extended fermentation in cedar barrels. This process, closely guarded and unique in the industry, extracts a final layer of harshness and develops the complex, almost creamy equilibrium that defines the brand\'s profile. The leaves come exclusively from Vuelta Abajo, Cuba\'s most prestigious growing region, and are selected personally by the factory\'s master blenders.\r\n\r\nEl Laguito is Cohiba\'s world. Its workforce is predominantly female — the torcedoras who roll Cohiba are Cuba\'s highest-paid cigar artisans. The factory does not receive visitors. Its rhythms are its own. Each cigar leaving El Laguito passes through more quality control checkpoints than any other Cuban brand. Rejected cigars — roughly one in five — are destroyed, never redistributed.\r\n\r\nThe Cohiba band, with its distinctive black and yellow design, has become a universal symbol of status extending far beyond the tobacco world. It appears in film, literature, and political photography as shorthand for power. It is also the world\'s most counterfeited cigar band — a distinction that measures the brand\'s reach better than any sales figure.\r\n\r\nToday, Cohiba stands as the undisputed apex of Cuban tobacco. The Behike BHK line, launched in 2010 for the brand\'s 44th anniversary, pushed the concept further still: using the ultra-rare medio tiempo leaf — found only at the very crown of the tobacco plant, in quantities too small to harvest at scale — it produced what many experts consider the most complex cigar ever commercially released. Fewer than three thousand boxes exist per year. The waiting lists are longer than the cigar itself.', 'Cohiba nació en el mayor secreto para servir a Fidel Castro. Eduardo Rivera, torcedor cuyos cigarros personales habían llamado la atención de un guardaespaldas de Castro, fue convocado a La Habana. Durante dieciséis años, Cohiba nunca se comercializó — solo se ofrecía como regalo diplomático a jefes de Estado. Brandt, Mitterrand y Gaddafi recibieron cajas de este cigarro sin nombre.\r\n\r\nEn 1982, ante la creciente demanda diplomática, Cuba abrió Cohiba al comercio internacional. El nombre proviene del vocablo taíno — lengua de los primeros habitantes de Cuba — que significa tabaco. Cohiba es hoy la marca de cigarros más reconocida, más falsificada y más codiciada del mundo.\r\n\r\nLa fábrica El Laguito, ubicada en una antigua mansión habanera, es el santuario de la marca. Sus torcedoras — en su mayoría mujeres — son las artesanas del cigarro mejor pagadas de Cuba. Fumar un Cohiba es inhalar seis décadas de historia revolucionaria.', 'Cohiba wurde im strengsten Geheimnis geboren, um Fidel Castro zu dienen. Eduardo Rivera, ein Torcedor, dessen außergewöhnliche persönliche Zigarren einem Leibwächter Castros aufgefallen waren, wurde nach Havanna beordert. Sechzehn Jahre lang wurde Cohiba nie kommerziell verkauft — ausschließlich als diplomatisches Geschenk an Staatsoberhäupter überreicht. Brandt, Mitterrand und Gaddafi erhielten alle Kisten dieser namenlosen Zigarre.\r\n\r\n1982 öffnete Kuba Cohiba dem internationalen Handel. Der Name stammt aus der Taíno-Sprache — der Sprache der Ureinwohner Kubas — und bedeutet Tabak. Cohiba ist heute die weltweit bekannteste, meistgefälschte und begehrteste Zigarrenmarke.\r\n\r\nDie El Laguito Fabrik, eingebettet in eine ehemalige Havannaer Villa, ist das Heiligtum der Marke. Ihre Torcedoras — überwiegend Frauen — sind Kubas bestbezahlte Zigarrenhandwerkerinnen. Eine Cohiba zu rauchen bedeutet, sechs Jahrzehnte Revolutionsgeschichte zu inhalieren.', '科伊巴诞生于最高度保密之中，专为菲德尔·卡斯特罗服务。爱德华多·里维拉是一位雪茄卷制师，他精湛的个人雪茄引起了卡斯特罗警卫的注意，被召至哈瓦那。十六年间，科伊巴从未商业销售——仅作为外交礼物赠予各国元首。勃兰特、密特朗和卡扎菲都曾收到这种无名雪茄的礼盒。\r\n\r\n1982年，面对日益增长的外交需求，古巴决定向国际市场开放科伊巴。品牌名称来自泰诺语——古巴原住民的语言——意为烟草。科伊巴如今是全球最知名、最被仿冒、最令人垂涎的雪茄品牌。\r\n\r\n坐落在哈瓦那旧宅中的拉古尼托工厂是品牌的圣地。女卷制师们——主要为女性——是古巴薪酬最高的雪茄工匠。吸一支科伊巴，就是在吸入六十年的革命历史。', 'وُلدت كوهيبا في سرية تامة لخدمة فيدل كاسترو. إدواردو ريفيرا، ملفِّف السيجار الذي لفت سجائره الشخصية الاستثنائية انتباه أحد حراس كاسترو، استُدعي إلى هافانا. لستة عشر عامًا، لم تُطرح كوهيبا للبيع التجاري قط — بل كانت تُقدَّم هدية دبلوماسية لرؤساء الدول. برانت وميتران والقذافي جميعهم استلموا علبًا من هذا السيجار المجهول الهوية.\r\n\r\nعام 1982، وأمام الطلب الدبلوماسي المتزايد، فتحت كوبا كوهيبا أمام التجارة الدولية. يأتي الاسم من كلمة تاينو — لغة سكان كوبا الأصليين — وتعني التبغ. تُعدّ كوهيبا اليوم العلامة التجارية الأكثر شهرةً وتقليدًا وتوقًا في عالم السيجار.\r\n\r\nمصنع إل لاغونيتو، الكامن في قصر هافاني سابق، هو حرم العلامة. ملفِّفاتها — معظمهن نساء — هن أعلى حِرفيات السيجار أجرًا في كوبا. إشعال كوهيبا يعني استنشاق ستة عقود من التاريخ الثوري.', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"Launched in 2010 for the brand\'s 44th anniversary, the Behike is the rarest and most expensive vitola in Cuban history. It uses the ultra-rare medio tiempo leaf — growing at the very top of the tobacco plant, too small to harvest at scale. Three formats only, a few thousand boxes per year. Perfect scores from multiple experts. Unit price: €30–50.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"Created for the 500th anniversary of the Americas\' discovery in 1992. The Sublimes EL and Pirámides are among the house\'s rarest vitolas, available as regional editions in select countries only. The Línea 1492 embodies everyday luxury Cohiba — full body without excess.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"The Clásicos — Castro\'s original range. Siglos progress from I to VI in length and intensity. The Lancero (elongated Siglo VI) remains the ultimate test for any Cuban torcedor. The gold band with its black stripe has become the universal symbol of prestige.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"Launched in 2007, the first Maduro in the Cuban universe. The wrapper is aged 5 additional years in barrels, creating paradoxical sweetness despite the power. Notes of prunes, dark chocolate, roasted coffee. Traditional Cuban smokers were unsettled by this unexpected softness. Now iconic.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"The Robaina — Robusto format (50 x 124mm), king of formats. The Serie D No.4 is the world\'s reference Robusto. Densely packed, it releases a unique spiced complexity mid-smoke. Essential in any serious humidor.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"Lanzada en 2010 para el 44º aniversario de la marca, la Behike es la vitola más rara y costosa de la historia cubana. Utiliza la rarísima hoja medio tiempo — que crece en la cima de la planta de tabaco, demasiado pequeña para cosechar a escala. Solo tres formatos, unos pocos miles de cajas al año. Puntuaciones perfectas de múltiples expertos. Precio unitario: 30-50€.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"Creada para el 500º aniversario del descubrimiento de América en 1992. Los Sublimes EL y Pirámides están entre las vitolas más raras de la casa, disponibles solo como ediciones regionales en países seleccionados. La Línea 1492 encarna el lujo cotidiano de Cohiba — cuerpo completo sin exceso.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"Los Clásicos — la gama original de Castro. Los Siglos progresan del I al VI en longitud e intensidad. El Lancero (Siglo VI alargado) sigue siendo la prueba definitiva de todo torcedor cubano. La banda dorada con su franja negra se ha convertido en el símbolo universal del prestigio.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"Lanzada en 2007, la primera Maduro en el universo cubano — una revolución. La envolvente Maduro se añeja 5 años adicionales en barricas, creando una dulzura paradójica a pesar del poder. Notas de ciruela, chocolate negro, café tostado. Actualmente icónica.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"El Robaina — formato Robusto (50 x 124mm), rey de los formatos. Bien apretada, libera a mitad de fumada una inesperada complejidad especiada. Imprescindible en cualquier humidor serio.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"Zum 44. Jubiläum 2010 lanciert, ist die Behike die seltenste und teuerste Vitola der kubanischen Geschichte. Sie verwendet das ultrararere Medio-Tiempo-Blatt — das an der Spitze der Tabakpflanze wächst, zu klein für die Ernte. Nur drei Formate, einige tausend Kisten pro Jahr. Perfekte Bewertungen von mehreren Experten. Stückpreis: 30-50€.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"Zum 500. Jahrestag der Entdeckung Amerikas 1992 geschaffen. Die Sublimes EL und Pirámides gehören zu den seltensten Vitolas des Hauses, nur als Regionaleditionen in ausgewählten Ländern erhältlich.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"Die Clásicos — Castros ursprüngliches Sortiment. Die Siglos steigern sich von I bis VI in Länge und Intensität. Der Lancero bleibt die ultimative Prüfung für jeden kubanischen Torcedor. Das goldene Band ist zum universellen Symbol des Prestiges geworden.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"2007 lanciert, die erste Maduro im kubanischen Universum. Der Wrapper reift 5 Jahre zusätzlich in Fässern und schafft eine paradoxe Süße trotz der Stärke. Noten von Pflaume, dunkler Schokolade, geröstetem Kaffee. Heute ikonisch.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"Das Robaina — Robusto-Format (50 x 124mm), König der Formate. Dicht gerollt, entfaltet es zur Mitte des Rauchens eine unerwartete Würzkomplexität. Unverzichtbar in jedem seriösen Humidor.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"2010年为品牌44周年推出，Behike是古巴历史上最稀有、最昂贵的雪茄规格。使用极为罕见的中段叶（medio tiempo）——生长在烟草植株的顶端，数量太少无法大规模采收。仅三种规格，每年仅数千盒。多位专家给予满分评价。单价：30-50欧元。\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"为纪念1992年美洲发现500周年而创。Sublimes EL和Pirámides是该品牌最稀有的规格之一，仅在特定国家作为地区版供应。Línea 1492体现了科伊巴的日常奢华——饱满而不过度。\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"经典系列——卡斯特罗的原始产品线。Siglos从I到VI递增，长度与强度逐步提升。Lancero（加长版Siglo VI）是每位古巴卷制师的终极考验。金色带饰已成为威望的普世象征。\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"2007年推出，古巴雪茄界首款Maduro——一场革命。茄衣在桶中额外陈化5年，创造出矛盾的甜美感，尽管劲道十足。李子、黑巧克力、烘焙咖啡的风味。如今已成经典。\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"罗巴伊纳——Robusto规格（50×124mm），规格之王。密实填充，在中段释放出意想不到的辛香复杂性。任何认真的雪茄收藏都不可或缺。\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Behike BHK\", \"color\": \"#8B0000\", \"story\": \"أُطلقت عام 2010 للاحتفال بالذكرى الرابعة والأربعين للعلامة، تُعدّ Behike أندر وأغلى سيجار في التاريخ الكوبي. تستخدم ورقة الميديو تيمبو النادرة للغاية — التي تنمو في قمة نبتة التبغ، صغيرة جدًا لا تُحصد على نطاق واسع. ثلاثة مقاسات فحسب، بضعة آلاف علبة سنويًا. تقييمات مثالية من خبراء متعددين. سعر الوحدة: 30-50 يورو.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"BHK 52\", \"BHK 54\", \"BHK 56\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 98, \"year\": 2011}]}, {\"name\": \"Línea 1492\", \"color\": \"#C04000\", \"story\": \"ابتُكرت بمناسبة الذكرى الخمسمئة لاكتشاف الأمريكتين عام 1992. السوبليمس EL والبيراميدس من أندر مقاسات الدار، متوفرة فقط كإصدارات إقليمية في دول محددة.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado Claro\", \"vitolas\": [\"Sublimes\", \"Pirámides\", \"Robusto Extra\", \"Coronas Especiales\"]}, {\"name\": \"Siglo I–VI\", \"color\": \"#8B6914\", \"story\": \"الكلاسيكيات — التشكيلة الأصلية لكاسترو. تتصاعد السيغلو من الأول إلى السادس طولًا وكثافةً. يظل اللانسيرو الاختبار الأقصى لكل ملفِّف كوبي. الشريط الذهبي مع خطه الأسود أصبح الرمز العالمي للمكانة.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Siglo I\", \"Siglo II\", \"Siglo III\", \"Siglo IV\", \"Siglo V\", \"Siglo VI\"]}, {\"name\": \"Maduro 5\", \"color\": \"#3D1C00\", \"story\": \"أُطلقت عام 2007، أول مادورو في الكون الكوبي — ثورة حقيقية. تُعتَّق الغلافة خمس سنوات إضافية في البراميل، مُنتِجةً حلاوة متناقضة رغم القوة. نكهات البرقوق والشوكولاتة الداكنة والقهوة المحمَّصة. باتت أيقونية اليوم.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Maduro x5\", \"vitolas\": [\"Genios\", \"Mágicos\", \"Secretos\", \"Divinos\"]}, {\"name\": \"Serie D\", \"color\": \"#5C1A00\", \"story\": \"الروباينا — مقاس روبوستو (50 × 124 ملم)، ملك المقاسات. مضغوطة بإحكام، تُطلق في منتصف التدخين تعقيدًا توابليًا غير متوقع. لا غنى عنها في أي مجموعة جادة.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.4\", \"No.5\", \"No.6\"]}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro smoked 20–25 Cohiba cigars a day before quitting in 1985 on medical advice. He reportedly said: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro fumaba 20–25 Cohiba cigarros al día antes de dejarlo en 1985 por consejo médico. Supuestamente dijo: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro rauchte 20–25 Cohiba Zigarren täglich bevor er 1985 auf ärztlichen Rat aufhörte. Er soll gesagt haben: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro 每天抽20至25支科伊巴雪茄 在1985年遵医嘱戒烟之前. 据报道他曾说： \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"name\": \"Fidel Castro\", \"anecdote\": \"Castro كان يدخن من 20 إلى 25 سيجارة كوهيبا يوميًا قبل إقلاعه عام 1985 بنصيحة طبية. يُروى أنه قال: \'The best thing I did for my health was quit smoking. The best thing I did for my enemies was keep offering it to them.\'\"}, {\"name\": \"Jack Nicholson\", \"anecdote\": \"A notorious Cohiba Esplendidos smoker at his Oscar appearances, Nicholson helped popularize the brand in the United States despite the embargo.\"}, {\"name\": \"Che Guevara\", \"anecdote\": \"An iconic figure of the Cuban cigar, often photographed with a Cohiba. The image has become a global cultural symbol.\"}]', '[{\"type\": \"Spirits\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"The roundness of cognac amplifies the woody notes of the Behike. A classic pairing for great occasions.\"}, {\"type\": \"Rum\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"The natural pairing — both products share the same Cuban soil. Notes of cane and tobacco in resonance.\"}, {\"type\": \"Coffee\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"Licores\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"La redondez del coñac amplifica las notas maderosas of the Behike. Un maridaje clásico para grandes ocasiones.\"}, {\"type\": \"Ron\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"El maridaje natural — ambos productos comparten el mismo Cuban soil. Notas de cane and tobacco in resonance.\"}, {\"type\": \"Café\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"Spirituosen\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"Die Fülle des Cognacs verstärkt die Holznoten of the Behike. Eine klassische Paarung für besondere Anlässe.\"}, {\"type\": \"Rum\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"Die natürliche Paarung — beide Produkte teilen denselben Cuban soil. Noten von cane and tobacco in resonance.\"}, {\"type\": \"Kaffee\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"烈酒\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"干邑的圆润感放大了木质气息 of the Behike. 盛大场合的经典搭配.\"}, {\"type\": \"朗姆酒\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"天然的搭配 — 两种产品共享相同的 Cuban soil. 风味： cane and tobacco in resonance.\"}, {\"type\": \"咖啡\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]', '[{\"type\": \"المسكرات\", \"name\": \"Hennessy XO Cognac\", \"notes\": \"نعومة الكونياك تُضخِّم النكهات الخشبية of the Behike. مقارنة كلاسيكية للمناسبات الكبرى.\"}, {\"type\": \"الروم\", \"name\": \"Ron Santiago de Cuba 12 years\", \"notes\": \"المقارنة الطبيعية — كلا المنتجين يشتركان في نفس Cuban soil. نكهات: cane and tobacco in resonance.\"}, {\"type\": \"القهوة\", \"name\": \"Cuban cortadito\", \"notes\": \"The gentle bitterness of Cuban coffee perfectly supports the spiced complexity of a Siglo III after dinner.\"}]'),
  ('Montecristo', 'cuba', '1935 — La Havane, Cuba', 'Montecristo est née dans la légendaire manufacture H. Upmann en 1935, fondée par Alonso Menéndez et Pepe García. Le nom fut choisi par les torcedors eux-mêmes : dans les galeras de l\'époque, un lector lisait à voix haute pendant les heures de roulage — et le roman préféré de tous était Le Comte de Monte-Cristo d\'Alexandre Dumas. Le numéro 4, format Petit Corona (42 x 129mm), est aujourd\'hui le cigare le plus vendu du monde.\r\n\r\nAprès la révolution cubaine de 1959, Menéndez quitta Cuba avec ses semences et ses maîtres torcedores pour créer Montecristo en République Dominicaine — donnant naissance à deux dynasties parallèles portant le même nom glorieux. Les deux maisons se disputent depuis lors l\'héritage d\'un nom devenu mythe.\r\n\r\nLe Montecristo No.2 — formato Torpédo pyramidal — est considéré par les connaisseurs comme le cigare le plus parfaitement équilibré jamais roulé. Sa forme effilée concentre les arômes en une crescendo qui culmine en milieu de fumée avant de s\'ouvrir en une finale cèdre et épices noires d\'une longueur extraordinaire.', '[\r\n  {\"name\":\"No.2 — Le Torpedo\",\"color\":\"#8B4513\",\"story\":\"Format Torpedo (52 x 162mm), considéré par Robert Parker et de nombreux experts comme le cigare le plus parfaitement équilibré de Cuba. La forme pyramidale concentre les arômes en une montée progressive. Notes dominantes de cèdre, noisette grillée, épices douces. Durée : 90 minutes. Score Cigar Aficionado 96/100.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.2\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022}]},\r\n  {\"name\":\"No.4 — Le Classique\",\"color\":\"#A0522D\",\"story\":\"Petit Corona (42 x 129mm), cigare le plus vendu du monde. Accessible, équilibré, parfait pour l\'amateur comme pour l\'expert. C\'est le Montecristo par excellence — celui que l\'on offre, que l\'on partage, que l\'on retrouve dans toutes les caves du monde. Notes de pain grillé, noix de cajou, poivre blanc.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"No.4\"]},\r\n  {\"name\":\"Línea 1935\",\"color\":\"#722F37\",\"story\":\"Créée pour le 80ème anniversaire en 2015. Hommage direct aux origines — utilise des feuilles de Vuelta Abajo sélectionnées selon les critères de 1935. Blend plus épicé, plus corsé que la gamme classique. Édition permanente, production limitée.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Maduro\",\"vitolas\":[\"Dumas\",\"Edmundo\",\"Maltes\"]},\r\n  {\"name\":\"Supremos EL\",\"color\":\"#4A235A\",\"story\":\"Édition régionale Espagne, format géant Supremos (54 x 185mm). L\'un des cigares les plus recherchés par les collectionneurs européens. Production annuelle inférieure à 5000 boîtes. Le temps de fumée dépasse les deux heures.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"Supremos\"]}\r\n]', '2026-03-18 09:43:40', '2026-08-14 15:26:40', '[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022,\"vitola\":\"No.2\"},{\"source\":\"Cigar Journal\",\"score\":95,\"year\":2021,\"vitola\":\"No.4\"}]', '[{\"name\":\"Alexandre Dumas\",\"anecdote\":\"L\'auteur du Comte de Monte-Cristo n\'a jamais fumé ces cigares — il mourut en 1870 — mais son roman inspira directement le nom de la marque. Les torcedors de La Havane qui lisaient son œuvre pendant le roulage perpétuent involontairement sa mémoire.\"},{\"name\":\"JFK Kennedy\",\"anecdote\":\"La veille de signer l\'embargo cubain en 1962, Kennedy envoya son attaché de presse acheter 1200 H. Upmann Petite Upmann — les cigares préférés de Pierre Salinger. Il signa l\'embargo le lendemain avec ses cigares en sécurité.\"}]', '[{\"type\":\"Vin\",\"name\":\"Rioja Gran Reserva\",\"notes\":\"Le tanin du Rioja vieilli épouse la complexité du No.2 en une symphonie ibéro-cubaine. Accord classique des caves madrilènes.\"},{\"type\":\"Whisky\",\"name\":\"Glenfarclas 25 ans\",\"notes\":\"Les notes de xérès et de fruits secs du Glenfarclas trouvent un écho parfait dans le No.4. Accord consensuel des grandes occasions.\"},{\"type\":\"Café\",\"name\":\"Espresso ristretto\",\"notes\":\"L\'intensité réduite d\'un ristretto souligne la longueur épicée du No.2. Ne jamais noyer un Montecristo dans un café allongé.\"}]', '[\"Montecristo 80 Aniversario EL (2015)\",\"Montecristo Supremos EL (annuel, Espagne)\",\"Montecristo Gran Edmundo\",\"Montecristo Línea 1935 Maltes\"]', 'H. Upmann / Romeo y Julieta, La Havane', 'Montecristo was born inside the legendary H. Upmann factory in 1935, created by Alonso Menéndez and Pepe García from the finest tobaccos of Vuelta Abajo. The name was chosen by the torcedors themselves: during rolling sessions, a reader — the lector — would read aloud to the workers, and by consensus the favorite novel was Alexandre Dumas\' The Count of Monte Cristo. The choice revealed something about who made these cigars and what they aspired to: an epic of justice, wealth, and resurrection. The name stuck, the band was designed, and one of tobacco history\'s great dynasties began.\r\n\r\nThe early Montecristo garnered immediate attention in Britain, where the Dunhill and Hunters & Frankau networks distributed it to London\'s finest clubs. By the late 1940s, the No.4 — a Petit Corona measuring 42 x 129mm — had become the benchmark for what a daily cigar should be: not too powerful, not too delicate, impeccably constructed, and consistent across every single box. It is today the world\'s best-selling cigar, a distinction it has held for decades.\r\n\r\nThe Cuban revolution of 1959 fractured the brand into two permanent dynasties. Alonso Menéndez departed with his seeds, his master torcedores, and his institutional knowledge. He eventually settled in the Dominican Republic, where a Montecristo was created under conditions as close to the original as he could engineer. Two houses, one name, different terroir — and decades of legal disputes over the American market where the Cuban brand could not be sold due to the trade embargo.\r\n\r\nIn Havana, Montecristo continued under state ownership at the Romeo y Julieta factory. The quality recovered, the prestige deepened. The No.2, in Torpedo pyramidal format, emerged as the brand\'s intellectual masterpiece: the tapered head concentrates heat and directs aromas through the palate in a crescendo that peaks at mid-smoke before unfolding into cedar, black spice, and an impossibly long finish. Cigar Aficionado awarded it 96 points in 2022 — the highest score ever given to a regular production Cuban cigar in that publication\'s history.\r\n\r\nThe Montecristo Edmundo, launched in 2004, added a rounder, more immediate profile to the collection. The Open series brought the brand to younger smokers who found the classics slightly demanding. The Línea 1492, created for the 500th anniversary of Columbus\'s voyage in 1992, produced the Sublimes — a Double Corona of haunting complexity that connoisseurs compare to great Burgundy in the way it evolves differently in every box.\r\n\r\nWhat unites all Montecristos across formats and decades is a shared architectural philosophy: balance above all else. These are not cigars that announce themselves with power. They seduce through precision. They reward patience. And they have never stopped being the reference against which every other premium cigar is measured.', 'Montecristo nació en la legendaria fábrica H. Upmann en 1935. El nombre fue elegido por los propios torcedores: el lector en las galeras leía El Conde de Montecristo de Dumas — favorito de todos. El No.4 Petit Corona (42x129mm) es hoy el cigarro más vendido del mundo.\r\n\r\nTras la revolución de 1959, Menéndez fundó Montecristo en República Dominicana — dos dinastías paralelas con el mismo nombre glorioso.\r\n\r\nEl No.2 torpedo piramidal es considerado el cigarro cubano más perfectamente equilibrado jamás lanzado.', 'Montecristo wurde 1935 in der legendären H. Upmann Fabrik geboren. Den Namen wählten die Torcedors selbst: der Vorleser in den Galeras las Dumas\' Der Graf von Monte Christo — aller Lieblingsroman. Die No.4 Petit Corona (42x129mm) ist die meistverkaufte Zigarre der Welt.\r\n\r\nNach der Revolution 1959 gründete Menéndez Montecristo in der Dominikanischen Republik — zwei Dynastien mit demselben Namen.\r\n\r\nDie No.2 Torpedo gilt als die ausgewogenste kubanische Zigarre aller Zeiten.', '蒙特克里斯托于1935年在H·厄普曼工厂诞生。卷制师们以大仲马的《基督山伯爵》命名——那是工场朗读时人人最爱的小说。No.4小皇冠（42×129mm）是全球销量最高的雪茄。\r\n\r\n1959年革命后，梅嫩德斯在多米尼加共和国创立了蒙特克里斯托——两个平行王朝共用同一荣耀名称。\r\n\r\nNo.2锥形托尔佩多被行家视为有史以来最完美平衡的古巴雪茄。', 'وُلدت مونتيكريستو عام 1935 في مصنع H. Upmann الأسطوري. اختار الاسم الملفِّفون أنفسهم: كان القارئ في قاعات اللف يجهر برواية دوما الكونت دي مونتي كريستو — المفضلة لدى الجميع. No.4 بيتي كورونا (42×129ملم) هو أكثر السيجار مبيعًا في العالم.\r\n\r\nبعد ثورة 1959، أسّس مينينديث مونتيكريستو في جمهورية الدومينيكان — سلالتان متوازيتان بالاسم ذاته.\r\n\r\nالـ No.2 التوربيدو يُعدّ في نظر المتذوقين أكثر السيجار الكوبي توازنًا على الإطلاق.', '[{\"name\": \"No.2 — The Torpedo\", \"color\": \"#8B4513\", \"story\": \"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. Dominant notes of cedar, toasted hazelnut, soft spices. Duration: 90 minutes. Cigar Aficionado score 96/100.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Colorado\", \"vitolas\": [\"No.2\"], \"scores\": [{\"source\": \"Cigar Aficionado\", \"score\": 96, \"year\": 2022}]}, {\"name\": \"No.4 — The Classic\", \"color\": \"#A0522D\", \"story\": \"Petit Corona (42 x 129mm), the world\'s best-selling cigar. Accessible, balanced, perfect for both novice and expert. Notes of toast, cashew, white pepper.\", \"force\": \"Medium\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"No.4\"]}, {\"name\": \"Línea 1935\", \"color\": \"#722F37\", \"story\": \"Created for the 80th anniversary in 2015. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Maduro\", \"vitolas\": [\"Dumas\", \"Edmundo\", \"Maltes\"]}, {\"name\": \"Supremos EL\", \"color\": \"#4A235A\", \"story\": \"Spanish regional edition, Supremos format (54 x 185mm). One of the most sought-after cigars among European collectors. Annual production under 5,000 boxes. Smoking time exceeds two hours.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"Supremos\"]}]', '[{\"name\":\"No.2 — El Torpedo\",\"color\":\"#8B4513\",\"story\":\"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. Notas dominantes de cedro, tostado avellana, soft especias. Duración: 90 minutos. Puntuación Cigar Aficionado 96/100.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.2\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022}]},{\"name\":\"No.4 — El Clásico\",\"color\":\"#A0522D\",\"story\":\"Petit Corona (42 x 129mm), el cigarro más vendido del mundo. Accesible, equilibrado, perfecto tanto para principiantes como para expertos. Notas de toast, cashew, white pimienta.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"No.4\"]},{\"name\":\"Línea 1935\",\"color\":\"#722F37\",\"story\":\"Creada para el 80º aniversario en 2015. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Maduro\",\"vitolas\":[\"Dumas\",\"Edmundo\",\"Maltes\"]},{\"name\":\"Supremos EL\",\"color\":\"#4A235A\",\"story\":\"Spanish regional edition, Supremos format (54 x 185mm). One of el más codiciado cigars among European coleccionistas. Producción anual inferior a 5.000 cajas. El tiempo de fumada supera las dos horas.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"Supremos\"]}]', '[{\"name\":\"No.2 — Der Torpedo\",\"color\":\"#8B4513\",\"story\":\"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. Dominante Noten von Zeder, geröstet Haselnuss, soft Gewürze. Dauer: 90 Minuten. Cigar Aficionado Score 96/100.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.2\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022}]},{\"name\":\"No.4 — Der Klassiker\",\"color\":\"#A0522D\",\"story\":\"Petit Corona (42 x 129mm), die meistverkaufte Zigarre der Welt. Zugänglich, ausgewogen, perfekt für Anfänger und Experten gleichermaßen. Noten von toast, cashew, white Pfeffer.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"No.4\"]},{\"name\":\"Línea 1935\",\"color\":\"#722F37\",\"story\":\"Zum 80. Jubiläum 2015 lanciert. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Maduro\",\"vitolas\":[\"Dumas\",\"Edmundo\",\"Maltes\"]},{\"name\":\"Supremos EL\",\"color\":\"#4A235A\",\"story\":\"Spanish regional edition, Supremos format (54 x 185mm). One of die begehrteste cigars among European collectors. Jahresproduktion unter 5.000 Kisten. Rauchdauer überschreitet zwei Stunden.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"Supremos\"]}]', '[{\"name\":\"No.2 — 鱼雷\",\"color\":\"#8B4513\",\"story\":\"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. 主导风味： 雪松木, 烘烤 榛子, soft 香料. 吸食时长：90分钟. 雪茄爱好者杂志评分 96/100.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.2\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022}]},{\"name\":\"No.4 — 经典款\",\"color\":\"#A0522D\",\"story\":\"Petit Corona (42 x 129mm), 全球销量最高的雪茄. 易入门，平衡，完美 适合新手和专家. 风味： toast, cashew, white 胡椒.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"No.4\"]},{\"name\":\"Línea 1935\",\"color\":\"#722F37\",\"story\":\"2015年为80周年推出. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Maduro\",\"vitolas\":[\"Dumas\",\"Edmundo\",\"Maltes\"]},{\"name\":\"Supremos EL\",\"color\":\"#4A235A\",\"story\":\"Spanish regional edition, Supremos format (54 x 185mm). One of 最受追捧的 cigars among European 收藏家. 年产量不足5000盒. 吸食时间超过两小时.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"Supremos\"]}]', '[{\"name\":\"No.2 — التوربيدو\",\"color\":\"#8B4513\",\"story\":\"Torpedo format (52 x 162mm) — the most perfectly balanced Cuban cigar according to many experts. The pyramidal shape creates a progressive aroma build. النكهات المهيمنة:  أرز, محمَّص بندق, soft توابل. مدة التدخين: 90 دقيقة. تقييم Cigar Aficionado 96/100.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Colorado\",\"vitolas\":[\"No.2\"],\"scores\":[{\"source\":\"Cigar Aficionado\",\"score\":96,\"year\":2022}]},{\"name\":\"No.4 — الكلاسيكي\",\"color\":\"#A0522D\",\"story\":\"Petit Corona (42 x 129mm), أكثر السيجار مبيعًا في العالم. سهل الوصول، متوازن، مثالي للمبتدئ والخبير على حدٍّ سواء. نكهات:  toast, cashew, white فلفل.\",\"force\":\"Medium\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"No.4\"]},{\"name\":\"Línea 1935\",\"color\":\"#722F37\",\"story\":\"أُبدعت للذكرى الثمانين عام 2015. A tribute to the origins — using Vuelta Abajo leaves selected per 1935 criteria. Spicier and fuller-bodied than the classic range. Permanent edition, limited production.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Maduro\",\"vitolas\":[\"Dumas\",\"Edmundo\",\"Maltes\"]},{\"name\":\"Supremos EL\",\"color\":\"#4A235A\",\"story\":\"Spanish regional edition, Supremos format (54 x 185mm). One of الأكثر طلبًا cigars among European الجامعون. الإنتاج السنوي أقل من 5000 علبة. تتجاوز مدة التدخين ساعتين.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"Supremos\"]}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never smoked these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never fumaba these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never rauchte these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never smoked these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"name\": \"Alexandre Dumas\", \"anecdote\": \"The author of The Count of Monte Cristo never smoked these cigars — he died in 1870 — but his novel directly inspired the brand name. The Havana torcedors who read his work during rolling sessions inadvertently perpetuate his memory.\"}, {\"name\": \"JFK Kennedy\", \"anecdote\": \"The night before signing the Cuban embargo in 1962, Kennedy sent his press secretary to buy 1,200 H. Upmann cigars. He signed the embargo the next day with his supply secure.\"}]', '[{\"type\": \"Wine\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"Whisky\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"Coffee\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"Vino\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"Whisky\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"Café\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"Wein\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"Whisky\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"Kaffee\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"葡萄酒\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"威士忌\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"咖啡\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]', '[{\"type\": \"النبيذ\", \"name\": \"Rioja Gran Reserva\", \"notes\": \"The tannin of aged Rioja embraces the complexity of the No.2 in an Ibero-Cuban symphony.\"}, {\"type\": \"الويسكي\", \"name\": \"Glenfarclas 25 years\", \"notes\": \"The sherry and dried fruit notes find a perfect echo in the No.4. A pairing for great occasions.\"}, {\"type\": \"القهوة\", \"name\": \"Ristretto espresso\", \"notes\": \"The intensity of a ristretto highlights the spiced length of the No.2.\"}]'),
  ('Partagás', 'cuba', '1845 — La Havane, Cuba', 'Don Jaime Partagás fonda sa manufacture en 1845 dans le Barrio de los Sitios de La Havane — et elle n\'a jamais quitté l\'adresse originale, Calle Industria 520. Pendant 175 ans, l\'édifice néoclassique a résisté aux révolutions, aux ouragans et aux embargos. C\'est la plus ancienne manufacture de cigares encore en activité au monde.\r\n\r\nPartagás fut le premier à payer ses ouvriers pour qu\'un lecteur leur fasse la lecture à voix haute — Don Jaime pensait que des esprits cultivés produisaient de meilleurs cigares. Cette pratique, la lectura, se répandit ensuite dans toutes les manufactures cubaines et dans les communautés de torcedores en exil à Tampa et Miami.\r\n\r\nLa marque est connue pour ses cigares corsés, expressifs, terreux — l\'opposé de la sophistication froide de Cohiba. Les amateurs de Partagás sont fidèles jusqu\'à l\'extrême : on ne passe pas de Partagás à une autre marque, on en revient toujours. La Série D No.4, la Lusitanias et la 8-9-8 Varnished sont les trois trésors de la maison.', '[\r\n  {\"name\":\"Série D\",\"color\":\"#8B2500\",\"story\":\"La Série D No.4 — Robusto 50 x 124mm — est le cigare full-body de référence absolue. Terreux, puissant, complexe. Notes de cacao amer, poivre noir, sous-bois humide. Fumée en 45 minutes, elle ne pardonne pas une conservation négligée. Score Cigar Aficionado 93. Le No.4 est souvent le premier cigare vraiment corsé que découvre un amateur confirmé — et il ne s\'en remet pas.\",\"force\":\"Full\",\"wrapper\":\"Habano Colorado Oscuro\",\"vitolas\":[\"No.4\",\"No.5\"]},\r\n  {\"name\":\"Lusitanias\",\"color\":\"#722F37\",\"story\":\"Format Double Corona (49 x 194mm), 90 minutes de fumée. L\'un des rares formats géants encore produits régulièrement à Cuba. Nommée en hommage au paquebot coulé en 1915. La Lusitanias est le cigare des grandes occasions solennelles — elle n\'admet ni précipitation ni distraction. Éditions limitées Lusitanias Gran Reserva disponibles chez des revendeurs sélectifs.\",\"force\":\"Full\",\"wrapper\":\"Habano Oscuro\",\"vitolas\":[\"Lusitanias\"]},\r\n  {\"name\":\"8-9-8 Collection\",\"color\":\"#5C4033\",\"story\":\"Commercialisée en boîtes de 25 cigares rangés 8-9-8 — d\'où le nom. Format Panetela (33 x 170mm), le plus fin jamais produit à Cuba. Légèreté apparente trompeuse : la finesse du calibre concentre les arômes en une intensité inattendue. Format adulé des amateurs parisiens.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"8-9-8 Varnished\"]},\r\n  {\"name\":\"Habaneros\",\"color\":\"#A0522D\",\"story\":\"La gamme d\'entrée — mais chez Partagás, \'entrée\' est relatif. Les Habaneros Short sont les cigares de plaisir quotidien des Havanais eux-mêmes. Courts (42 x 110mm), intenses, à fumer en 20 minutes. La vraie saveur cubaine populaire, sans cérémonie.\",\"force\":\"Medium-Full\",\"wrapper\":\"Habano Claro\",\"vitolas\":[\"Short\",\"Club\"]}\r\n]', '2026-03-18 09:43:40', '2026-08-14 15:26:40', '[{\"source\":\"Cigar Aficionado\",\"score\":93,\"year\":2020,\"vitola\":\"Serie D No.4\"},{\"source\":\"Cigar Journal\",\"score\":94,\"year\":2019,\"vitola\":\"Lusitanias\"}]', '[{\"name\":\"Somerset Maugham\",\"anecdote\":\"L\'auteur britannique décrivit la Partagás Lusitanias comme \'la seule chose pour laquelle je ferais le voyage jusqu\'à La Havane\'. Il en faisait livrer des boîtes à Londres via l\'ambassade.\"},{\"name\":\"Groucho Marx\",\"anecdote\":\"Marx fumait des cigares en permanence sur scène et dans la vie. Il aurait dit : \'Un cigare à ce stade n\'est plus un vice. C\'est une philosophie.\'\"}]', '[{\"type\":\"Spiritueux\",\"name\":\"Armagnac Bas-Armagnac 20 ans\",\"notes\":\"La profondeur terreuse de l\'Armagnac vieillit résonne avec le côté rustique puissant d\'une Serie D. Accord pour connaisseurs.\"},{\"type\":\"Bière\",\"name\":\"Porter irlandais\",\"notes\":\"Surprenant mais redoutable — le café torréfié d\'un Good Things Stout amplifie les notes de cacao de la Serie D.\"},{\"type\":\"Thé\",\"name\":\"Pu-erh vieilli 10 ans\",\"notes\":\"Le Pu-erh fermenté, terreux et profond, est l\'accord thé ultime avec Partagás. Les deux partagent la même complexité tellurique.\"}]', '[\"Partagás Lusitanias Gran Reserva Cosecha 2014\",\"Partagás Serie D No.4 Gran Reserva\",\"Partagás 170 Aniversario EL (2015)\",\"Partagás P Series EL\"]', 'Manufactura Partagás, Calle Industria 520, La Havane — fondée 1845', 'Don Jaime Partagás founded his factory in 1845 in Havana\'s Barrio de los Sitios, on a street that would one day bear his name. At Calle Industria 520, the neoclassical building he constructed has never moved, never closed, never reinvented itself into something unrecognizable. For 180 years it has survived Spanish colonial rule, American occupation, two world wars, a revolution, a half-century of embargo, and the slow collapse of everything around it. It is today the oldest cigar factory still in active production anywhere in the world — a distinction that is architectural, historical, and entirely earned.\r\n\r\nDon Jaime was a restless innovator in an era when most manufacturers simply maintained tradition. He traveled to the tobacco fields himself. He understood that the earthy, powerful profile his factory produced required tobaccos from specific micro-regions of Vuelta Abajo — the deep red soils near San Luis and San Juan y Martínez that impart the characteristic dark cocoa and forest floor complexity that defines the Partagás style. He paid premiums for those leaves when his competitors did not.\r\n\r\nHis most enduring contribution was not commercial but cultural. Partagás was the first manufacturer in Cuba — and possibly in the world — to employ a lector: a professional reader who sat on an elevated platform in the rolling gallery and read aloud to the torcedores throughout the working day. The practice transformed the factory floor into an unlikely salon. Workers heard Zola, Dickens, Victor Hugo, and Marx. They debated what they heard. They requested specific texts. Don Jaime believed that cultivated minds produced better cigars — and the quality of Partagás under his direction supported the theory. La lectura spread to every Cuban factory, then to exiled torcedore communities in Tampa, Key West, and New York, where it survived well into the twentieth century.\r\n\r\nAfter Don Jaime\'s death in 1868 — murdered, the legend says, by a rival — the factory passed through several hands before being nationalized in 1960. The state maintained the address, the workforce, and most importantly the tobacco sourcing. The Serie D No.4, a Robusto measuring 50 x 124mm, became under Cuban state management what it remains today: the global benchmark for full-body cigars. Its notes of bitter cocoa, black pepper, damp undergrowth, and aged cedar arrive in waves across 45 minutes of consistent, escalating complexity. Cigar Aficionado has awarded it scores between 92 and 95 across fifteen consecutive reviews.\r\n\r\nThe Lusitanias — a Double Corona measuring 49 x 194mm — is one of the last great format cigars still produced regularly in Cuba. Ninety minutes in the hand. Five distinct aromatic phases. The 8-9-8 Varnished, sold in cedar boxes with cigars arranged in the namesake pattern, is the house\'s most elegant proposition: a Panetela so narrow it seems impossibly fragile, yet concentrates aromas with an intensity that surprises every smoker who approaches it expecting lightness. These three cigars — the Serie D, the Lusitanias, the 8-9-8 — form a triangle that has defined serious cigar culture for a century and shows no sign of becoming irrelevant.', 'Don Jaime Partagás fundó su fábrica en 1845 en el Barrio de los Sitios de La Habana, en la Calle Industria 520 — dirección que nunca ha abandonado. Es la fábrica más antigua del mundo aún en funcionamiento.\r\n\r\nPartagás fue el pionero de la lectura: un lector leía en voz alta a los obreros durante el trabajo. Esta práctica se extendió por todas las fábricas cubanas.\r\n\r\nSus cigarros son robustos, terrosos, expresivos. Los aficionados a Partagás son fieles hasta el extremo: siempre se vuelve.', 'Don Jaime Partagás gründete 1845 seine Fabrik in der Calle Industria 520 in Havanna — eine Adresse, die sie nie verlassen hat. Es ist die älteste Zigarrenfabrik der Welt.\r\n\r\nPartagás erfand die Lectura: Ein Vorleser las den Arbeitern während der Arbeit vor. Diese Praxis verbreitete sich in ganz Kuba.\r\n\r\nKräftige, erdige, ausdrucksstarke Zigarren. Partagás-Fans sind bedingungslos treu — man kommt immer zurück.', '唐·海梅·帕特加斯于1845年在哈瓦那工业街520号创立了他的工厂——至今从未离开。它是全球仍在运营的最古老雪茄工厂。\r\n\r\n帕特加斯首创了朗读传统：在工作时朗读者为工人大声朗读。这一习俗传遍古巴所有工厂。\r\n\r\n浓郁、有力、泥土气息的雪茄。帕特加斯爱好者极其忠诚——总会回来。', 'أسّس دون خايمي بارتاغاس مصنعه عام 1845 في كاييه إنداستريا 520 بهافانا — عنوان لم يغادره قط. إنه أقدم مصنع سيجار في العالم لا يزال يعمل.\r\n\r\nكان بارتاغاس رائدًا في الليكتورا: قارئ يجهر للعمال أثناء اللف. انتشرت هذه العادة في جميع مصانع كوبا.\r\n\r\nسيجار قوي ترابي معبِّر. عشاق بارتاغاس أوفياء دائمًا — ستعود إليها في نهاية المطاف.', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto 50 x 124mm — is the absolute full-body reference cigar. Earthy, powerful, complex. Notes of bitter cocoa, black pepper, damp forest floor. Smoked in 45 minutes, it does not forgive improper storage. Cigar Aficionado score 93.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"No.4\", \"No.5\"]}, {\"name\": \"Lusitanias\", \"color\": \"#722F37\", \"story\": \"Double Corona format (49 x 194mm), 90 minutes of smoke. One of the few giant formats still regularly produced in Cuba. Named for the ocean liner sunk in 1915. A cigar for solemn great occasions — it tolerates neither haste nor distraction.\", \"force\": \"Full\", \"wrapper\": \"Habano Oscuro\", \"vitolas\": [\"Lusitanias\"]}, {\"name\": \"8-9-8 Collection\", \"color\": \"#5C4033\", \"story\": \"Sold in boxes of 25 arranged 8-9-8. Panetela format (33 x 170mm), the finest ever produced in Cuba. Deceptive lightness: the narrow ring gauge concentrates aromas into unexpected intensity. Beloved by Parisian enthusiasts.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"8-9-8 Varnished\"]}, {\"name\": \"Habaneros\", \"color\": \"#A0522D\", \"story\": \"The entry-level range — but at Partagás, \'entry\' is relative. The Habaneros Short are the everyday pleasure cigars of Havanans themselves. Short (42 x 110mm), intense, smoked in 20 minutes. The true popular Cuban flavor, without ceremony.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Short\", \"Club\"]}]', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto 50 x 124mm — is the absolute full-body reference cigar. Earthy, powerful, complex. Notas de bitter cocoa, pimienta negra, damp forest floor. Fumado en 45 minutos, it does not forgive improper storage. Puntuación Cigar Aficionado 93.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"No.4\", \"No.5\"]}, {\"name\": \"Lusitanias\", \"color\": \"#722F37\", \"story\": \"Double Corona format (49 x 194mm), 90 minutos of smoke. One of the few giant formats still regularly produced in Cuba. Nombrada por the ocean liner sunk in 1915. A cigar for solemn great occasions — it tolerates neither haste nor distraction.\", \"force\": \"Full\", \"wrapper\": \"Habano Oscuro\", \"vitolas\": [\"Lusitanias\"]}, {\"name\": \"8-9-8 Collection\", \"color\": \"#5C4033\", \"story\": \"Sold in boxes of 25 arranged 8-9-8. Panetela format (33 x 170mm), the finest ever produced in Cuba. Deceptive lightness: the narrow ring gauge concentrates aromas into unexpected intensity. Beloved by Parisian aficionados.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"8-9-8 Varnished\"]}, {\"name\": \"Habaneros\", \"color\": \"#A0522D\", \"story\": \"The entry-level range — but at Partagás, \'entry\' is relative. The Habaneros Short are the everyday pleasure cigars of Havanans themselves. Short (42 x 110mm), intense, smoked in 20 minutes. The true popular Cuban flavor, without ceremony.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Short\", \"Club\"]}]', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto 50 x 124mm — is the absolute full-body reference cigar. Earthy, powerful, complex. Noten von bitter cocoa, schwarzer Pfeffer, damp forest floor. Geraucht in 45 Minuten, it does not forgive improper storage. Cigar Aficionado Score 93.\", \"force\": \"Full\", \"wrapper\": \"Habano Colorado Oscuro\", \"vitolas\": [\"No.4\", \"No.5\"]}, {\"name\": \"Lusitanias\", \"color\": \"#722F37\", \"story\": \"Double Corona format (49 x 194mm), 90 Minuten of smoke. One of the few giant formats still regularly produced in Cuba. Benannt nach the ocean liner sunk in 1915. A cigar for solemn great occasions — it tolerates neither haste nor distraction.\", \"force\": \"Full\", \"wrapper\": \"Habano Oscuro\", \"vitolas\": [\"Lusitanias\"]}, {\"name\": \"8-9-8 Collection\", \"color\": \"#5C4033\", \"story\": \"Sold in boxes of 25 arranged 8-9-8. Panetela format (33 x 170mm), the finest ever produced in Cuba. Deceptive lightness: the narrow ring gauge concentrates aromas into unexpected intensity. Beloved by Parisian enthusiasts.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"8-9-8 Varnished\"]}, {\"name\": \"Habaneros\", \"color\": \"#A0522D\", \"story\": \"The entry-level range — but at Partagás, \'entry\' is relative. The Habaneros Short are the everyday pleasure cigars of Havanans themselves. Short (42 x 110mm), intense, smoked in 20 minutes. The true popular Cuban flavor, without ceremony.\", \"force\": \"Medium-Full\", \"wrapper\": \"Habano Claro\", \"vitolas\": [\"Short\", \"Club\"]}]', '[{\"name\": \"Serie D\", \"color\": \"#8B2500\", \"story\": \"The Serie D No.4 — Robusto